/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070122-6","meetingId":"h19-cm01","date":"2007年1月22日","dateIso":"2007-01-22","committee":"区民委員会","time":"午後１時１８分～午後２時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問","question":"区が主催者になって協賛の方々に入っていただいて、協力的にいろいろなものを進めていくということでお願いをしているんですけれども、その協賛の皆さん、積極的に向こうから呼びかけがあったのかということと、ほかにもさまざまな企業がいろいろやっているんじゃないかと思うんですけれども、そういう活動みたいなものはどんな扱いになっているのでしょうか。","respondent":"田中環境課長","answer":"こちらの環境大賞の企画につきましては、環境大賞推進会議等が設置してありますが、そちらの委員のほうで企画検討する中で、他の自治体等ではライオンズクラブやロータリークラブが環境講座等の支援を行って、普及活動をやっているということがありますので。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"特に個人の方が１人いらっしゃるということですが、うれしいというか、そんな感じがしたので、そういう個人の方たちのところも教えてください。","respondent":"田中環境課長","answer":"全体的にはリサイクルですとか、環境学習、教育の部分が多いようです。企業については、ＩＳＯの１４００１シリーズの企業の中での取り組み等の報告があるということで、全体的には環境学習ですとか教育、リサイクル関係が多いということになっております。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"今までの学習だとか、教育だとか、リサイクルというと、またちょっと個人の方の活動されている内容と違うということでは、非常に興味を引くという印象を持ったんですけれども、個人でできることですから、まだまだ最初は限られた範囲なのかなと思っているんですけど、あの辺にジャコウアゲハチョウを育成するということは、今の現状、あの辺を思い浮かべると。","respondent":"田中環境課長","answer":"今後とも次年度に向けては継続的にもっと大きく広がったような形でやるということで、東京電力ですとか、品川清掃工場ですとかも含めまして、打ち合わせ等を行っているところです。","id":"exchange-003"},{"speaker":"大沢委員","kind":"意見","question":"応募の方法なんですけれども、企業に対してはどのような働きかけをされたのかということが１つ、それから、２２団体と１個人ということですけれども、相対的に本区の企業、学校その他の団体で、すべてを見回して、２２という数字をどのように区はとらえていらっしゃるのかということが１点、もう１つ、つけ足しになっちゃいますが。","respondent":"田中環境課長","answer":"ダイジェスト版ということではなくて、ＣＤ等に焼いた形であります。ただ、うまい形で普及していったり簡単に見れるという形にはなっていないので、いろいろなこういういい活動がビジュアルな形で見れるように、今後ライブラリーの整備に努めていきたいと考えております。","id":"exchange-004"},{"speaker":"大沢委員","kind":"意見","question":"課題の中で企業の立場ということで、考え方、取り組み方は違うと思うんですけれども、企業の立場に立つものを進めていく上で、どのような工夫をされるのか、お考えがあったらお聞かせください。","respondent":"田中環境課長","answer":"その面では、そういう新しい成熟した形の企業の取り組みも積極的に取り上げるということで、大賞の意義等をＰＲしていきたいと考えております。","id":"exchange-005"},{"speaker":"本田委員","kind":"確認","question":"応募の数が少ないなというのが実感としてあるんです。今、いろいろ課長のお話を伺ったところでありますけれども、品川区内に団体、個人、こういう取り組みをやっているというのはもっとたくさんあると思うんですけれども、非常に多くの区民に知らせていくという点では、受賞したところだけではなくて、応募したところの内容も知らせる。そういうところをもう１度確認したいと思います。","respondent":"田中環境課長","answer":"受賞した団体ももちろんそうですが、受賞していない団体についても紹介していくという対応をしていきたいと考えております。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問・要望","question":"こういう講演会も大変結構ですし、あと展示会をやったり、いろいろ区民に向けて発信をして、いろいろな形で多くの区民が参加する、団体が参加する、こういう状況を全体としてつくっていくと。今、区が後押しをしているわけですけれども、民間サイドからも一緒になって動きを旺盛に広く展開していく、そういう地域づくりをこの面でも進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"林（和）副委員長","kind":"意見","question":"説明が終わりました。ただいまの説明にご質疑等がございましたら、ご発言を願います。１つ、環境記者の登録者が１７名で、エコサポーターの登録者が３名ということですけれども、それぞれ目標といいますか、どの程度の人たちを登録していこうとしているのか。","respondent":"田中環境課長","answer":"講座等の参加者にサポーターですとか環境記者というのがありますよということを訴えて、徐々に広げていく形です。ただ多くの情報が集まるためには、まんべんなく区内やいろいろな分野に環境記者がいることが理想ですので、もっと大幅に広げていきたいとは思っております。","id":"exchange-008"},{"speaker":"林（和）副委員長","kind":"質問","question":"ただいま地域活動課長から原小学校跡施設の利用計画の骨子について、口頭での報告がございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"２つ目は、町会長の会議にお出かけになって情報提供しているというお話ですけれども、近隣の住民の方々との理解というのは、どの程度進んで、どういう状況に至っているのかどうかも含めてですね。","respondent":"田村地域活動課長","answer":"そちらの人たちが来年度の事業をどうするかというようなご議論で、実際に運営にあたっているということですので、これから働きかけていくときには、やはり町会とか地区委員会だとか民生委員会だとか、既存の組織がありますので。","id":"exchange-010","title":"町会・自治会支援"},{"speaker":"南委員","kind":"質問・要望","question":"施設的に必要なバリアフリーだとかそういうのは、もちろんこれから欠かせない内容ですから、取り入れていただけるんだろうと思っているんですけど、改めてそのことも含めてお願いしたいと思います。","respondent":"田村地域活動課長","answer":"バリアフリーについては、まだ予算編成の時期なんですが、当然集会所と同様の、ほかの地域センターと同様のバリアフリーは、財政的な限界もありますけれども、取り入れてやってまいりたいと考えています。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"よくテレビでいろいろなお店が、例えば銀座のどこどこで何を売っているとか、そんな紹介があると、わりとわーっと行くとかと言われるんですけど、品川区もこれが３回目だと思うんですけれども、たまたまこの間、この取り組みじゃなかったと思うけど、どこかのテレビ局が、荏原だったかどこかのラーメン屋さんを紹介したら、すごい行列で。","respondent":"金子産業振興課長","answer":"土曜日ですので、周辺の商店街もあいていますので、その辺のところはまち歩きに参加される方にごらんいただきながら、アピールとまではいかないとは思いますけれども、ご案内をされる予定にしていると聞いております。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"予算をつければいいとかつけてほしいという思いで言っているつもりじゃないんですけれども、しかしイベントをするときにそういう経費的なところに負担感があるという話も聞こえてきているので、やっていくということと品川区のそういう応援を受けて、商店街の活性化をしていきたいというところがマッチして、客の入りが多くなればいいと思っているんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"林（和）副委員長","kind":"質問","question":"１１月２７日の委員会終了後の議事録をもとに調製させていただきました。このような形で議長に報告したいと思いますけれども、よろしゅうありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/593414?Template=document&Id=2480#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":15428,"voices":41}},{"id":"h19-20070122-7","meetingId":"h19-cm01","date":"2007年1月22日","dateIso":"2007-01-22","committee":"厚生委員会","time":"午後１時０３分～午後４時２８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回は、午後５時から午後１０時ということでの応急診療体制ということなんですけれども、土曜日は午前中はやっているところが多いと思うんですが、午後は休みのところがほとんどなんじゃないかなと思うんですけれども、そこの土曜日の午後についてはどう考えるのかということと、あと、この予算についてどれぐらいになるのかということだけ教えてください。","respondent":"谷田部健康課長","answer":"土曜日午前中に診療しているところはご案内のとおり多いんですが、午後も診療しているところがございまして、ですから、全くゼロというわけではなくて、午後も対応できていると。","id":"exchange-001"},{"speaker":"三村委員","kind":"質問","question":"この案内をするときに、午後やっている病院、数少ないけれどもこういう病院は営業していますよとか、やっていますよみたいな案内なんかもあわせてできるのかどうか。もしできるようだと、そういったことも広報していただければ、知らずに受けられなかったという方がいなくなると思うので、その点について１点だけお伺いできればと思います。","respondent":"谷田部健康課長","answer":"東京都福祉保健局で運営しております、２３区も協力して運営しているんですけれども、「ひまわり」というのがございまして、これはインターネット、電話等で連絡、問い合わせしていただければ、あいている診療所の地図だとか、住所だとか。","id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"確認で、もう一度、ちょっと聞き逃したと思いますのでもう一度確認したいんですが、実施方法で「当分の間」というところですが、３月までは個別の診療所でしていただくと、３月以降は荏原医師会、品川区医師会のところでできるということなのかということと、それから、品川の現状として、小児科医というのは増えているのか減っているのかというところの現状をお聞きしたいということ。","respondent":"谷田部健康課長、倉橋品川区保健所保健サービス課長","answer":"それで、私どもはなるべく軽易な病気については地元の近いところで対応できればそちらのほうで対応して、それからあと、救急体制でそちらのいわゆる専門的な医療が必要な分については、それは二次。ただし、大学病院等もありますので、ほかの区に比べれば、若干条件はそれほど厳しくないかというふうな認識をしております。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"認定こども園ということでの報告が初めてなので、いろいろわからないことがありまして、教えていただきたいと思いますけれども、１つは、この認定こども園ができることで、品川区の保育園がどう変わっていくのかということを教えていただきたいと思うんですけれども、二葉すこやか園とか、のびっこ園台場、それからぷりすくーる、こういうところもどうなっていくのかということと、また、区立の幼稚園。","respondent":"高橋幼保一元担当課長","answer":"公立幼稚園で預かり保育をしたのも１つのものだと考えているところですが、今回、幼稚園、保育園が就学前の教育保育のプログラムを検討しているのもその１つであると思って、今後につきましては、幼児教育に特化した形で幼保一元化も進めていく方向性も考えているところです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"長時間利用のほうは２０対１、四、五歳は３０対１ということなんですけれども、短時間のほうは、３歳から５歳までは３５対１ということになるということなんですけれども、先ほどのお話だと、共通利用時間のところは３５対１というふうなことでの説明だったかなというふうに思ったんですけれども、ということになると、幼稚園が開いている短時間の間というのは、子どもたちは３５対１で。","respondent":"高橋幼保一元担当課長","answer":"先ほど長時間の部分でも３５と言いましたけれども、それは幼稚園部分、３歳以上の１つの集団としてその部分で見るときには、３５人ぐらいまで保育というか、預かり保育というんですか、長時間保育をしても可能ですよです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さっきもう１つお願いしたのは、地方裁量型だと、今、品川区でも認証保育園というのがたくさんできていると思うんですけれども、それが認定こども園になっていくのか、なっていくとしたらどう変わっていくのかということを教えてください。","respondent":"高橋幼保一元担当課長","answer":"そうすると、逆ピラミッド型になって、０歳からの就学前の子どもたちの教育保育が一貫してできるかなというところも１つ問題が出てくるということもありますし、今の時点では、１１月、この東京都の基準が出る前の調査の中でも。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"短時間というのは４時間ということなんですけれども、そうすると、長時間保育の子どもたちも、短時間の４時間の間については３５対１ということで保育がされるということになるわけですよね。そういうわけではないんですか。","respondent":"高橋幼保一元担当課長","answer":"幼稚園・年齢区分型につきましては、認証保育所というか、認可外の保育所は０歳から３歳まで、３歳から５歳については、保育に欠ける、欠けない子を一緒に見るということで、その部分で、幼稚園でありながら保育園機能も持たせるということでは、預かり保育等を実施するです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"前は２０人、私の子どもを預かっていただいているときなんかは、２０人に多分複数の担任というふうなことでされていたのが、今は２０人を１人で見ているということそのものも大変だと思うんですけれども、それが３５人を１人で見るとなると、本当に大変な状況になるんじゃないかなというふうに思うんですけれども、今、小学校でも、東京はまだ３０人学級になっていませんけれども、３０人学級にしていこう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"はい、わかりました。この都の認定基準の説明書の裏のページなんですけれども、６番の子育て支援の省令に定める子育て事業のうち２つ以上を実施ということで書かれているんですけれども、この省令に定める子育て事業というのが具体的にどんなものがあるのかということと、それから、それの財政的な支援というのがあるのかどうか、このことについてだけ教えてください。","respondent":"高橋幼保一元担当課長","answer":"それと、補助金のことにつきましては、認定こども園子育て支援補助を新設するです。この内容について細かいところは、きょうの説明等を聞かないとわからないところですが。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新しく出てきたところでこれから検討していくということで、細かなところはまだよくわからない部分がたくさんあるということですので、またいろいろわかったらご報告いただきたいというふうに思いますけれども、品川区の保育の水準を下げない方向でぜひ取り組んでいただきたいということで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、この認定こども園という認定をされることが、今後の保育に関してどういう影響があるか、要は、対外的にです。というところになると、ちょっと不明な点が多いなと。それと、この中で職員の資格の中で、３歳から５歳児、幼稚園教員免許、それから保育士の資格、これは非常に大きな視点だと思うんですね。その辺の考え方、今の時点で結構ですので教えていただければと思います。","respondent":"高橋幼保一元担当課長、小林保育課長","answer":"職員の資格については、保育課長からお答えします。保育士につきましては、幼稚園教諭の資格の試験なんかも始まりまして、まだまだ数は多くございませんが、今年度につきましては、十数名受験しまして２名合格というような形も出てきておりますので。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり認証保育所、それから私立幼稚園も補助の対象になると思うんですね。考え方がやはりどんどん変わっていくだろうというふうに思っています。私立幼稚園といいますと、私立ですからそれぞれのところで教育方針等々が違う状況がありますので、そこを整備する、統一にする必要はないのかもしれませんけれども、やはり考え方の統一はやはり区と一緒に今後考えていただきたいなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"提案","question":"都の基準が明らかにされたわけなんですけれども、この間、幼保一体化のさまざまな形でご提案をされているんですが、現行の保育園、また現行の幼稚園の水準を下回らない、子どもたちにとってよい環境を保ってほしいということを、この間、何回か申し上げてきたんですけれども、区の検討についてはこれからさまざまということなんですけれども、ちょっとこの基準のところで。","respondent":"高橋幼保一元担当課長","answer":"３点目の子育て支援についての施設の基準とか、その人員配置については、特には示されていない部分で、現行の中で全く１日やらなくてはいけないというものでもないと思うんですけれども、その部分については、区としてどうするかということが問われる部分でありますので。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"認証保育所に準じているような中身で今の保育室のところと部屋の平米数のところも出ているということなんですけれども、これは都の基準ですけれども、待機児の解消というところは１つ大きなねらいではあると思うんですけれども、この辺は、私、前から言っていますけれども、認証でいいと思うのではなく、やっぱり今の認可のところに少しでも近づけて。","respondent":"高橋幼保一元担当課長","answer":"その部分について、区としてどうであるかということは、検討する、間に入ることは可能になっていますので、その部分も今日の事務レベルでまた聞いてくる部分かと思いますので、わかりましたらまたお伝えする機会がありますので。","id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"そういった面で、今後どのくらいの利用負担になるかはわかりませんが、認証保育園なんかは直接契約のところを見ると、実際には認可のところでもかなり負担が大きいというところでは、利用者にとってどうなのかなという視点でもぜひ区のほうでとらえていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何点かお聞かせください。特定施設入居者生活介護、これは先ほど西五反田のケアホーム、また、都南病院の跡地のケアホームと同様のものだということで説明がありましたので、安心の住まいではなくてケアホームが有料老人ホームと同じような、そういうケアホームということでいいのか、それを１つ確認をさせてください。","respondent":"蓼沼高齢福祉課長","answer":"有料老人ホームとは、またこの特定入居者生活介護、いわゆる区ではケアホームと言っておりますけれども、それとはまた別のものだというふうにお考えいただければというふうに思います。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"有料老人ホームも、この特定施設入居者生活介護ということで介護保険のほうから介護報酬が支払われているというところでは、そのところでは同じくくりになるんだと思うんですけれども、私は改めてケアホームが今、西五反田にあって、入居待ちをされている方は３０名ということでお聞きしましたけれども、都南病院の跡地に２９のケアホームができるというふうなところで。","respondent":"蓼沼高齢福祉課長","answer":"今後のそうした高齢者、団塊の世代が高齢期を迎える中でさまざまなニーズに対応していくということの見込みといいますか、そういうニーズが予測される中で、こういった一定の施設整備をしていく必要があるだろうということで計画を進めているところです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今まで住民の意見がどこで聞かれたのかということと、それから、これから地域に対しての説明をどうしていくかということを１つお聞かせいただきたいのと、あとは、私はやっぱりこの問題については、この間、部長のほうからも、都南病院跡地も西五反田に比べたらリーズナブルな利用料でというふうなことで、２０万円ちょっとというふうなことでお話があったと思うんですけれども。","respondent":"蓼沼高齢福祉課長","answer":"ですから、そういう地域住民説明会については、今後のスケジューリングの中で対応していきたいというふうに考えております。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて、ここの今回の施設に関しては、民設民営方式ということでなっているんですけれども、なぜ公設で指定管理者という形でなくて、民設民営というふうにされるのか、公設民営と民設民営の違い、ここら辺についてもお聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"特に高齢者施設の特定施設につきましては、今回、新しい枠組みで高優賃というものを活用しようというふうに考えておりますが、これにつきましては、いろいろと交付金の関係ですとか、あるいは確保する住居の戸数等々について一定のメリットがあるです。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都南病院の跡地は公設民営で指定管理者という形にしますよね。それが今回は民設民営というのの、その地方自治体ではできない、社会福祉法人でないと設置できないというのが、都南病院の跡地ではできて、ここではできない、そこら辺のところがちょっとよく理由がわからないので、もうちょっと説明をしていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"それに当たって活用する制度について効率的でさまざまなメリットがあるものはどういうものがあるだろうかと検討した中で、この改修型で交付金が受けられて、そして施設整備についても、これは住宅という類型になりますので。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、こちらの応募要項のほうを見ると、その１ページのところの応募資格というところに、幼保一元施設では、社会福祉法人以外の株式会社も可として別法人が提携して運営する場合は云々というふうに書いているんですけれども、ということは、ここのところで、両方とも運営実績を有する社会福祉法人でなくても、社会福祉法人が株式会社と連携をしてやっているようなところでも可だということになるのか。","respondent":"蓼沼高齢福祉課長","answer":"ただ、そういう別法人が組む場合は、運営責任を明確にしていただくということで考えております。ただ、具体的にこういうような法人、区内でも１つ品川総合福祉センターが特養と保育園を運営しているという、区内でもそういう法人があることはあります。","id":"exchange-021"},{"speaker":"三村委員","kind":"質問","question":"この１３ページの審査の流れのほうを見しますと、公募の発表があって、公募の説明会、見学会までの間が４日間しかないんですけれども、とても短いように感じるんですけれども、この説明会、見学会のほうに出席できなくても、きちんと説明だとか、情報提供が受けられるのかというのと、あと、今、品川区内に限っていない、都内に限っていないというお話がありましたけれども、広く公募を呼びかけるのであれば。","respondent":"蓼沼高齢福祉課長","answer":"ただいまのご指摘です。今週末に公募説明会、現地見学会を予定しておりますが、これは現地が今、実際、学校事業をしている学校ということで、土曜日ですとか、日曜日に設定せざるを得ないということで、学校側と調整した結果、この２７日という設定になったものです。","id":"exchange-022"},{"speaker":"三村委員","kind":"質問","question":"ぜひよろしくお願いいたします。その際に、質問が来たら情報提供するというのではなくて、こういった説明会に来られない場合でも十分な情報提供をしますよということもきちんと広報していただければなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"西本委員","kind":"提案","question":"運営費等と、まだまだ決まっていないとは言いつつも、どういったような補助金がおりたりとか、どのぐらいのレベルで運営をしていっていいのかというところが、多少不明瞭なところがあるので、ちょっとわかりにくいのではないかなというところが１点と、それからあと、この前の報告の中で、認定こども園というのがありまして、私たちの中でも認定こども園というのは何ぞやというところがあるものですから。","respondent":"蓼沼高齢福祉課長、小林保育課長","answer":"幼保一元施設のほうは、子育て支援基盤整備補助金の活用ということで、活用予定の補助金も名称を明記していますので、一応こういう要件を示して、一定程度、後は自己負担金、これがどのくらいなのか。したがいまして、今回のご説明の中では、認定こども園保育所型を志向した認可保育所という形で、基本的にスタートの最低の要件から言うと認可保育所ということが前提になっております。","id":"exchange-024"},{"speaker":"西本委員","kind":"提案","question":"いろいろ提案を受けてというところで、本当にその事業所が公募に当たってきちんとできるかどうかの判断、もちろん選定委員会がありますから、そこの中での判断になるかとは思うんですけれども、どういう点を裏取りをするのかなというところ、本当に実績等々をどういうふうに見ていこうとしているのかなというところと、あと。","respondent":"蓼沼高齢福祉課長","answer":"済みません、答弁が漏れまして。公表につきましては、先ほどご説明させていただきましたとおり、決定した事業者以外の提案内容については公開しないということにしております。やはり提案内容、豊かな発想で自由に提案をしていただくです。","id":"exchange-025"},{"speaker":"西本委員","kind":"提案","question":"というのは、やっぱり広い意味で考えたときに、確かに企業の企業秘密というところはあるかとは思いますけれども、私たちもこれから品川区の政策を考えていく上では非常に参考になる点だと思いますので、これは要望になりますけれども、きちんとできる限り報告をしていただきたいなというふうに要望して終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私もちょっと議会がどうかかわれるかというのが非常に気になっているところがあるんですけれど、この流れからすると４月に決まってしまってからここの事業者ですよということが出てくるだけなのかなと、ちょっとその辺をもう１回確認をさせていただきたい。そこに対するモデルケースとして考えてしまっていいのか、そこまで考えていませんよというのか、その点をちょっとお答えいただければと思います。","respondent":"蓼沼高齢福祉課長","answer":"選定についての公平性の確保等といったところですので、これまでも高齢者の関係で言いますと、亀田邸ですとか、都南については、必要なときに委員会のほうに報告をしてまいりましたけれども、この原小の件につきましても。","id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"どれだけ本当に、行政側のチェックもそうですけれども、議会が、選定をするに当たってもそうですが、選定された後の運営についても、どれだけチェックができるのかというところにおいて、この民設民営のところが今の制度より、ご答弁を聞いていると後退をしてしまう、チェックができないんじゃないかと、とても不安なんですけれども、ここのところが今回この問題の最大のところではないかなと思うんですが。","respondent":"蓼沼高齢福祉課長","answer":"この原小跡地の件につきましては、先ほど申し上げましたように、これまでの指定管理者の選定あるいは選定結果、施設整備計画等についてご説明申し上げたような形で議会のほうにも報告をしていきたいというふうに思いますし。","id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"不二家の安全衛生の問題もそうですけれども、行政が今まで行っていた事業を民間に出していくに当たってのすごい慎重な部分がすごく今、求められて、問われていると思うんですが、私はこの民設民営という、こういう形で出して、安易にこれを認めていくわけにはいかないんじゃないかなと思っているんですが、いかがでしょうか。","respondent":"蓼沼高齢福祉課長、小林保育課長、木下福祉高齢事業部長","answer":"ただ、民設民営と申しましても、地域活動交流拠点、西側の別棟の校舎、それから屋内運動場については、これは公設民営というんですか。もちろん品川の子どもを預かっていただいておりますので、預かる場合にはこういった形でやっていただきたいよというお話もありますから、そういった意味で。いわゆる今回の施設につきましては、民設民営ということでありますけれども、そういう視点で申し上げると。","id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"提案","question":"何かこの辺は従来とは全く違うという認識を私は持っているんですが、その辺を１つお答えいただきたいのと、あとは、今後、指定管理者としての議会での議決はないけれども、報告をするのでご心配ありません、ご安心くださいとあったんですけれども、私は指定管理者でも不十分だと思っているのが、より一層緩和をされた中身であるという認識を持っていますが、その辺についてはいかがでしょうか。","respondent":"小林保育課長、木下福祉高齢事業部長","answer":"ただ、今回既にご説明させていただきましたように、いろいろな事業者から豊富な提案をいただくということからすると、いわゆる足かせになるような要件はできるだけ差し控えて、広く参加していただく趣旨から言うと。あと予算も含めまして、議会の方々のご意見をちょうだいしながら進めていきたいと思っているところです。","id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今回の中身は、決して安心できる中身ではないと思っています。ぜひ報告はきちんとしていただきたいし、意見も言っていきたいなと思っています。保育園のところは、公的な保育を守るという立場においては、品川区、株式会社を取り入れることは本当にやめていただきたい。これは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２点ほどになると思いますけれども、設立委員の方１１名というのは、どのぐらいの年代の方が委員になっていらっしゃるのかが１点と、それから、具体的活動という中に、カフェの運営、これ、図面もありますけれども、これは一般開放するという意味なんですか。それとも中の方だけでここの部分を使うのか。","respondent":"冨岡高齢事業課長","answer":"団塊の世代を中心に上下、ヤングシニアと言われる世代の方たちに委員となっていただいております。それから、カフェですが、これは靴を脱いで上がっていただくような仕組みにはなっておりますけれども、一般の方にも公開をする予定です。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これを運営の１つの拠点にして考えるのだったら、採算ということを考えるといけないかもしれないけれども、あんまり採算ベースはよくない、中へ入ってこないよという気もしましたので、何かうまく方法をとれないのかなと。せっかく進めていく上で、皆さん、やりやすく有効に使ってもらいたいなと思いますので、その辺、検討だけしておいていただければということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"木下委員","kind":"質問","question":"自分の趣味・興味を地域デビュー・社会参加へと結びつけると、地域というと、いわゆる自分たちの感覚ですと、自治会ですとか、町会ですとか、そういう組織じゃないかなというふうに思っておりますので、そこら辺の何か具体的な、例えば参加ですとか、タイアップですとか、そういう考え方を持っていらっしゃるのかどうなのか、それとも、なければそういう自治会だとか、町会だとかとはまた違って。","respondent":"冨岡高齢事業課長","answer":"それが１点です。それから、これは将来的にはコンピューターの部分でさまざまな会員制の掲示板を開いたりする予定ですので、また新しい形の地域での展開というのをこれから試みてみたいと、その意味では、ラボという意味で使わせていただいている、そんなようなところです。","id":"exchange-034"},{"speaker":"木下委員","kind":"質問","question":"特に今のところは考えていらっしゃらないと。ただ、将来的にはそういう形でオープニングに町会の方々も呼ぶみたいに、何かタイアップして発展できればなというふうに思っていらっしゃるということで理解してよろしいでしょうか。","respondent":"冨岡高齢事業課長","answer":"先々につきましては、これはもちろん自主的な団体ですので、区がどうこうということではございませんが、そういうふうな可能性については、あるということもあり、また考慮するように案内をしていきたいと考えています。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"実際の運営についてお聞きしたいんですけれども、自主事業、それから区の委託ということで、この中の自主事業の中に筋トレ卒後教室というのがあるんですが、これはどなたがどういうふうにやるのかなと。","respondent":"冨岡高齢事業課長","answer":"それからもう１つは、いきいき脳の健康教室の関連ですけれども、このいきいき脳の健康教室につきましては、まず参加者の方と、それからアシスタントのサポーターの方が対話をしながら行っておりますが、その場所につきましては、例えば山中小の山中いきいき広場でありますと。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、資格をとるということで、今お聞きしましたけれども、それなりの資格といいますか、経験をきちっとしませんと、逆にけがが多くなったりとか、寝込んでしまったりとか、腰を傷めたりということがありますので、それを十分に配慮していただきたいなと思っています。そういう形をとられるのでしょうか。そこの会員という意味がちょっとよくわからないんです。","respondent":"冨岡高齢事業課長","answer":"その資格で。つまり、山中いきいき広場のほうにお願いをしているという形です。あるいは、シルバー人材にお願いをしていただく。そういう委託です。会の教室の運営につきましてはお願いをしている。それと同じような形で運営をお願いしていくです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"そうすると、山中の場合には、運営している人が例えば自治会、町会とかにお願いをして、ボランティアを募っているということなんでしょうか。そういうことであればそれで構わないんですけれども、どういう形で委託していて、だれが何をするのかよく見えないんです。","respondent":"冨岡高齢事業課長","answer":"説明不足で申しわけございません。いきいき脳の健康教室ですけれども、参加者の方が、サポーターというボランティアの方、これを区でお願いをして、その方と話をしながら教室を進めていくということが１つあります。","id":"exchange-038"},{"speaker":"三村委員","kind":"質問","question":"５番目の活動の中に、分野別パソコン講座と初心者向けパソコン教室というのがあるんですけれども、こちらのパソコン室のほうなんですけれども、こういった事業以外に、あいた時間帯や何かは、地域の方への貸し出しだとか、こちら、サロンのほうに子連れのお母さんたちが来られるということだったんですけれども、日経新聞のほうで子育て介助というところで、そういうお母さん方のパソコン教室みたいな。","respondent":"冨岡高齢事業課長","answer":"最初に、やはり教室を中心にここは進めてまいりたいと考えています。","id":"exchange-039"},{"speaker":"三村委員","kind":"意見","question":"こういうパソコンがある程度あって、何かで借りられるスペースというのが、結構品川区内にはないということだったので、ぜひそういう、ここのシニアネットだけが占有するのではなくて、もちろん講座だとか、委託事業のほうを優先というのは当然なんですけれども、あいた時間帯については、そういったところへもぜひ貸し出しができるようにご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"三村委員","kind":"意見","question":"それは別に外国人だけではなくて、知的な障害がある方に対しても、平仮名のルビが振ってあるだけで全然理解度が違う。そのためにはなるべく多くのものに平仮名を振ってほしいなということで、ぜひご検討していただければと思います。","respondent":"西島障害者福祉課長","answer":"今のご指摘にもございました振り仮名つきにつきましては、広報の今のスペースの中で振り仮名を振ってどれだけ読めるのかという、読まれる方が、高齢者の方もいらっしゃいますので、字の大きさ等いろいろな課題がありますが、大変貴重なご意見をいただきましたので。","id":"exchange-041"},{"speaker":"西本委員","kind":"確認","question":"非常にこの骨子、きっちりと書かれていて、これが現実的になってくると非常にうれしいなと思いました。そこで１点確認したいのは、６ページの療育支援ネットワークの当面の支援体制、「当面」とついているんですが、この当面というのは、１０年間の骨子の中でどの範囲を言っておられるのか、最終的なところの像みたいなもの、イメージみたいなものがあるのかどうかお聞きしたいと思います。","respondent":"西島障害者福祉課長","answer":"この案をつくっていく過程の中ではさまざまな議論もございまして、将来的な、ここにはちょっと載せ切れなかったんですが、将来的な構想みたいなものも検討はしています。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"非常にここのところが気になっていた部分なんです。多分に制度化されていない部分が多くあって、ただ、しっかりとやっていただきたいなという部分がありましたので、今後いろいろな動きに合わせて積極的に品川区は取り組んでいただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この障害基本計画と基本方針をつくるに当たってのニーズ調査とか、障害者の実態調査とか、そういうことはされているのかということを１つお聞かせいただきたいのと、それと、これを見ると障害者のケアマネジメント体制の整備というのが基本的方向の１番に挙げられているわけですけれども、それでこれが具体的にどうなっていくのかというのがちょっとイメージがつかないので教えていただきたいんですが。","respondent":"西島障害者福祉課長","answer":"ただ、いわゆるケアマネジメントの手法というものはとってございませんでしたので、このケアマネジメントのポイントは何かといいますと、まず本人の意向を尊重しながら。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、ケアマネジメントという点では、今のお話ですと、関係機関が集まって集団でカンファレンスみたいな形もしながら、その人に対してどういう対応が一番適切なのかということで人生を踏まえたような形での対応をしていくという、そういうのが一人一人の障害者の方に対してされていくということの体制が、この障害者生活支援センター、家庭あんしんセンターの中にある。","respondent":"西島障害者福祉課長","answer":"この体制をどうするかということは、１つには来年度以降の計画になりますので、来年度以降、どんな体制でやるかということをあまり踏み込んでお答えしますと、来年度予算編成との絡み等も十分具体的に出てくるお話ですので、ここにつきましては。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ニーズ調査に関しては、私は区としては一人一人に対応されてつかんでいるというのは確かにあると思うんですけれども、声に出せないところでかなりの要望、ニーズがあると思うんですね。そういうようなところでは、ぜひそういうのを改めてこの制度が変わったというところで把握して、それを政策に生かしていただきたいというところで、これは要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"２週間ですよね。２月１日の広報でお知らせするとちょっと聞いたんですけれども、せっかくのパブリックコメントの機会なので、ぜひもうちょっと延ばして、しっかり意見を聞いていただきたいなというのが１点と、あと、きょうは骨子なんですけれども、これからの計画をつくっていく間に、わかりやすく数値目標とかが入れられるのかどうか、ちょっとその辺をお聞かせください。","respondent":"西島障害者福祉課長","answer":"パブリックコメントですが、障害者基本計画はずっといろいろなことで検討してまいって、少し遅れぎみになった関係で、今年度中に作成ということになりますと、ここ２週間がいっぱいかなと、このパブリックコメントを受けて。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/443219?Template=document&Id=3166#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":61591,"voices":140}},{"id":"h19-20070122-8","meetingId":"h19-cm01","date":"2007年1月22日","dateIso":"2007-01-22","committee":"建設委員会","time":"午後１時０４分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","topics":[{"id":"topic-01","title":"の１番を聴取いたします。(1)の八潮北公園野球場の早朝利用の開始","agenda":"の１番を聴取いたします。(1)の八潮北公園野球場の早朝利用の開始","exchanges":[{"speaker":"井上委員","kind":"質問","question":"質問です。青空野球場の代替ということで、返還に伴って八潮北公園野球場を早朝利用ということなので、これはずっとこのまま継続していくものなのかということと、それから今度新しく整備されたところのグラウンドができて、多目的広場ができたときに、またこれが変更するのかというところを。","respondent":"藤田道路公園課長","answer":"八潮北公園野球場につきましては、早朝利用については継続して行っていきたいと考えています。新たな品川南埠頭にできます公園につきましては、詳細についてはこれから利用時間等の検討を行うものですが、当然、早朝利用等も視野に入れながら検討を進めていきたいと考えています。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"こういう状況になる前に、八潮北公園野球場のところの早朝の利用の要望とか、そういうのはなかったのか、ただ単に向こうがなくなったからこれを拡大したという考え方なのか、これの方向を変えるに当たっての考え方はどういうことでしょうか。","respondent":"藤田道路公園課長","answer":"ただ、今回の青空野球場の件が１つの契機になったということは、それは事実だと考えていますので、利用者ニーズを今後きちんと把握する中で、その声にこたえられるよう進めていきたいと考えています。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"１点、ニーズがあったということは把握していたということで、どういうニーズが、もっと早くできたとか、実情を区民の方に聞いていないわけですけれども、本来であれば、こういう状況でなくても拡大ができたものなのか、相当困難であったものなのに今回すごく頑張ってやったんですよということなのか、そこのところ、本来であれば区民のニーズをもっと反映できることが。","respondent":"藤田道路公園課長","answer":"そういった形で需要と私どもの維持管理のための方策、その辺をあわせて考えていく中で、今までは青空野球場における推移を見守ってきたです。","id":"exchange-003"},{"speaker":"藤田委員","kind":"質問・要望","question":"もう１点は、早朝の割引というのはあるのかないのか、その辺、ないんだったらない理由ですよね、おそらくそういうのを我々は町中で言われるんじゃないかと思うんですけれども、その説明、もしできれば教えていただきたい。","respondent":"藤田道路公園課長","answer":"それと料金の関係ですけれども、私ども今回の４月から１１月ということで早朝利用を開始するわけですけれども、その中での料金については従来の料金と同じということで、２時間で１,５００円という形で計画をしているものです。","id":"exchange-004"},{"speaker":"藤田委員","kind":"質問","question":"早朝の割引はしませんよということでよろしいんですかね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"地域の方々は、今まで３面あったものが、これまで一定の努力もあるという一面で、都から南埠頭公園ですか、お話がありましたけれども、何とかもう１面できないものかと、そんなご相談も伺っていますので、今時点での、この早朝利用、これはこれで１つの努力なのかもしれないけれども、引き続きどういう姿勢で臨むか、東京都の関係も含めて臨んでいくのか、これをちょっとお考えを示していただけますか。","respondent":"松代管理工事課長","answer":"そういった関係から、今後つくります野球場等も含めましてすべて有料になりますので、本当の実態、利用される実態、そういったことをきちんとつかみ、利用者層のそういった実態をとらえて、今後も検討を進めていきたいと考えています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"南埠頭公園１面の機能の問題と、あと今、既存の野球場の機能のお話があったんですけれども、今後は利用者とよく話し合ってというお話ですけれども、ぜひ引き続き、今まであった３面が、今の時点では新たに確保は１面なわけですから、せめてもう１面、やっぱり今までのレベルが足りないと思いますので、東京都と区がどういう姿勢で話し合っていくのか。","respondent":"松代管理工事課長","answer":"そういった意味では、何とか１面は確保できたんですが、先ほど申し上げましたようにこの１面ですべてということはまだ考えておりませんけれども、ただ、利用される方々の実態というのを、先ほど言いましたように十分今後把握をしていきたいと思いますし。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういうのも、僕もちゃんとまだ調べていないんですけれども、Ａ面が使えなくなって、この間、練習する場所がなくて困っているという話も伺っていますので、もし区で今まで使っていた野球チーム、品川区は大小たくさんあるかとは思いますけれども、どの程度まで今現在で使えなくなるという、行き場がなくなったチームの状況というのはつかんでいるのかを教えていただけますか。","respondent":"松代管理工事課長","answer":"今後は残りの２面等がなくなる中で、またそういうことも加えて発生することでしょうから、そういったことを今の既存の野球場の中で調整等をまたしていただき、その中で試合等を組んでもらう、また練習をするのもその中でやっていただく、そういったことをお願いし。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区内には２６０ぐらいチームがあるんですかね。それぞれチームによって大小あるでしょうから、状況も一律にはいかないのかもしれないけれども、練習場の行き場がなくなるような、そういった事態だけは何とか解決策を示すべきだと思いますので、まずは今起きている状況はぜひ把握するように努めていただきたいと思うんですけれども、改めて、いかがでしょうか。","respondent":"松代管理工事課長","answer":"そういったところでいろいろと大会を運営される事務局、またそういった団体等でご理解をいただいて、いろいろ工夫をしていただいて試合等をやっていただく、また、ふだんの利用等については平日等の若干あいているところもありますので。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと細かいことなんですが、使用期間と使用時間はちょっとまちまちですよね。これは何でこうなるんでしょうか。","respondent":"藤田道路公園課長","answer":"使用の時間についてですけれども、青空野球場はこれまで無料だということもあって時間の設定がちょっと変則的な形になっておりますけれども、本来であれば通常９時から利用開始になるものなので、その２時間前の入れかえということで考えて、７時から９時というのが通常の時間。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"時間等はわかりました。通常だと大体１試合、いろいろありますけれども、大体２時間近くかかるかなと思うんですけれども、仕事に行くとか何かそういうことを考えると、なるべく早くから使えればとちょっと自分なりに感じるんですけれども、そこら辺の利用者団体との調整というか、そういうのはされているんでしょうか。","respondent":"藤田道路公園課長","answer":"そういう中でやってきておりますので、今回のことについて改めて声を直接確認したということはないんですけれども、１つのこのルールの中で天王洲野球場についても７時から９時という形でやっておりましたので、それに倣った形での今回スタートということで考えてあります。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"いろいろこれも、スタートをするにしても、また声を聞きながら対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"の(2)の東京港臨港地区の変更","agenda":"の(2)の東京港臨港地区の変更","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"全然知らないで恐縮なんですけれども、臨港地区に指定されていることと解除されることで何が変わってくるのかということと、あと、これは結局、外されて、次の都市計画審議会で公園になるという計画なんでしょうか。それはどういった公園になるとか、そういったことを教えていただければと思います。","respondent":"阿部都市計画課長、松代管理工事課長","answer":"臨港地区の目的ですけれども、まず港湾というのはさまざまな、例えば物流の機能を持っているわけです。そういう物流の機能を担保するために、土地利用の規制を行います。都市公園として位置づけた後の整備の内容ですけれども、多目的広場というような位置づけで、野球場としての機能等を持った、野球に限らずフットサルだとか、そういったものに使えるような施設整備をしたいと。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"今聞いて１点だけ、都から区に移管をされる、そういう計画のあれですよね。その際に、区は東京都に費用とか何かは払うんですか。","respondent":"阿部都市計画課長、松代管理工事課長","answer":"公園につきましては、区に移管される部分は無償で移管されます。合わせて７,５００m2としまして、多目的広場としての整備をすると、このように計画を進めているところです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"価格は大体お幾らぐらいなんですか。もしわかりましたら。","respondent":"松代管理工事課長","answer":"価格は現在交渉中です。一般的には、東京都からの譲渡の場合は減免をしていただけるものと思っておりまして、限りなく減免をしていただいて、安く買えればと思っているところです。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"今、６,０００m2と伺ったんですけれども、ここの変更概要で面積は０.７ヘクタールとあるんですけれども、これは誤差の問題なんですか。それともこういうものなんですか。","respondent":"阿部都市計画課長","answer":"というのは、ほかのところとの用地で関係で、ほかのところは四捨五入とか、そういうのがありまして、港湾については６,０００ちょっとですけれども、港湾計画上、０.７ヘクタールといっております。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"さっきの購入費の問題なんですが、土地の価格というような用地買収をするときには評価価格があるというようなものであると思うんですけれども、基本的なベースの価格というのが評価がきちんとどこかからの判定があってというもので、それに伴って減免の交渉が始まるということですかということと、それだったらその評価価格というのは単価として出ているものなんですか。","respondent":"松代管理工事課長","answer":"基本的には路線価等をもとにして、そこの中で価格が決定され、減免の割合等も含めてそこで決定されると。ですから交渉といいましても、そこで決定されたものを私どもは受けざるを得ないと、このような形だと思います。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"それでしたら、もう新年度のそういう審議会にかかるものではなくて、次からはもう改修の事業が始まるわけですから、その評価価格というのは出ていると思うんですけれども、それはどのぐらいの金額なのかというのはわかりますか。","respondent":"松代管理工事課長","answer":"進めなきゃいけないのは、今、都市計画上の手続、そういったものを順を追って進めております。それの見通しがつき次第、財産価格審議会等を当局で開いていただいて、最終的に売買価格が決定するものと、このように承知しています。","id":"exchange-018"},{"speaker":"井上委員","kind":"確認","question":"３月の東京都の都市計画審議会で決定した後、その審議会が開かれる、価格の審議会でかかるということでよろしいのかどうか確認だけです。","respondent":"松代管理工事課長","answer":"きちっとした日にち等は聞いておりませんけれども、流れとしてはそのように聞いているところです。","id":"exchange-019"}]},{"id":"topic-03","title":"の補助第２６号線（豊町）街路築造工事説明会","agenda":"の補助第２６号線（豊町）街路築造工事説明会","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"この場所は、掘割りということですけれども、これは、ここから始めたというのは、ここを基地として、あと残りを両側からやるという考え方でいいんですか。","respondent":"阿部都市計画課長","answer":"はここをこの既に完成しているところから、今回のところまでは工事ヤードとして使うということで、まずこういうふうにやりまして、その次にＪＲ、今申し上げました住吉踏み切りのところをやりまして、その先については向こうから、今、東急の側でやっていますけれども。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"簡単に言えば、段差がある中を、何ていうかな、今できているね。平らなところに掘って、掘割りにしてどうやって車両を入れるのか、地下鉄の話じゃないけれども、大きく迂回路をつくったりするような気がするんだけれども、こっちの区役所のほうから真っすぐやっちゃったほうが簡単なような気がするんですけれども、その辺は何でなんですか。その辺はどうですか。","respondent":"阿部都市計画課長、岩田まちづくり事業部次長","answer":"申しわけございません。築造は当然のことながら一番最後に全部やりますけれども、工事としてまず掘っていくところからやっていくと聞いております。ちょっと説明不足で申しわけありません。ちょっと説明がわかりにくいんですけれども、この点線で何もかいていないんですけれども、ここを工事車両が通行するんです。もうこれを削っちゃうんです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域の方からも、ご承知のとおり、何とかタコ公園を残していただきたいと、一応声は届いているかと思いますけれども、それに対して改めて聞きまして、どのような対応策を考えていらっしゃるのかを教えていただきたいのと、同時に、すいません、これは全体の話になるんですが、この補助第２６号線は、一応この完成というのはいつぐらいの事業ペースに今なっているのか、ここだけじゃなくて全体の話で。","respondent":"松代管理工事課長、阿部都市計画課長","answer":"場所、時期等、まずは工事の説明会をし、その後、このタコの移設等の詳細を私どもと打ち合わせをして進めていくと、このようになっているところです。工期ですけれども、平成２１年度まで事業認可を受けてあります。今、東京都第二建設事務所としては２１年度の完成を目指して進めているです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"タコ公園のことですけれども、今、移築、移設の方向で進んでいるということで、地域の方々も何とかできないものかということを強くおっしゃっていましたので、ちょっとそれを聞いてほっとしたんですけれども、ただ、あの交渉を進めるに当たって、このタコの形が難しいとか、いろいろ事前に聞いていたもので、課題はどういうふうにクリアされたのか、教えていただきたいのと、あと、この地図で言うと。","respondent":"松代管理工事課長","answer":"その辺のところの地域の意見というのは、当然のこと、東京都第二建設事務所がいろいろと地域に説明をしながら意見を聞いておりますので、それをあわせて私どもも聞きながら、いろいろ整備等に充てていきたいと、このように考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"大きくは、道を挟んだ反対側に移動すると、そういう方向であるということですよね。２０ｍ道路ですよね。それぞれ歩道はつけるにしても、２車線２車線になるんでしょうかね。ちょっと僕も勉強不足で申しわけないんですけれども、完成された後のいわゆる住民への影響といいますか、交通アセスというんですか、何か現状で示せるものがありましたら教えていただけますか。","respondent":"阿部都市計画課長","answer":"もう１つは、今、ここがないためにかなり迂回をして、品川中央公園ですか、あそこのわきを通ってこちらに１６３号線に入ってきては大井町に行けるという形になっていますけれども、その交通量は大分減ってくるだろうと思っています。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"特に例えば小学校ですと、戸越台中学ですか、幹線道路に面している学校はやっぱりそれなりの防犯を、学校の構造も二重サッシというのか、エアタイトという何かそういう構造の仕方みたいなんだけれども、そういう工夫をしたり、住宅も二重サッシなどいろいろな工夫を交通量や環境への影響によってはそういった対応も想定されるのではないのかなと思いますので。","respondent":"阿部都市計画課長","answer":"それともう１つは、先ほど管理工事課長から申し上げましたとおり、ここの付近につきましては一部ふたかけにもなりますので、そういう意味では委員がおっしゃるような戸越台中学のような影響が出てこないと考えています。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこはふたかけでということなんですが、それにしても長く西側に道路が入るわけですから、それはその周辺の方に与える影響はあるかと思いますので、そのためにもどういう交通量が想定されるのか、それによってどのような周辺への影響が起きるのか、そこら辺は把握していただきたいと思うんですけれども、いかがでしょうか。","respondent":"阿部都市計画課長","answer":"通過交通量については、当然のことながら私どもも把握する必要があるとは思ってありますけれども、影響につきましては、今申し上げたとおりの構造ですので、どういう影響があるか把握してほしいということですけれども、それは把握いたしますけれども、今申し上げたとおり。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"２点いいですか。もう１点、この工事箇所が大間窪小学校の敷地にかかっているということで、地下の工事ではありますが、例えば振動ですとか、騒音ですとか、地盤の関係とか、周辺の工事車両とか、学校に与える影響というのはある程度想定されているのか、もし何か影響があるということでしたら、対策を考えていらっしゃるのかということを教えてください。","respondent":"松代管理工事課長、阿部都市計画課長","answer":"この計画が出たときに、まず最初に出たのがタコの保存、移築ということが出まして、委員がご指摘のとおり、私どももそれをつぶして新しくつくったほうが経費的には安かろうと思って、東京都第二建設事務所もその方向でいて。そのときに、学校側に十分説明をして納得していただいていると聞いてあります。","id":"exchange-027"},{"speaker":"阿部委員","kind":"質問","question":"タコの愛着の価格を幾らと言えるかということだと思うんですけれども、それが高いか安いかという判断は別にして、幾らぐらい差があるのかどうかというのは伺っておきたいのですが。","respondent":"松代管理工事課長、阿部都市計画課長","answer":"価格については、第二建設事務所ですべて面倒を見ていただいていますので、詳しくは、聞いてございません。説明につきましては、学校関係者、あわせまして、先ほど申し上げましたけれども、近隣の方々、当然学校の保護者の方もいらっしゃると思いますけれども、その方々についてはあすから個別にビラを配布して。","id":"exchange-028"},{"speaker":"阿部委員","kind":"質問","question":"学校のほうなんですけれども、それは学校の判断というより、地域は地域でと思うんですけれども、今、選択性をとって遠くからいらっしゃるお子さんもいると思いますので、できれば学校の保護者ということで説明の機会があったほうがいいのではないかと思いますが、いかがでしょうか。","respondent":"阿部都市計画課長","answer":"先ほど申しましたとおり、学校関係者に説明をして、それは学校側との打ち合わせによると思いますけれども、要望があれば対応したいと考えています。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ビラの配布の範囲を教えていただきたいのと、あと先ほど、今回の工事箇所については平成２０年３月までだということと、あとは工事全体の関係でいくと、事業認可で平成２１年度までと、そんな説明だったかなと思うんですけれども、今説明がある箇所が終わってから、その後また横須賀線の下を通す工事になるということなんですけれども、実際のそこら辺の見通しというか。","respondent":"阿部都市計画課長","answer":"あの道路を挟んで三間通りの範囲と聞いています。もう１点は工事認可の件ですけれども、先ほど申し上げたとおり、２１年度までの事業認可を受けていますので、第二建設事務所としては、当然のことながら、その事業認可の中で当然終了させていくというのが現在の考え方です。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"大体、現実問題、いつごろまでかかるものか、東京都が、それと、この手続で今、平成２１年度までという線は区切られているんだけれども、現実問題、それがおくれれば、それはまた変更しなきゃいけないんですけれども、そこら辺のところは区は何か独自に見解を持っているか、あるいは東京都からどのくらいになりそうだとか、そういうのというのは大体何か聞いているかというのはどうなんでしょうか。","respondent":"阿部都市計画課長","answer":"１点目の説明会の範囲ですけれども、今回あくまでもこの区間が、工事区間はここで斜線の部分ですので、それに関連するという意味で先ほど申し上げた範囲で説明会をすると聞いてあります。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"説明の範囲なんですけれども、そういう意味で、私はどうも豊町のほうにそのお知らせが行かないのか、さっぱり今の説明ではわからないんです。ここは安全確保できるか、そういう心配もあるわけですから、これはもし今みたいに直接迷惑をかけるということで会議を考えたということであれば、当然、豊町も入ってしかるべきだと思いますので、ぜひそこのところはもう一回検討して対応していただければと思います。","respondent":"阿部都市計画課長、岩田まちづくり事業部次長","answer":"ですから今申し上げたとおり、原則は通行できないということではございません。ですからそういう意味では、豊町ではなくて、区道を中心にして説明会をしていただくということで東京都第二建設事務所の申し入れを受けてあります。私ども道路工事の場合はおそらく周辺の騒音、振動とか、あるいは工事ヤードへの建設車両の出入りの方向とか、そういう一番利害関係のあるところは漏れなくお声をかけることになるわけですけれども、それ以外には通過される方、通過交通。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"例えばこういう質問が出た場合に、東京都第二建設事務所で都がやるので今みたいな話にはならないとは思うんですけれども、やっぱりそこら辺、現実的にこんな感じになりそうだという説明ができるなら、しておいたほうがいいんじゃないかなと思いますので、ここはちょっとここで言っていてもしようがないので、先ほどの件とあわせてちょっと現実的なところを、おそらく質問が出るとすると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"藤田委員","kind":"質問","question":"土地がないということで。ここでやはりこのエレベーターのところ、基地を残地につくると、そしてホームのところを渡り廊下で幾らかはまたできるわけですから、その辺もちょっとやはり都と少し話し合って、できるものであれば、そういう方法もとれないことはないんじゃないかなと思うんですが、いかがですか。","respondent":"岩田まちづくり事業部次長","answer":"ここは改札口を入ったら上り下りが別の階段で今、上りおりするようになっていますので、普通でいけば２基、上り下りそれぞれ１基のエレベーターの設置が必要で、現況の東急用地の中ではそれが事実上、物理的に不可能だということで。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"昼間は工事をしないのかどうかというのが、さっき夜間だけですみたいなことがあったので、そのことも教えていただきたいなと思ってますので、もう少し区の姿勢としてきちんと対応するということをちょっと確認したいと思います。タコ公園について言えば、前は公園を残してほしいということでタコを保存してほしい、何とか残してほしいという声だったと思うんです。","respondent":"阿部都市計画課長、松代管理工事課長","answer":"先ほどありました、例えば１６３の工事、全体の説明、どういうふうになるのか、しているのかですけれども、道路計画につきましては、全体をどういうふうに提案しているかということは、なかなか全体のＰＲは難しい面もございまして。それを東京都としては最初、非常に費用、それとあと工法的な部分で移築は難しいというところがあったんですが、その後さらに細かく検討をしていただいた上で、当然のことながら費用的な部分も検討された上で。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問・要望","question":"さっきの都市計画道路全体像で、道路地図とかがあるのはわかっていますけれども、道路地図は計画道路の地図なので、実際に今動いているところの全体像が示されなければ、今本当に１６３号線と駅前通りも、そこの道路のところと空き地はどんどんあるけれども、全然見えてこないと思ってますので、委員長にお願いなんですが、あまり今期、建設委員会はありませんけれども、全体像がわかるような、私たちも。","respondent":"阿部都市計画課長","answer":"ですからどういう場面、それが一番の、ホームページに載せていけばいいのかなと思いますので、それはちょっと検討させていただきたいと考えています。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"ホームページとかということじゃなくて、そもそも私たちは問われたり、説明ができない状況にあって、関心を持って聞きに行く方たちだけはなくて、きちんと知ること、もっともっと公表して、今、途中で、計画が年度年度で予定されている年度よりも相当遅くなっていて、全容が見えてこないということをどこかで明らかにしてほしいということなので、そういう意味なんです。","respondent":"岩田まちづくり事業部次長","answer":"こうならないように、品川区は前面には出ませんけれども、地域の方の要望が満たされながら、東京都も一応他の地域といいますか、全体的に税金のむだ遣いと言われないような方法で、現在検討を進めていただいているということをぜひご理解をいただいて。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問・要望","question":"とかく最近できた公園は、品川はどうでしょうか、よく見るのは、組み立て式のとりあえず滑り台と、登るものと、砂場があればいいといったらつくった方に失礼ですけれども、組み立て式の公園が最近主流になる中で、あの時代は１つ１つの公園に遊んでいただきたい子どもの姿を考えてつくった形、都内にもああいうタコの形というのは数少ないという話もちょこちょこテレビでも取り上げられる１つですよね。","respondent":"岩田まちづくり事業部次長","answer":"それはそれで非常に結構なことで、タコ公園も委員がおっしゃるように非常に長い間なれ親しんで、愛着を持っていただいているというのは、逆につくったほうにとっては設計冥利に尽きるんでしょうけれども、最近では１０年ぐらい前、宣伝で使われて、それでまた脚光を浴びて。","id":"exchange-038"}]},{"id":"topic-04","title":"の平成１９年２月都営住宅入居者募集","agenda":"の平成１９年２月都営住宅入居者募集","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"区内の募集戸数等がわかったら、あと全体の募集戸数等がわかったら教えてほしいんですけれども。","respondent":"齋藤住宅課長","answer":"後ほど、もうすぐ詳細が来ますので、今はわかりません。","id":"exchange-039"}]},{"id":"topic-05","title":"の平成１８年度マンション管理セミナー（第２回）の開催","agenda":"の平成１８年度マンション管理セミナー（第２回）の開催","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今回、第２回ということでしたけれども、第１回目は参加者は何人ほどだったのか、その参加者から寄せられた感想やご意見はどんなのが寄せられているのか、ちょっと教えていただけますか。","respondent":"齋藤住宅課長","answer":"このマンション管理セミナーは区単独で平成１１年度から年２回開催しております。第１回は中小企業センター、１２０人ぐらい入れるところで大体埋まりました。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"旧耐震の人でも、大体もう阪神淡路大震災から１２年たって、改めて皆さんちょうど自分のところがどうなのかと、率直に感じていると思うんです。区でも管理組合の把握をされているかと思うんですけれども、そこには特別なもの、お知らせの方法という工夫があってしかるべきではないのかなと思うんですけれども、いかがでしょうか。","respondent":"齋藤住宅課長","answer":"２１日以降、広報「しながわ」で掲載しましたところ、今、２けたぐらいのメールで応募の方がいらっしゃって、基本的にはこういった周知方法の中で対応しておりますが、今まで相談会に来られた方、あるいはマンション。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"これはやっぱり防災の問題は政策的にも進めなければいけない分野ですから、ぜひ力を入れて、マンション管理セミナーはそこに絞っただけの講演をやってもすごい喜ばれるんじゃないのかなと、どうも抱えている問題は共通する部分も多いんじゃないのかなと思いますので、マンションの耐震化、そこに絞ったセミナーなんかもぜひ工夫をされて進めていただきたいと思いますけれども。","respondent":"齋藤住宅課長","answer":"委員のご指摘のとおり、耐震の部分についてはなかなか難しい問題だと思ってあります。平均的な耐震、民間のマンション７階８階建てで７０戸、耐震診断で５００万円、設計で５００万円、本当にやると２億円３億円かかってしまう。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"マンションの課題というところで、ちょっと住宅課とは離れるかもしれないんですけれども、これから、今伺っている中で、ローンが３５年とかで終わった後というマンションがたくさんあると思うんですけれども、そういう中で、マンションの中の入居当時は若かったり家族がいたりという中で、本当に大きなマンションでも高齢者１人世帯のマンションとか。","respondent":"齋藤住宅課長、福田まちづくり事業部長","answer":"まちづくり事業部の住宅課といたしましては、最優先の課題はハードの面でございまして、所管は違いますけれども、建設委員会の中でもそういったお話があったということを高齢福祉課等々に伝えますので、ぜひ他課と連携しながら。私どももそれに着目をしながら、住宅制度について、あまり硬直的に考えず、対応できたらと考えています。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひそういう意味では、マンション管理セミナーとかという名目でやったときに、呼びかけもしやすいし、参加もしやすいと思いますので、ぜひ前向きに、緩やかに区民のニーズをとらえていただいて、取り組んでいただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"藤田委員","kind":"質問","question":"ですから区として、それを専門家の講師を、マンションの要請があれば出向いて、その費用については全額区が出すということが厳しければ、マンションはマンションでやはりお金をプールしていますから、そちらのほうに派遣するのに例えば幾らか区が助成しますよというぐらいの積極性があってもいいのではないかなと。","respondent":"齋藤住宅課長","answer":"今、委員のご提案があった講師派遣のような形での分譲マンションへの支援というのは、一部の区で行っております。私どもの区といたしましても、そういったことでできないか、これは検討してまいりたいと思います。","id":"exchange-045"},{"speaker":"藤田委員","kind":"質問・要望","question":"そういうところは非常に難しいなと、人間関係もそう、買った人もいれば、買った人から借りた人もいれば、いろいろなことが今ありますので、そういうのも１つ課題だなと思いますので、ぜひそういうところにはこうしたらどうだというような専門家のアドバイスというのは、やっぱり必要だと私は思いますので、新年度どういうふうになるかわかりませんけれども、方向性として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"井上委員","kind":"提案","question":"前回本会議のときに、駐輪場の指定管理者が選任をされて決定されましたけれども、そのときに説明があった施設整備を順繰りに進めていくということが示されましたけれども、今、私たちのところに届く声としては、駐輪するときの施設の間隔が狭かったり、すごく利用勝手が悪いという声が多分担当課にも届いているかと思うんですけれども、そのことについて、今後そういう整備をするのに当たって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"井上委員","kind":"提案","question":"それで、これは今後、そういう設備を台数を増やそうというところでやっているという状況にあると思いますから、きちんと整備するのであれば、年配の方たちでもちゃんと自分で出し入れができるようなところにしてほしいという改築というか、そういうことも提案をしていかなければいけないと思っていますので、行政のほうで問題のあるところを提案できないのであれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"阿部委員","kind":"提案","question":"すいません、素人臭いことを言うかもしれませんけれども、今のご提案でそういう問題があるというのは私も初めて知ったので、そういうご提案をしていただいてよかったなと思うんですけれども、全部一遍に見に行ったほうがわかりやすいのか、今日ちょっとこれが終わってから一人ずつ駐輪場ぐらい見てきてもいいなと。そのほうが話が早いのではと思って。お任せいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"井上委員","kind":"提案","question":"個人的に調査するのは当たり前のことだと思いますので、委員会として提言をするということで、委員会の視察が必要だということを提案しているので、誤解のないようにお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"藤田委員","kind":"質問・要望","question":"任期もありますし、我々のあと残された委員会の回数も限られていますので、委員会の運営については委員長がいろいろ考えているわけですから、正副委員長でよく考えていただいて、どうするかというのを決めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/668670?Template=document&Id=3872#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":35317,"voices":143}},{"id":"h19-20070122-9","meetingId":"h19-cm01","date":"2007年1月22日","dateIso":"2007-01-22","committee":"文教委員会","time":"午後１時０３分～午後 ３時３５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","topics":[{"id":"topic-01","title":"いじめ撲滅キャンペーンおよび教育相談の概要","agenda":"いじめ撲滅キャンペーンおよび教育相談の概要","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"いろいろ対策・対応されていることはわかりました。研修をされた内容なのかもわからないけれども、これからどういうふうに教職員への指導とか、あるいは教職員を通じてどういう形での指導とかお願いをしていくと思うんだけど、その辺については、教育委員会としては学校に任せちゃうということなのか、どういうふうにしていくか考えがあったら、計画があったらお願いします。","respondent":"河野指導課長","answer":"今回の秋からの一連の動きの中で、つい先日もいじめ問題検討委員会、これは急遽、校長会と連携して立ち上げた組織ですが、この一連の取り組みについて、反省を含めて今後の展望について意見を出し合いました。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"だからそういうことを市民科の授業の中にもあるでしょうし、朝礼とか学級会とか、あらゆるところを通じて日常的に子どもたちに意識をさせながら、身につくというのは、今回の何カ月間の中である程度は理解をしていっているんだろうけど、身につくというのは恒常的というか、続けていくことが重要だと思うので、その辺も教育委員会と校長会だとか検討委員会の中で絶えずやっていってほしいなと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"以前、自殺予告が２件あって、１件は消息がわかった。もう１件についてはその後私は聞いていないんですが、具体的にはどうなのかということと、それから、私は「いじめ撲滅」というこの呼び方にちょっと違和感を覚えて、犯罪撲滅だとか、麻薬撲滅みたいなのはいいんですけれども、子どもの内面に入ったいじめの問題について、撲滅ということが、しかもキャンペーン的にやることが果たしていいのか。","respondent":"河野指導課長","answer":"その結果、該当する児童・生徒は見当たらないということで、今度学校長名でその文面に記載されていた具体的ないじめの内容、例えば「１,０００円貸して」と言われたとか、そういうことを具体的に記した内容の文書を全家庭に配布いたしまして。","id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"子どもの内面に入って学校の教師も、多くの問題を抱え、悩みを抱えている子どもたちにいかに迫っていくのかという点からしますと、決して一定期間のこととはとらえていないのはわかりますけれども、こうしたやり方と、名前がどうも、この「撲滅」といのがふさわしくないような気がしてならないというのは、繰り返しになりますけれども、感じます。","respondent":"河野指導課長","answer":"具体的に出席停止期間中どういう対応をしなければならないのかという中身について、まだ全く具体的に触れられておりませんので、まだ我々のほうとしても詳細について検討するというところまでは至っていないのが現状です。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"今後も制度的にいじめの問題を改善していく体制としては、やはり教師の側がよりきめ細かく子どもの状態を把握できるような環境をつくってあげることがすごく大事だなと思うんですけれども、昨日、芳水小学校の学校公開があったのでちょっとお邪魔させていただいたんですが、今、３０人ぐらいのクラスが多かったんですけれども、ここは率直に言って、それは授業の場を見て思ったんですけれども。","respondent":"河野指導課長","answer":"特にいじめに関しては、これは小学校の１つの欠点でもありますが、担任が抱え込んでしまって、指導が十分機能しないままに事態がどんどん進んでいくというようなことがないようにということから、報告、連絡、相談を遵守して、学校組織として対応するように指導しています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"学校全体で集団的に対応ということだった思うんですが、すべての教師が担当のクラスを持っているわけで、自分のクラスだけで精いっぱいという状況もあると思うので、教師の側が集団的に対応できるような配慮をこれからもつくっていただくことを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"武内委員","kind":"質問・要望","question":"ちょっと聞き漏らしちゃったかもしれないので確認だけさせていただきたいんですけど、１２月いっぱいで教育相談のアンケートに基づいた面談はすべて終わったということですね。それと、ご説明があったかもしれないんですけど、聞き漏らしているかもしれないんですけど、面談はどなたがやられたんですか。","respondent":"河野指導課長","answer":"面談は各学級担任が実施しております。","id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"それと直接関係ないんですけど、たしか今日の広報しながわで教育相談の方を募集するという記事が出ていたような気がしたんですけど、別にこれと関係なく募集されるという意味ですか。","respondent":"河野指導課長","answer":"本日の広報しながわで募集をかけたのは、教育相談センターの心理職、それから、小学校に配置するスクールカウンセラー等に関して登録をしていただくという趣旨のものです。","id":"exchange-008"},{"speaker":"本間委員","kind":"質問","question":"撲滅キャンペーンということで、１カ月ぐらいの期間を設けていろいろ調査をしたというのは、その調査をしたということだと思いますが、中身的に見ればキャンペーンという形をつけなくて、これを機会にこれからも続けていくという部分でのことも考えたことなのかどうかというのが１つと、それから、このＡ小学校の中に、３項目あるうちの１つなんですけど、あいさつ運動の実施というのがありますね。２点です。","respondent":"河野指導課長","answer":"そのほかに、特にあいさつを強調してやろうという月間につきましては、学校においでになる保護者の方を含めたお客様方に積極的にあいさつをするようにということで、特に集中して取り組むというケースも学校ではあります。","id":"exchange-009"},{"speaker":"本間委員","kind":"意見","question":"大分定着してきているかもしれませんが、一、二年ぐらい前だと思いますが、ある小学校の場合には、校長先生がかなり早い時間帯に出勤しておりまして、１人で校門の前でおはようありますと言いながら、場合によっては肩をたたいたりだとか、元気づけたりしている姿を見たことがありますけれども、これが今の話だと、学校の生徒の中から上級生を出すということのようですね。","respondent":"河野指導課長","answer":"キャンペーンそのものは今後やるやらないはともかくといたしまして、いじめに対する取り組みというのはこの中で完結するものではございませんので、取り組みについては今後も継続して実施していくというふうに考えております。というか、それは当然のことであると考えております。","id":"exchange-010"},{"speaker":"本間委員","kind":"質問","question":"あいさつですからありがとうだけではございませんけれども、おはよう、ありがとう、さようならとかという部分も全部含まれていると思いますけれども、何かそういうポイントを絞りながらやっていくのもまた１つ、目標に向かって、１つでもいいですから、これだけはきちっとやろう、おはようならおはようとか、さようならならさようならとかいうことをやっていくのも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"八潮北公園野球場の早朝利用開始","agenda":"八潮北公園野球場の早朝利用開始","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"野球人にとっては、品川の中で野球ができる場所がどれだけあるかということが死活問題なわけですけれども、青空野球場の代替ということで早朝利用を八潮北公園野球場で開始するということは非常に大事なことだと思いますけれども、単純に考えまして、今まで５時までしかできない、夜は使えないとしても、使えたところが１面なくなって、その分を八潮北公園の、２時間の時間帯が枠が増えるということなので。","respondent":"富田生涯学習課長","answer":"私どもこういった都からの申し入れによる青空野球場の返還等々ということにつきましては、スポーツ協会を通しまして軟式野球連盟に実情をご説明申し上げ、こういった南埠頭公園の代替等、できる限りの努力をしているということについてはお話をしています。","id":"exchange-012"},{"speaker":"安藤委員","kind":"提案","question":"野球を通して人生が豊かになるという点では、かなり大事な活動だと思うんですけれども、直接の担当は、野球場の建設とかというのは違う所管かもしれませんけれども、こちらの所管としての積極的なアイデアといったものは。こちらのほうから積極的にそちらのそういった施設をつくる所管に対して、提案していくというような何かアイデアがあれば。","respondent":"富田生涯学習課長","answer":"私ども区民大会等を行っておりますけれども、区内の区立の施設で困難な場合には、中央海浜公園、スポーツの森等々、区としてその部分を申し込んで利用していくなど、そういったことも含めて努めてまいりたいと考えています。","id":"exchange-013"},{"speaker":"原（雅）副委員長","kind":"質問・要望","question":"１つだけちょっと教えていただきたいんですけれども、青空、Ａ面の代替地で八潮北の野球場ということだけれども、使用の応募とか、回数とか、それを補完できるような形をとられていますか。全くＡ面の代替地としてこちらを使っているわけだから、その使用の方法とか回数とかを比較したときに。","respondent":"富田生涯学習課長","answer":"このたび早朝利用を開始するにあたりましては、八潮北公園の利用ということになりますので、予約システム等々、早朝枠を土・日・休日について設けるということで、管理人のいる時間をその部分を繰り上げる等々ということで対処していくということになっています。","id":"exchange-014"},{"speaker":"原（雅）副委員長","kind":"質問","question":"そうなったのはわかるんですが、区民の方が利用するにあたって、前のところと比較したときに、使い勝手とか、そういうところで支障がないんでしょうかね。","respondent":"富田生涯学習課長","answer":"ただ青空野球場は都から無料で借りているということもありまして、無料で区民の皆さんに利用いただいたところですけれども、その部分については使用料の負担を他の野球場と同等にいただくということになってまいります。","id":"exchange-015"}]},{"id":"topic-03","title":"年末開館の実施状況","agenda":"年末開館の実施状況","exchanges":[{"speaker":"武内委員","kind":"質問","question":"先ほど予想は４,０００名ぐらいだというお話だったんですが、大体通常の休日のときの来館者数よりは上回ったということの考え方でよろしいですか。","respondent":"工藤品川図書館長","answer":"荏原図書館に関しましては、大体９００名から１,０００名というふうに日曜日の来館者をつかまえてございましたので、そういった意味では、荏原図書館の３０日は若干数字に関しては落ちたわけなんですけれども、同等もしくはそれを上回る来館者があったと考えております。","id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"年末の忙しい時期でもこういう形で本に親しんだり、また映画等という文化的なことで利用される方がこれだけいらっしゃるということは、個人的にはいろいろなそういう取り組みがあるんだろうなと思ったんですけれども、そういう面では今後、来年度以降もまたこういうものが予定されているんでしたら、教えていただきたいと思います。","respondent":"工藤品川図書館長","answer":"それ以降につきましては、開館の拠点を増やすのかどうかというものは、また今後に向けて検討していきたいと思ってありますけれども、今の時点では全館を３０日までやるとは考えてございません。開館するとしましても、拠点方式でやっていきたいと考えております。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169946?Template=document&Id=4596#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":12584,"voices":56}},{"id":"h19-20070122-5","meetingId":"h19-cm01","date":"2007年1月22日","dateIso":"2007-01-22","committee":"総務委員会","time":"午後１時０４分～午後３時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","topics":[{"id":"topic-01","title":"告だけさせていただきます。 ──────────────────────────────────────────── ２ 報告事項 (1)","agenda":"告だけさせていただきます。 ──────────────────────────────────────────── ２ 報告事項 (1)","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"有権者ということで、これは２０歳以上の男女を調査対象ということになっていると思うんですけど、１０代ぐらいも世論調査として、これと一緒にやるべきなのかどうかというのがちょっとわからないとは思うんですが、１０代ぐらいからこういうのは組み込んでいたほうが若い人に対して、関心を持たせる上ではいいのではないかと、私は思ったりするわけですが、この世論調査以外で、例えば１０代の人に関して。","respondent":"中川原広報広聴課長","answer":"２０歳未満の方の調査については、こういった区民に対する公的な調査としてはあまり経験としてはありませんが、テーマによっては、特に啓発的な環境の問題とかいろいろ取り組んでいることがありますので、その辺、ちょっと考えてみたいなと思います。","id":"exchange-001"},{"speaker":"山村委員","kind":"意見","question":"本当にそのとおりだと思うんですけれども、今後、若い世代に品川区に対して関心を持ってもらうですとか、地域のそういう問題、活動に参加させるとかということを考えると、こういう調査でもやっぱり１０代のいつからかというのはちょっと難しいだろうと思いますが、参加させても、私は悪くはないんじゃないかなと思いましたので、言わせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"１点だけお聞きしたいんですけれども、２年に１回実施をしているこの調査の目的として、今後の施策の展開の資料にするという話が出ていますけれども、取り方の問題として、例えば２ページにある定住意向理由の中で、これは全体の数字ですから、あれかもしれないですけれども、こどもの教育環境がよいからというのは、低いほうのランクに入っていますね。","respondent":"中川原広報広聴課長","answer":"教育環境を例にとってのお尋ねだと思うんですが、この項目は区民全般に関係するものと、ある世代にニーズが集中するものとありますので、これは先ほど申し上げましたように、全世代の平均値を取ってありますので、そういった意味では教育問題とか子育て支援について。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問・要望","question":"世帯によって要望というのは違いますから、当然そうだろうと思います。ただ、どういう形で返していくか。だから、どういうふうに皆さんに返していくのかというのを明確にした、このアンケートになるのか、それともまた別の形になるのかはわからないんですけれども、そういうことが必要なのではないかという気がします。","respondent":"中川原広報広聴課長","answer":"次の世論調査のときにまたやってみて、区民の方に聞いてみる。例えば各戸収集がいい例なんですけれども、各戸収集に取り組んで、ある程度１年以上たったところで、今回の所管がこれを聞いてみたいという形で質問項目を持ってきます。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"今、大体対象者が１,５００人ということで、回収数が１,１２３人。やはり実際、日常そこで活動して、区政に対するご意見をいろいろ持っている人、もう少し関心の高い人にこういう調査をお願いするという形のほうが、より区政に生かしていく場合に、私は本当の生の区政に対する評価・調査になるんじゃないかと思うんですが、その辺、町会単位とか何かの調査はやっているんでしょうか。","respondent":"中川原広報広聴課長","answer":"それから調査につきましては、区政に関心のある方はモニターになってもらって、モニターのアンケートも取っていますし、電子アンケートという形で、モニターアンケートというのをやったものは、必ず一般の若い世代の方にも電子アンケートをしたりとか。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"その内容は今わかったんですが、ただ日常生活として品川区に長く住んでおられる、またいろいろ品川区の区政の実態をよくご存じな、やっぱり町会がせっかくあるんですから、そういうところを利用して、もっと生の声、そうするともっといろいろな声を聞けると思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"原（浩）委員","kind":"意見","question":"民間のネットで調べた、住み続けたいまちみたいなものがありまして、品川区はやっぱり１番になっていますので、日頃の成果が出ているのかなと。ただ１点だけ、１０ページの品川区役所の印象という中で、これは調査方法にもよると思うんですけれども、信頼できるというところが若干下がってきたという、この辺のところをちょっとお聞かせください。","respondent":"中川原広報広聴課長","answer":"先ほどイメージアップ運動が始まる前を取っておりますのは、やっぱり取り組みをしなかったときと、したときに比べると、やはりその間、いろいろな行政の状況がるるありまして、影響を受けることがあったとしても、総体、そういうところで動いているかなと感じております。","id":"exchange-007"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"了解いたしました。とにかく区民数も増加していますし、９割というのはすごい数字だなということなので、続行して頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問・要望","question":"今回の工事、１億１,３００万円余りということで、何点かの定期的な補修というのが軸になっていますけれども、ちょっとお伺いしたいのは、品川清掃工場でのサーマルリサイクルが本格化すると、作業所そのものが必要なくなっていくと聞いていますけれども、その辺の今後の計画の流れは私はよくわからないんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"もちろん、作業所で説明を聞いた範囲だと、１年ごとに変えなくちゃならないもの、２年ごとに変えなくちゃならないものとありますけれども、中央監視モニタリングシステムそのものを交換するんだという説明をあそこで受けましたけれども、あれは操業を開始してから１８年間、あれを使ってきて、途中で修理したりとかというのはあったんでしょうけれども、同じ設備を入れるとすれば、これから先。","respondent":"宍戸施設担当課長","answer":"そのほかの部分も、例えばフィーダ設備の(1)の部分ですけれども、磨耗から守るパッド、それからごみをかくスクレーパを交換する。これは毎年１年に１回、必ず行っていることです。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"わかりました。ということは壊れた部分、さっき中央監視モニタリングシステムというところがよくわからないんですけれども、必要な修理の体制は今日見た段階でのあれで終わっているんですよという話でとらえていいわけですか。","respondent":"宍戸施設担当課長","answer":"モニタリングシステムについては、本当に故障してしまっていたので、今回、契約して、すぐ契約時が１２月２７日ですから、それから直ちにあそこの部分は取り替えた。取り替えが完了しているという状態でごらんいただいたです。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"参考までにお聞きします。時間も相当短縮できるのかなと、ちょっと今日、見ていたんですが、その辺どうなんでしょうか。もしわかる範囲で、そこらでメンテナンスをかけて、あそこで一たんとめて、またコンテナ船に乗せて、あそこに運んで、またおろして、また焼却するというのは結構手間も相当かかるような気がするんですが、その辺、何か検討した結果とか、試算とかあるんですか。","respondent":"石田委員長、桑村総務課長","answer":"それも自治制度特別委員長がいらっしゃいますけれども、答える人が難しいかな。わかることがあったら。そういう意味では、普通に考えれば、車で行って云々ということもあるんだろうと思いますが、やはり工場をつくりますと、品川清掃工場の場合はあまりそういうことを近隣の方とお話し合いとかやっていませんけれども、普通ですと。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"意見だけですけれども、あそこまで清掃車が入ってくるなら、あそこから京浜島だったら一直線だと思うんです。環七云々という話もないのかなと思うんですけど、ちょっとどうしてあそこにおろしているのか、コンテナにわざわざ詰めて行くというのが、何かまたそれをまた戻して、あいたコンテナを持ってくるというのが、非常にむだなような気がしましたので、ちょっと意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"山路委員","kind":"質問・要望","question":"１点お伺いしたいのは、施工メーカーが施工して、経年劣化、故障、磨耗度なんかはいつでもわかりますよね。技術的には一番ベターな随意契約だと思うんですけれども、一部にこういう流れで随分一部事務組合から来ましたよね。これは地元業者でもう少し技術的なものがあって、部品を手に入れたり、地元業者でもできるのではないか、その辺を調査されたことがあるのかどうか、教えていただきたいと思います。","respondent":"宍戸施設担当課長","answer":"同じ随意契約ですけれども、そういった精査については区に移管されてから厳しくやっているというようなことはありますが、新明和工業以外のところに発注できないのかということについてはいろいろ研究はしているけれども、やはり難しいという結論を出したと聞いております。","id":"exchange-014"},{"speaker":"原（浩）委員","kind":"質問","question":"その割合のときに技術料、さっきあったプラント、これは２つ目の次の質問にも関連してくるんですけれども、単純に言ってしまえば消耗品ですとか、それが大体何割占めているのかと、あと実際には特許権の問題と、実際、技術的に何が入るのか。多分、我々が見に行ったので、ほかから人数が動員されているのかなという気もしたのですから、まずその辺のところに関して１点お聞かせ願いたい。","respondent":"宍戸施設担当課長","answer":"これは今回、契約金額が１億１,２００万円余なんですが、そのうちの直接工事費が９,３００万円、そのうちの人件費相当分が約２５％で２,５００万円、それから部品ですとか、運搬費、そういった物が７５％です。","id":"exchange-015"},{"speaker":"原（浩）委員","kind":"質問","question":"詳しくありがとうあります。かなり特殊性があるので、自分も以前、新日鉄のほうの高炉の見学会をしたことがあるんですけれども、それに意外と似ているかなという感じもしたんですね。ですから、特殊性があって、金額的にも一律、一般的な形で消耗品だからというイメージではとらえられないことは重々わかっておりますので、ちょっとその辺のところの数字のことをお聞きしたかったというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田委員長","kind":"質問・要望","question":"ほかによろしいですか。私から１つだけ要望だけしておきます。答えは要りません。先ほど施工業者とか期間、特許権等のお話の中で、いろいろ努力をされたというのはわかりました。わざと言っているなと思うときもあるから、これは連携して、あまり不可能というのを言わないほうがいいんじゃないかと思う。１点だけお願いします。報告事項を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/396657?Template=document&Id=1744#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":19467,"voices":46}},{"id":"h19-20070123-11","meetingId":"h19-cm01","date":"2007年1月23日","dateIso":"2007-01-23","committee":"自治制度特別委員会","time":"午後１時０６分～午後２時３１分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査「得制度改革・主要５課題に関すること」","agenda":"特定事件調査「得制度改革・主要５課題に関すること」","exchanges":[{"speaker":"石田委員","kind":"確認","question":"何点か確認をします。初めに、条例明記５４％とおっしゃいましたが、これは５５％ですよね。","respondent":"濱野区長","answer":"大変申し訳ありません。５４％と５５％が頭の中でごちゃごちゃになっておりまして、５５％ということを明記されることは、それなりの意義があると考えたです。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"５５％と明記されるということですが、中身を見ると２％と１％の補助金の部分があるわけですから、我々から見ると、三位一体改革の中の２％プラスアルファだという話と、今回の部分で２％は変わらないという話とは若干後退したのかなと思える感じは否めない。我々がよくわからないのは、例えば３６５億円増えてきました。この辺の見解がいつも違うわけです。それを使い切るけれども、今度は中身の話です。","respondent":"濱野区長","answer":"結局、問題は都補助金１％を削減されたということですけれども、先ほど申しましたように、都補助金というのは区側からさまざまな要請を受けて補助金が成り立ってまいりましたから、それはこれからも働きかけはできるのではないかと考えております。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"もう１点だけ伺います。最後のほうの、これからやるのだというのは一番大切なことだと思います。いつも区議会というのは、そこに置かれてしまう。そこが必ずトータル的な話だと中身の問題があるでしょうけれども、そういうところをぜひしていただきたいと思いますけれども、その辺の考え方、議長会を含めた考え方はいかがでしょうか。","respondent":"濱野区長","answer":"そういった意味で、これからも区長会が議長会とよく連携を保ちながら、東京都と話し合っていくことが必要だと思っていますので、そのことは区長会でも提案をしていきたいと考えています。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問・要望","question":"本当に頑張っていただきたいのですが、我々もぜひこの部分は区議会を挙げて支援していく話だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"提案","question":"現在、都と区の協議がどのような状態にあるのかというと、１ページ目の四角で囲まれている１２月２６日、１２月２８日と二つ書かれているけれども、１２月２８日が都から提案されたものを区長会が「都案を了承することを確認」というのは変な言葉だけれども了承したと受け取って、これが現在、区側が認めたもので、都側には返事はしていないのですね、今どうなっているのですか。","respondent":"日下部企画財政課長","answer":"これはもう少しこちらに補足すればよかったかもしれませんけれども、一応１２月２８日にこのような形で都案の了承について正副会長が協議して確認しました。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"１ページに表されているのは、１２月２８日の、今言われたような、これからのことについて含めて、都側も認めた。都区がこれで合意したと理解すればいいのですか。","respondent":"日下部企画財政課長","answer":"現段階ではそうです。１月３１日に改めて都区協議会で最終的な確認をするです。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、数字の話になりますが、まず６２２億円と７７７億円という差、先ほども石田委員も調停という話もされていたけれども、なぜこの差が出たかという原因はわかっているのですか。三位一体改革による影響を区側が計算をすると７７７億円、都側が計算をすると６２２億円、差が１５５億円ある。算定の仕方が違うから差か出るわけですが、その原因は何ですか。","respondent":"日下部企画財政課長","answer":"これもおかしいわけです。もう一つは、都の住民税の徴収取扱費の関係でも、６５億円ほど出てまいりますけれども、これも三位一体に直結する中身ではないということで、これも対象から除外する。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、国の三位一体分と都の三位一体分は、都は国の三位一体から来ているのだろうけれども、都が従来区に対して負担していた税源分はもう知らないよと言っているわけですか、その辺を説明してください。","respondent":"日下部企画財政課長","answer":"一番率直な言い方をすれば、そのようなことだと思います。自分たちに原因があるわけではないわけです。あくまで国の制度改革によって連動するといいますか、直接的に都が進める話ではない。この辺がよく理解できないところですが、都側はそのような主張を取り下げないです。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"先ほど調停までは行かないで、あくまで話し合いでいくというけれども、都側の主張はいろいろ税の部分だとか徴収の部分だとか言うけれども、それは都と区の間の話し合いの項目として従来からもあった問題です。それが突然三位一体の中に入れようとするから、都側もおいおいという話で、従来から都区の協議事項の中に入っていたとすれば、なぜ三位一体の中に入れてしまったのですか。","respondent":"日下部企画財政課長","answer":"そういう意味では新しい一つの材料として、三位一体に全部連動する形で出てきたものですから、その辺は区側としてはあくまでも影響にかかわる中身であるということで、それはそれとして主張しているわけです。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"これから続けるという、先ほどの１ページ目の話だから、その辺は整理して交渉すべきではないかと思うので、これはこれから先ということなので、私はそのように受け取ります。３ページ目も５４％の数字です。５５％という数字はどこに出てくるのですか。具体的な金額はどこに出てくるわけですか。","respondent":"日下部企画財政課長","answer":"これは都側提案として、このような形で提示されたということでございまして、最終的に……。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"意見","question":"先ほどの区長の答弁だと、５５％だから納得して、これから先のことに目を向けていくという話をされていて、私たちは５４％の数字を基本に議論しているという、その相差については次に報告しますというと、今日から次までの間、ずっと１％について悩まなければならない。それについて、やはり区長は５５％を基本とすると言ったのだから、その１％が幾らで、どのような形で都から出てくると説明してくれないと。","respondent":"日下部企画財政課長","answer":"大変、申し訳ございません。あくまでも途中経過ということでつけさせていただきました。最終形は３％アップの５５％ということになりますと、５４％で９,６１７億円ですが、５５％になりますと９,７９４億円になってまいります。１７７億円の増です。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"確認","question":"確認します。９,７９４億円になると区長がこれでいったほうが都側と手を打って、またさらに上乗せというか、税源移譲だ何だといろいろ交渉していく基礎になるから５５％で９,７９４億円、１７７億円は３ページの表の三位一体新規算定等のうちの新規算定の中に入ってきて、これが４２５億円を超えてくると理解してよろしいわけですね。","respondent":"日下部企画財政課長","answer":"基本的には、この中で仕分けをすれば、そのような形になると思います。表現として適切かどうかわかりませんが、この中に溶け込んでくるという形になると思います。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"今度は、その表の三位一体でくる財調と２番目の新規算定、従来は一番下はあったけれどもこれが増えたという表で、真ん中のものを財調協議をして、この額をどうするか毎年やってきたわけです。ここに三位一体が出てくると、三位一体で出てくる３６５億円、都が算定してくる３６５億円については、そこにしか使ってはいけないという特別交付金のような形になってくるのですか。","respondent":"日下部企画財政課長","answer":"これはあくまでも普通交付金ですので、性格として区分けはされますが、具体的にいうとあくまで一般財源ですので、ここに境はございません。基本的には、使途が特定されるものではございません。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました。私たちにわかりやすく三位一体の部分と分けて書いていただいたと考えると、このような額で入ってきて、従来どおりの都側との交渉で予算あるいは決算から算定されていくというのはわかりました。それから、先ほど区長のお話で５５％を基礎にしてこれからやっていく。これから学校改築について、都と区が協議できると理解していいわけですか。","respondent":"濱野区長","answer":"学校改築については、平成１８年度特別交付金２００億円とこの中にも多少見ているということで、都側としてはこれで一件落着だという認識だと思います。我々としては、学校改築と同時に人口構造の変化に伴って施設の変換がこれから出てくるだろう。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問","question":"最後に、企画にお聞きします。進行形にしているから、もう予算がそろそろでき上がってくると思いますけれども、平成１９年度の予算については、財調はどのように位置して再編成をされたのか、財調の額がわかっているのなら知らせてください。","respondent":"日下部企画財政課長","answer":"１月１１日にこのような形で役員会で基本的な確認がされた。それから、１月３１日の都区協議会ということで、もう基本的な都区間での確認は大体見通しが立ちましたので、昨年とは大分状況が違いますので、一応５５％、プラス３％を前提に予算編成をする予定しています。","id":"exchange-015"},{"speaker":"本田委員","kind":"質問・要望","question":"１点だけお尋ねします。ましてや三位一体に伴う減額分とか、補助金をなくして一般財源化の１％分とか言われても、なかなか理解できないところがあると思いますので、そういて点では今後のあり方に向けて、区側もいちどきれいに整理して、新たな問題提起のポイントを示していただきたいと思いますけれども、そういう点についてはいかがでしょうか。","respondent":"濱野区長","answer":"その主体として今の２３区の区割りでいいのか、あるいは２３区が分かれていても、事務組合だとか広域連合だとかいろいろな手法はあるわけですから、それを実施するための手法としてどのようなものがあるのかないのか、ないとすれば合併なのかという、最後に議論されるべきことが。","id":"exchange-016"},{"speaker":"本田委員","kind":"質問・要望","question":"今、合併の話が出ましたけれども、当委員会もそうですし、ほかの中でも区の合併というのは全然議論が出ません。そのような議論ではなくて、都区間で何が必要なのか、解決すべきなのかということをやっていただきたいと思っているのです。そういう意味で、先ほどどうですかということをお尋ねしたわけですが、もう一度、お願いします。","respondent":"濱野区長","answer":"やはり、品川区は自治権拡充の旗振りでもあり、先導的な役割を果たしてきた区としては、この議論をしっかりと進めていくことが重要であるし、できるだけ議論の中に入っていって、品川区の主張を述べていきたいと考えています。","id":"exchange-017"},{"speaker":"本田委員","kind":"質問・要望","question":"ただ、これからの出発点が特別区の自治権拡充が非常に重いものになるということを頭に置いて、新しい品川区は新しい区長のもとでちょうど切り替えでありますので、斬新な案を発信しながら自治権拡充を進めていただきたいと考えていますので、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"土井委員","kind":"意見","question":"一応の決着を見たということでは、都と区の大枠が決まった。これからその大枠を水平調整を含めた形ですけれども、どのように各区が自分の責任で配分等を含めて決めていくのかということをやっていかなければならないだろうと。そういう意味で、これからの方向、努力はどのような形で進むのかというところで何かありましたらお願いします。","respondent":"濱野区長","answer":"精神論としては私も声高に言いますが、実現となると難しいというのは現実です。しかし、これは一歩でも進んでいく必要があるという認識です。","id":"exchange-019"},{"speaker":"沢田委員","kind":"意見","question":"それからもう一つは、結構２３区の合併案というのは、大学教授だとかがいろいろな案を出していて、実際になるのかどうか不安が広がっているのです。平成１８年度の財調協議の見直しの中に、都区の区割りも協議しようということが書いてあって、先ほどは全然そのような要素は全くないと言われたのですが、これとは全然違うのかどうか説明していただけるとありがたいと思います。","respondent":"濱野区長","answer":"議論はすることになっております。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"特別区の区域のあり方、再編等と書いていて、ぎょっとしたのです。２３区側でこのような意見が出たことがありますか、俎上にのぼっていなかったと判断していいのか。その裏で財調が動いているわけですけれども、そこも含めて国の地方交付金に網をかけて変えようという議論はされているのでしょうか。そういう議論はあるのでしょうか、それは全然議論にもならないのでしょうか。","respondent":"日下部企画財政課長","answer":"つまり、前提になる制度が、今、委員がおっしゃいましたように大都市制度という、やはり土台になる制度そのものが２３区唯一の制度ですので、そのようなことも含めて、今、特に議論として、そのようなことは検討の俎上に上っていることは、私自身は聞いておりません。","id":"exchange-021"},{"speaker":"沢田委員","kind":"意見","question":"地方に行くと上下水道、交通、消防、警察、病院だとか、小さな自治体もやっています。東京だけは一体化というので、どう見てもおかしな問題で、ただこれは簡単にできないというのはよくわかりますけれども、今の中である程度議論をしておく必要があるのではないかと思いますけれども、意見があったらお願いします。","respondent":"濱野区長","answer":"今回、特別区と東京都の間の関係を見直すための大きな議論を始めようというきっかけは、そもそも主要５課題で残った大都市事務と区側の事務の議論がかみ合わないのは、お金の話をそこにすると議論がかみ合わないから、お金の話は来年度３％アップということで。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"やがて都区の中でも議論になるだろうし、特に石原都知事が再選された後は、必ずやってくるだろうと予想されます。もう少し先かもしれないけれども、区の再編についてタブー視はいけないと思うし、議論の仕方は難しいけれども、自治制度特別委員会なのか総務委員会なのか、そのようなところも出てくるけれども、それについてはやはり意識は持っているべきだと思うけれども、新しい区長としていかがですか。","respondent":"濱野区長","answer":"しかし、決してそれを逃げてはいけないと思います。受けた仕事を幾らでもやりようはあると思います。合併ということだけではなくて、やり方を十分検討していく必要があるのではないかと考えています。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/240034?Template=document&Id=5610#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":23387,"voices":60}},{"id":"h19-20070123-16","meetingId":"h19-cm01","date":"2007年1月23日","dateIso":"2007-01-23","committee":"街づくり特別委員会","time":"午後１時０３分～午後３時２６分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"密集住宅市街地整備促進事業に係る防災まちづくり計画（案）説明会等","agenda":"密集住宅市街地整備促進事業に係る防災まちづくり計画（案）説明会等","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"今回は事業化を求めていくんだと言っていますけれども、議会で採択をされてきたものとの、その辺の考え方をちょっと教えていただきたい。それから、実際にこの間の説明会の中で、補助２９号線について、これまで議会で採択をされた中身とは違う要望が生まれてきているのか、どうか。この辺を教えていただきたいんです。","respondent":"伊勢住環境整備担当課長","answer":"議会の請願の状況等も報告いたしたわけですけれども、今言った重要な路線であるということも説明いたしましたが、補助２９号線については廃止したほうがいいというようなスタンスで、もちろん全員ではないですけれども、何人かの方からはそういうような意見がございました。","id":"exchange-001"},{"speaker":"菊地委員","kind":"提案","question":"ちょっと今、世帯数も把握していなければ、経費についても把握していないというのは、一体住民の皆さんにどういうふうに説明したんでしょうかね。むしろ倒壊を防ぐ、全壊を防ぐ、密集市街地ですから、まずそういうことが前提になるほうが当たり前の話なんではないかと思うんですけれども、その辺の見解も教えていただければと思います。","respondent":"伊勢住環境整備担当課長","answer":"それで、こちらの「まちづくりニュース」でも、４ページにちょっと記載してあるんですけれども、下から２番目の土地利用及び建替え支援に関する項目の中で、丸ポチの土地利用及び建築物等に関する誘導の中に、下から３行目あたりに「建替えに併せた不燃化、耐震化とともに。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"それなしに、最初からもう火が出ることを前提にした考え方で遮断帯という言葉が出てくるわけですから、明らかにおかしいですよ。それから、議会の意思として、補助２９号線の計画は廃止しろって、住民の皆さんの中からも、つくるべきだというご意見が出てこないというのに、これを強引に押し進めるというのはいかがなものかと思いますけれども、そこをもう一度お願いいたします。","respondent":"岩田まちづくり事業部次長","answer":"街路事業をどうするかという視点でのご議論と、防災のまちづくりをどう進めるかという議論と、この補助２９号線についてごっちゃにしちゃうと、非常にややこしいことになってしまいますので、それをちょっと整理してご説明をします。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"この計画を廃止したら、どこかにつくらなくちゃならないと言いますけれども、単なる第二京浜のバイパスということであれば、そのものを別に想定をする必要もないんじゃないでしょうかね。少なくともこういう地域の中で、それがいくらでも活用していけるという体制づくりのほうが、住民にとってみれば、より活用できる制度になっていくんではないかと思うんですけれども、改めてちょっとお願いします。","respondent":"岩田まちづくり事業部次長","answer":"この計画自体は、よく読んでいただければおわかりになると思うんですけれども、こういう木造密集地域の木造住宅の耐震化と不燃化、こういったものは、他の地域に比較して、優先的に制度を投入して改修を図っていく、こういう方針は、もう既に区が打ち出しているわけです。","id":"exchange-004"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"そこの段階で、国と都に沿っていくのはわかるんですけれども、住民の場合は、特にこういうカラー刷りのきれいなものが出ちゃったりすると、もう感覚的にすぐにやって、うちの土地はどうなるんだという感覚になっちゃうものですから、その辺を丁寧に説明をしていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"この辺の協議会の皆さん、あるいは説明会に、この間、お出でいただいた区民の皆さんの意見というのは、どういうふうになっているのかを、ちょっと一つ伺いたい。その辺をちょっと伺いたいんですけれども。","respondent":"伊勢住環境整備担当課長","answer":"この６ｍ道路の位置ですけれども、やはり南側に東西に伸びる６ｍ以上の道路がないというようなこともございましたことと、この路線に防災活動広場もございまして、その辺の連携、あるいは地区全体の６ｍ道路のネットワークということも考えまして。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"例えば、沿線住民の方々の不燃化だとか、耐震補強だとか、そういうことをすべてやるとしたら、診断によって工事の内容、費用も違ってくるのは当然なんですが、その辺、どの程度考えられるのかというところで、総合的なその辺の検討というのはしてあるんでしょうか。していたら、ぜひお尋ねしたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"手元ですぐに出ないかもしれないんですけれども、基本的には１０年間の事業ということで、もちろんこれは相手方のあることですから何とも言えませんけれども、ここの地区ではおよそ３０億円の事業費です。建替えが幾らか、ちょっと今手元にございません。","id":"exchange-007"},{"speaker":"南委員","kind":"提案","question":"私が伺ったのは、この４ｍ道路から６ｍ道路にする防災生活道路Ｂの拡幅の関係で、拡幅するのに必要な費用。住民が受ける影響がどちらが少なくて、しかも、どちらが時間的に早くて、どちらが防災まちづくりにとって効果が上がるのかという、そういう検討をして、提案して、議論していくとなっているんだろうと思っているんですけれども、その辺はどうなんでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"この事業、国庫補助申請等を行うわけですけれども、まだ決まっているわけではないんですが、防災生活道路ＡとＢを足したものですけれども、道路整備費としましては、用地費、整備費、除却費、維持費等を合わせまして、道路整備費の計が１８億９,４００万円です。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"その点で、今、整備費だけだったので、もう一つのほうの試算があったら、教えてくださいと質問したつもりなんです。","respondent":"岩田まちづくり事業部次長","answer":"いわゆる、拡幅予定路線に面したお宅が老朽で家を建て替えようというときに、ではセットバックしていただけますでしょうか、セットバックしたところは、区で買わせていただきますと。その場合は、当然建て直すわけですから、これは補強ではなくて、新築になるわけですね。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"そういう議論がいろいろとできるような関係を、やっぱり尊重していただきたいということと、道路計画を広げることだけが何か先行しちゃうような、そういう進め方というのはあまり好ましいことにはならないと思いますので、何か今のまちづくり事業部次長の説明を伺うと、なかなかきちんとしていただいているのかなという気もしなくはないんですけれども、しかし、ちょっとその辺に不安を感じたので。","respondent":"伊勢住環境整備担当課長、岩田まちづくり事業部次長","answer":"非常に道路の拡幅の影響が大きくて、そこに再建が難しいという方につきましては、生活再建がその場でできるのかどうかも含めて、いろいろな手法でご相談に乗っていきたいと考えているところです。もしよろしければ、きちっとそこら辺を整理した資料として、次回にでも当委員会にお出しするということでよろしいでしょうか。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"きょうは後が詰まっているので、それで結構です。次回に、数字的なところでも教えていただければと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"今、南委員の意見で、資料として出すということですが、先ほど言っていた、豊町のほうの事業費とか、世帯数だとか、それから、補助２９号線そのものの事業費とか、その辺の数字についても、ちょっと資料として出していただけるようにお願いしたいんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/900262?Template=document&Id=6340#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":19563,"voices":40}},{"id":"h19-20070124-14","meetingId":"h19-cm01","date":"2007年1月24日","dateIso":"2007-01-24","committee":"行財政改革特別委員会","time":"午後１時０３分～午後２時３７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","topics":[{"id":"topic-01","title":"ついて、これまでの当委員会での主な発言を踏まえ、正副委員長で作成いたしました「具体的検討事項のまとめ」の案をもとに","agenda":"ついて、これまでの当委員会での主な発言を踏まえ、正副委員長で作成いたしました「具体的検討事項のまとめ」の案をもとに","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"品川大崎土木事務所跡ですけれども、視察も行きましたけれども、本当にあそこは区境ということで、当時、売却という話があり、私どもは売却も致し方ないかななどと考えていたところなんですが、急遽暫定利用していく、引き続き本格活用について検討を進める。何か先延ばしのようなことを感じるんですが、これは売却の話がだめになっちゃったからなのか。この辺について詳しくお知らせいただきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"全体的な検討の中で、今回、こういった形でもう少し検討を進めていくというような方向性が示されたものです。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"そういうことなら、わかりましたというふうにしておきたいと思います。大井土木事務所跡ですけれども、これは敷地面積が５７１.９３m2あって、大変に広いし細長い敷地で、これは移転するということですけれども、品川児童学園内の福祉工場しながわ清掃部門、現状ではどのぐらいの広さだったのか。その辺、ちょっと伺いたいと思います。","respondent":"堀越行財政改革担当課長","answer":"そういった形で、今考えておりますのが、先ほどご説明したとおり、デイサービス事業等を考えておりますので、大井土木事務所が近隣にあったということで有効活用を図るということで、こちらを利用するというような方向性で考えているです。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、品川児童学園そのものは半分くらいあくというような解釈でいいんですか。その辺もちょっと、こことは違いますけれどもお伺いしておきたいと思います。","respondent":"堀越行財政改革担当課長","answer":"ただ、発達障害児のいろいろな新しいデイサービス事業を展開していくに当たって、近隣にある大井土木事務所の跡を利用していくという考え方です。","id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"品川児童学園の発達障害のことなんですが、ちょっと委員会を逸脱するかもしれませんが、現場のほうからといいますか所管のほうからは、どういう事業の展開をして今後このスペースを利用していきたいというふうに上がってきているのか伺わせていただければと思います。","respondent":"堀越行財政改革担当課長","answer":"先般、１月２２日の厚生委員会のほうで、障害者基本計画の骨子についてご報告をさせていただいていると思いますが、その中でいろいろ療育のニーズの高まりですとか、区としてのそういった必要性の認識といった部分がありますので。","id":"exchange-004"},{"speaker":"川西委員","kind":"意見","question":"発達障害という単語で言うと簡単なんですけれども、非常に幅の広い今後の課題だと思うんです。それで、スペース確保だけじゃなくて人員体制とか、例えば今の品川児童学園通園の施設は在宅児童ですよね。それを今、おっしゃった学校まで広げるのか、あるいは保育園、幼稚園に入っている発達障害の人の相談体制の窓口を拡充するのか。そういう具体的な計画の上がり方をちょっと聞いておきたいと思っています。","respondent":"堀越行財政改革担当課長","answer":"今現在は、子育て支援センターのほうで相談を受け持っているわけですけれども、それをさらに進めまして、今、骨子の部分なので詳しいところはご容赦いただきたいんですけれども、そういった障害児の早期発見ですとか、相談支援体制の充実、計画的、効果的な相談。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味では、防災対策を一方で急がなきゃいけない。一方で、当面は業務委託の作業拠点として利用する。地震が起きたときにも出入口が使えるようになることを想定しているのかどうか。その辺の兼ね合いも伺いたいのですが。","respondent":"堀越行財政改革担当課長","answer":"それと、委員のご質問にありました部分の整合をとりながら、時期的なもの、そういった部分も含めて検討を進めていくという考え方です。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"今、現状はわからないんですけれども、この前見てきた限りですと、何となく通れる感じのようにも見えたんですけれども、当分の作業拠点と一方災害が起きたときの出入口の確保、結果としてまたどうするのかという議論もあるでしょうけれども、防災という面では、今どうするのかという議論もあるでしょうから、それの兼ね合いは今どんなふうにやられているのかなというのをもう一度だけお願いします。","respondent":"堀越行財政改革担当課長","answer":"今年度から防災まちづくりの対象エリアに指定されたということで、そういった出入口としての観点も含めて検討を始めたというところでございまして、繰り返しになりますけれども、戸越公園の国文学研究資料館の整備ともあわせまして。","id":"exchange-007"},{"speaker":"井上委員","kind":"確認","question":"最初に、品川大崎土木事務所跡の件ですけれども、先ほどの説明だと、金杉橋出張所のところがなくなったということですが、これは売却が前提なのか、それともここに本格活用について検討するというふうに書かれていますけれども、売却ではなく、品川区としてここを使っていくという考え方に変更になったのかということを確認させてください。","respondent":"堀越行財政改革担当課長","answer":"品川大崎土木事務所跡ですけれども、こちらについては全体的な施設の配置ですとか、事業について、立地環境等を含めて全体的な検討を進めていくというのがまず大前提です。","id":"exchange-008"},{"speaker":"井上委員","kind":"確認","question":"荏原土木事務所跡のほうは交渉に入っていくということで、決定段階ではない、今の時点ではそうだということで、もう一度確認だけお願いします。ちょっと答弁の言い方がよくわからないんですが、その辺をちょっともう少しはっきりお答えできるのであれば、ちょっとわかりにくい表現でしたのでお願いします。","respondent":"堀越行財政改革担当課長","answer":"それから品川大崎土木事務所跡については、総合的にどういった形で有効活用していけるかというのを検討する。売却については最後の手段というような形でお考えいただいていいと思います。","id":"exchange-009"},{"speaker":"藤田委員","kind":"質問・要望","question":"それぞれの土木事務所、将来的なことはまだこれから模索をしていくというような感じがしないでもないんですが、品川大崎土木事務所跡については地理的にも区境ということで、あの地域で施設なりどういうものが住民の要望としてあるのかはわからないんですけれども、やはりその辺も踏まえて売却の話はもうなくなってしまったということですので、この辺は慎重にぜひお願いしたいなと思うんです。","respondent":"堀越行財政改革担当課長","answer":"大井土木事務所跡の件ですけれども、こちらの建物のない部分については駐車のスペースとして利用する予定です。清掃部門の方たちが外に出ていくときに、箱形のバンに乗って出かけていきますので、今５台使用しておりますので、駐車場として利用するという形で考えてあります。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"私からは１点、３番目の項目の前文なんですけれども、これはどう読んでも小中一貫校６校構想の計画を進めるということを前提にしたような文章になっておりますので、ちょっと受け入れがたいなというふうに思っているんですが、やはり小中一貫校６校構想に関しては、まだまだ地域というか住民の皆さんの合意などもされていませんし、先日、私、小学校ＰＴＡ連合会の新年会に参加した場でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須藤委員","kind":"質問・要望","question":"その辺も整理をきちんとしていただきたい。今の３番で小中一貫校というのはおかしいよという話だけれども、現実的には一貫校跡地利用というのが、この行財政改革特別委員会が始まるときの審査項目の１つに入っていたので、その表現は表現として取り入れていかないと、整理の仕方としてはおかしくなってくるので、この表現は生かしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問・要望","question":"私は、この文で行けば、学校跡地の活用についてというところから入って何ら問題がないというふうに思います。それから１番の（１）のところで、十分な管理体制がとられるよう研究された上でという、この十分な管理体制というのがどういう意味でここにまとめていただいたものなのかちょっとわからないので、そこのところは確認をさせていただきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問・要望","question":"この管理という文章がどういうふうに管理されるのかというところが、ちょっとこういう部分に出された場合にどうなるのかなというのが疑問なんですが、学童保育クラブで荏原ほっと・サロンを地域の方たちが運営をされたときに、自分たちが担い手となったときに支援体制、運営をするのに対して相談機能が欲しいというような声があったので、地域の方たちが担う部分においては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"意見","question":"住民だけではやはりできていかない。さきの区長選挙でもありましたけれども、そこでの焦点の１つにあるぐらい率直にまだまだ意見が割れている段階、もちろん私自身は６校構想などやるべきではないという立場ですので、いろいろな議論を通じても一致した結論に至るにはまだまだ足りな過ぎるのではないかなというふうに思います。その２点。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問","question":"ですから、その跡地について我々はこの行財政改革特別委員会で議論をしてきたので、その構想が是であるか非であるかというのは文教委員会で云々とか、あるいは区長選で云々というのがありましたけれども、そのことを訴えた区長がそのまま政策的にやっていきますということですから、小中一貫校６校構想については計画としては生かされてきていますよ。ですから、この文章でいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"６校構想とおっしゃいますが、区長側が進めている話であって、じゃあ我々議会がどうするのかということでこの特別委員会が設置されているのであって、区長が６校構想をあげているからそれを追認する。そういう議論は違うだろうなということを今の意見で率直に感じました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"区長があげていて、議会でそれを予算化したり、整理をしてきているんですから、何も区長が右だと言ったから我々がはい、右ですということではない。そういう政策構想がなされてきていることについて、今までの経緯では議会でこういった方向性というのは認めてきていますよと。ですから、そのことについて当委員会で整理をさせていただいたというような考え方でいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"議会で認めているとおっしゃっていますけれども、文教委員会でも行財政改革特別委員会でも、またそれぞれの地域でいろいろまちの意見を聞いても、私は議論が分かれていると感じています。でも我々も我々の意見もこの間、立場を述べてきているわけですから、議会が認めたというひとくくりでくくられてしまうと、私自身も困ってしまいますので、そのことだけは伝えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"須藤委員","kind":"質問","question":"議会で認めたというのは、それぞれの委員が代表で出てきて、最終的にはいろいろな意見があるけれども、民主的には多数決という形で結果を整理していくんですから、それが議会としての答えです。ですから、Ａさん、Ｂさんが認めてないからこれは認めてない話だということにはなってこないので、６校構想というのは議会の中での収れんの１つであるというふうに来ていますので、この文章でいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、先ほど須藤委員が言われたように、私たちはこの委員会でいろいろな議論をして、指摘をして、質問もしてきました。そういうふうなことをどうしても委員会として求めていくのであれば、表現としては１番の自主的管理のところについても、そんな事細かい事情、例えば先ほど東大井地域の話が出ましたけれども、東大井と西大井では地域事情も違うでしょうし、町会の協力体制も違うでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"ですから、理事者に対して質問があるかどうか先にやっていただいて、その質問を解決した上で委員同士がするものだと思いますので、説明者として理事者がここに同席してこの議論をずっとやって聞いていく必要はないのではないかなというふうに思うんですけれども、質問は多分まだあると思いますから、そこを先に解決されて、この文章に入ったほうがいいんじゃないかなというふうに思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、公有地というものがどういうものかという論議が、一番最初のときに大きなところでどうとらえていくのかという論議がされましたよね。意見がもし分かれている部分であったら、削除をするか、両論併記という形で、やはりこの委員会での１年間の議論が反映されるような中身にしていただきたいと思うんです。そこのところをお願いしたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"中島委員","kind":"質問","question":"それで、小中一貫校の６校構想というもう既に２校進んでいるわけです。ただ、確実な決定というのはまだ後の４校というのがこれからだと思うんですね。そういったことで、私はこの小中一貫校６校構想は既にあるわけですから、６校構想の計画などにより生ずる学校跡地の活用ということで、そうすれば皆さんのご意見も反映されるのではないかなと思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"川西委員","kind":"質問","question":"その中でちょっと意見を申し上げますが、後でまとまった段階でちょっと理事者のほうに関連質問をしたいと思ってずっと待っていましたが、先にここのまとめの段階の意見を申し上げます。そういう段階で会派の中でも意見が出たのが、一番言っているのが３番なんですね。そういうことを出すべきだというのが私どもの意見ですので、絶対３番は抜けないものと考えています。終わりましたら後でちょっと質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"それが原小学校だけではないという議論をこの中で十分にしたということですので、そこは十分に尊重していただきたいし、構想であって決定ではない部分によって、このようなことを盛り込むということは、計画として、施策として出される部分が当然のようにこういう文章に載ることというのが問題だと思いますので、そのことを正副でよく検討していただいてまとめていただければというふうに要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"ですから、今のお話のように学校跡地の活用についてはというと、極端に言えば、どこの学校でも統廃合されてきても、その跡地についてはそういうふうに考えていけばいいんだよというようなものをやることなので、それでもいいということであれば、そういう表現になっちゃうけれども、そこまで当委員会では整理をしていないと思うので、あくまで今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"提案","question":"今回の６月の最初の提案においては、原小学校も旧土木事務所の跡地も同等の立場なんですよね。その後で、品川保育園の跡地が急に浮上してきて検討されたという意味では、何も今回、学校跡地を強調していたわけではないと思っているんです。広く公有地の活用のあり方というとらえ方からすれば、もしそういう懸念があるのでしたら、学校跡地の活用についてまでもカットをしていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"中島委員","kind":"質問","question":"今のご意見なんですが、この委員会では大田区の学校跡地、そして台東区の学校跡地を視察してまいりました。それぞれその地域性を生かした非常に効率的な活用をされていたと思うんです。ですから、この学校跡地というのをここで外してしまったら、この委員会は何をやってきたのかということになってしまうと思いますので、これは入れるべきと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"中塚委員","kind":"意見","question":"ここに６月７日の一番初めの行財政改革特別委員会の議事録があるんですけれども、委員長のほうから公有地等の活用につきましては、主に原小学校および旧土木事務所などについてということから始まっているんですよね。やはり本来付託された委員会の原小学校および旧土木事務所についてという公有地の活用を中心にすべきであって、３というのは必要ないんじゃないかとも思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"藤田委員","kind":"質問","question":"いろいろ議論が出されていますが、平成１８年度の当委員会でどういうまとめをするかというのがポイントになると思うんですね。今、正副委員長で出していただきました１番と２番、これは現実にもう動いているわけです。非常に好意的な人たちもいらっしゃるわけですから、当委員会で現時点の将来性について、責任を持ったまとめをしていく必要性があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"川西委員","kind":"質問","question":"具体的な質問になって悪いんですが、２番の品川保育園のことなんですが、２番の（３）のことです。これは文章も結構なんですが、２項道路なんですよね。入り口から入り口まで４ｍつながらないのはわかっているんですけれども、この改修を機会に品川保育園の用地の部分だけでもセットバックはしていただけるのかどうか。それからもう一つ質問があります。だれが思ってもそうなんです。","respondent":"堀越行財政改革担当課長","answer":"道路の部分についてもセットバックも含めまして、そういった方向性で検討をしているものです。それと、もう１点、八潮のほうにつきましては、現在、庁内で検討の内部の会議を設けておりまして、今後、またいろいろな状況を見ながら検討を進めていくという状況にあります。","id":"exchange-032"},{"speaker":"川西委員","kind":"意見","question":"ありがとうございました。では、ぜひ２番の（３）のほうは、ちょっと半端に広がることになるけれども、やはり率先して２項道路のセットバックはしていくべきだというふうに、長年あそこに近くにいまして思っています。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"それをまた運営にどう反映させていくのか。そこの１章は（４）にするのか。ですから、（２）のところは、僕は全部とっちゃってもいいと思っているんですけれども、ノウハウを最大限生かせる仕組み、その民間のノウハウが、談合だ、不二家だ、ちょっと前の耐震偽造、こうやってあるわけですから、これはちょっと原小学校の運営についてまだまだ議論が足りなさ過ぎると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"中塚委員","kind":"意見","question":"すべての会派から文章を正副委員長に提出して、それをもとにして検討または比較の資料を含めて出していく。そういう進め方はいかがでしょう。","respondent":"本多委員長","answer":"ただいま中塚委員から提言がございました。このまとめを進めていくに当たりまして、当然、こうした委員会の場で活発な議論をいただいてまとめていくという考え方で進めてまいりましたが、ただいまの提言につきまして何か意見があれば、お願いいたします。","id":"exchange-035"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、大局的にこれを全部どうのこうのということはなかなか困難だろうと思うので、おおむねこういった内容で結構で、正副委員長でまとめるといっても、それを大幅にどうのこうのするというのはかえって混乱を招くと思うので、ある程度こういう方向ですよというのを出しながらしていかないと、少数意見は少数意見で載せていただいて構わないんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"井上委員","kind":"提案","question":"結果そうなっていることに追随してどうぞということがもし委員会の中で、私もごめんなさい、ちゃんと議事録を確認していないので、そういう議論が大多数がそうであればいいんですけれども、そういう感じではなかったかなというふうに思いますので、ここは慎重にお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、（２）のところの民間事業者のノウハウを最大限生かせる仕組みづくりをと書いてありますが、今、井上委員からご意見がありましたけれども、ここの行財政改革特別委員会のところで、幼保一体化のところで福祉法人なんですねと確認をしたら、そうですと言った状況にもかかわらず、厚生委員会の中ではそこよりもさらに民間委託が進んでいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"率直に民間委託のことについて議論もありましたけれども、やはり全体としては、特に指定管理者のところでの議論が象徴的ですけれども、知らない業者が出てきたときに、議会としてそれをどう審査するのか。須藤委員の話でもあるんですけれども、民間委託、市場化テストが法律になって、だけどすぐに飛びつくのはどうかと。ですから、まだまだ（２）のところは私は要らないと強調しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"中塚委員","kind":"提案","question":"それぞれ会派の意見を持ち寄って正副委員長に出すという、先ほどの僕の提案は結果としてどうなったのか。意見があれば出してくださいということなのか。委員長にもう一度どういうふうに、次回に案をつくっていただくのか、その辺もう一度説明してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"須藤委員","kind":"提案","question":"それは我々も地域の皆さんの声を入れるということは必要だと思うので、そうすれば３番の中に、跡地については僕らは全体的な視点と地域の特性を踏まえというような表現になりましたけれども、全体的な視点と地域の特性や地域住民の声を踏まえ、活用のあり方を総合的にというような文章にしてくれば、今後はそういう形を基本に考えてくださいという当委員会としてのまとめになってくるので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"藤田委員","kind":"質問","question":"ですから、それはもうベースにあるわけです。福祉施設云々とありましたけれども、やはり考えの相違というのはありますから、それも集約してまとめていかなければいけないわけですから、その辺を念頭に置いて、ぜひお願いをしたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-02","title":"の民間委託等に関すること","agenda":"の民間委託等に関すること","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"私は提言のほうの１、２、３はいいと思います。議論を十分にまとめていただいたと考えていますが、ちょっとここだけは慎重に皆さんで検討していただきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問","question":"２番目のところでやはり気になったのが、これも同じでサービス提供後の評価の仕組みづくりのところが、せっかくここまで書いていただいているわけですから、職員の部分と委託効果が発揮される仕組みづくりの中の１つとして、提供後の評価体制の仕組みづくりも入れていただいたほうが、より私たちの意見が具体化されると思いますので、述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に、今回のところでは、民間委託に関して前提となる仕分けの基準という、さっきお話もあってその中にも入るのかもしれませんけれども、例えばどういうところが委託にふさわしくて、どういう部門は直営とかきちんとした正規雇用で守らなくてはいけないのかという論議も、ぜひしていきたいなと思っているのが、やはり幼稚園とか保育園、児童センター、子どもたちの育ち。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"須藤委員","kind":"質問","question":"まとめですから、井上委員からもいろいろと、その結果というところから下を、我々は民間委託に関することで議論してきましたので、民間委託の推進に当たっては社会経済情勢の変化を踏まえながら、真の区民サービスの向上につながるよう考えていかなければならないとか、必要性があるとかというような形で、真の区民サービス、それは単に経済的な効率性だけじゃないよと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん民間委託と言えば、これも区側の課長も部長も答弁していますけれども、当然新たなチェック機関、報告書を信じればいいという問題ではない。先ほど委員長のお話があったのは承知していますけれども、民間委託の推進が区民のサービス向上に直結はしないと思いますので、ぜひ今のそれぞれの委員の議論を踏まえてまとめていただきたいと思います。繰り返しで済みません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"中で出ていたのが、慎重に整理をすべきではないかというのと、問題点ありというところで、これをさらなるというまとめにつながるような深まりはないし、また理解も、まだ国の法律が通ったばかりで中身が理解されていない、私はそう思っています。論議も不十分であるというところでは、こうやって並立して載せるべきではないので、今回、これは外してもいいのではないでしょうか。","respondent":"本多委員長","answer":"その点につきましては、法改正の概要ということで説明を以前いただいて、今後の各自治体の課題ということでしたので、あえて注視しつつ総合的に分析というような文言を使わせていただきました。ただ、言われる意味はわかりますので、再度検討してみます。","id":"exchange-048"},{"speaker":"中島委員","kind":"質問","question":"やはり行財政改革という視点の中で、いろいろな社会の流れがある。それを注視しつつ事業の仕分け、１つのことを委託するに当たってもどの部分を委託するのか。しかも、住民サービスの向上と効率的な運営という、これが一番大事な目的ですから、その辺のところがしっかりこの文言の中に入っているので、私はこれでいいのかなと感じているところなんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう意味では、最初の前文のところの、結論に至りましたというのはちょっと検討していただきたいという意見もありましたけれども、１番のところでの、私もさっきから気になってはいたんですが、さらなる民間委託等のあり方というのが入っていますけれども、普通にぱっと見て民間委託をさらに進めていく方向というふうにしかとらえられないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/190566?Template=document&Id=5814#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":27393,"voices":84}},{"id":"h19-20070223-3","meetingId":"h19-c-budget","date":"2007年2月23日","dateIso":"2007-02-23","committee":"予算特別委員会","time":"午後３時０３分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/562921?Template=document&Id=872#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":2294,"voices":17}},{"id":"h19-20070226-6","meetingId":"h19-cm02","date":"2007年2月26日","dateIso":"2007-02-26","committee":"区民委員会","time":"午前１０時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","topics":[{"id":"topic-01","title":"第１２号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第１２号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"意見","question":"品川区の創業支援をやってもう何年にもなるんですけれども、トータル的にどのくらいの事業者が品川区内で創業支援の対象になってきているのかという実態ですね。それをちょっと知りたいと思います。","respondent":"金子産業振興課長","answer":"ですので、年によって傾向は若干変わってきておりますが、また創業支援資金についても、要件を少しずつ変更してきたので単純な比較はできませんが、この経済情勢の中から増加の傾向にあるということが言えるだろうと思います。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"ついでに聞けばよかったんですけど、年齢だとか、業種だとか、そういうところも、融資に限らず全体的な状況がどういうふうになっているのかというのが知りたいんですけれども、わかれば教えていただきたいのと、特に私自身関心があるのは、若い方々の創業というところも求められている実態もあると思うので、その辺も教えていただければと思います。","respondent":"金子産業振興課長","answer":"創業支援についての年齢と業種の傾向なんですけれども、統計としてきちっととっているわけではないんですが、創業支援施設も含めて申し上げますと、中年の方から、いわゆる団塊の世代の方もいらっしゃいますが、若い方が特にＩＴ系のもの等で創業を志している。","id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"創業支援ということで拡大していくということについては、すばらしい、いいことだということを大前提にあえて質問いたします。中身はいいんですよ。これは何回もいいますけれども、だけれども、そういうことについても考えておかないといけないのではないかと思いますので、ちょっとお伺いをしたいと思います。大ざっぱなことで結構です。","respondent":"金子産業振興課長","answer":"見込みですけれども、この件に対しての問い合わせが今年度で１０件ぐらいございました。先ほども申し上げたとおり、創業支援資金は増加の傾向にありますので、予算上の見込みとしましては２０件を見込んでいるところです。","id":"exchange-003"},{"speaker":"土井委員","kind":"意見","question":"そういうものが多いわけなんですけれども、本当はアイデアと企業の将来性にかけて融資をしてあげるということが本当は必要なんだと思う。そういうことになっていけばいいなと思うので、そういう視点ももし加えていけるようだったら、よろしくお願いしたいと思います。今すぐということじゃないかもしれませんが、意見だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問・要望","question":"新しく創業するわけですけれども、２つの会社を合わせた場合に、総量の枠というのがあるのかどうかを伺いたいのと、もう１つ、本年６１件、ＩＴと飲食店ということで業種別で伺ったんですけれども、その飲食店についてちょっとお伺いしたいんですが、それは飲食店の中で資金を必要とする飲食店の方は、個店があって新たに出店をする方がいるでしょうし、また新たに自分自身で会社を始める場合。","respondent":"金子産業振興課長","answer":"２点のご質問ですが、最初の質問なんですけれども、今回の創業支援資金の場合で、要するに今回は既存の会社を持っている方が新しく会社を起こす方を新たに対象にするというわけですけれども、先ほどちょっとご説明申し上げたのは、今。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"次に２.改正内容の(1)2)で、既に企業の代表者である者が別の中小企業を新たに品川区内に創業する場合、別の企業をということなので、もとの会社は１つで、新たに別の企業をということなので、大もとに対してはその総量の規制というのはないんですか。","respondent":"金子産業振興課長","answer":"当然、融資の希望額という形で融資の希望者が申請してくるわけですけれども、その場合に、創業支援資金は従来から枠はありますけれども、この枠の中で既存の企業の業績等を見て、相談員がその融資希望額が適当であるかどうか、もし融資希望額が多過ぎるのであれば。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問","question":"そういう傾向は今の話を聞いていると、どうもあまり多くはないのかなと思うんですけれども、２０件を見込んでいるということでありますが、内容的にはどういう傾向をとらえておられますか。","respondent":"金子産業振興課長","answer":"これは品川区だけの問題ではなくて、例えばお隣の大田区についても、この同じ期間で６,０００件から５,０００件に減るということで、城南地区あるいは都内ではこういった傾向が続いているのかなと考えているところです。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"創業支援資金ですから、本人の負担の利率をなるべくなら軽くスタートすれば、負担が軽いほうがいいんだろうなと思ったんですが、ここは高く設定すると書いてあるので、やっぱりそれだけの負担があるからそうするのですと、理解をしないといけないのかどうか、その辺を説明いただけますか。","respondent":"金子産業振興課長","answer":"ここに書いてあるとおりなんですけれども、また委員がご指摘のとおりですけれども、既に会社を経営している方を今回新たに拡大しようとしているところですので、一般の今までのさらに創業される方とは、経営のノウハウ、経験等が違うということで。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"そうすると、今の説明からいきますと、本人の負担率が０.５％高くなるわけですかね。０.５％ですから、本人の負担率が０.４％にもかかわらず、それよりも高い０.５％プラスしたら０.９％になっちゃうから、そうすると、借りる側にしてみると、高過ぎやしませんかというか、そういうことはないんですか。","respondent":"金子産業振興課長","answer":"先ほど申し上げたとおり、今回の対象の方については１.０％としていますのは、一方で創業支援というのは従来の方よりも、創業を大いにしていただこうという基本的な考え方がありますので、従来の資金よりも０.５％は低いという格好で、その間に設定しているわけです。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問","question":"区としてそういうふうに設定したとしても、今度は信用保証協会の話が出ていましたけれども、そういう設定の仕方、設定をする場合というか、そういうときは信用保証協会のほうとも相談をして、利率や何かを決めておくのか、主に信用保証協会は信用保証協会で重要な審査をおやりになって、独自にいろいろやってもらって、区は区としての考え方に基づいてこういう利率等については設定をしていくものなんですか。","respondent":"金子産業振興課長","answer":"区と信用保証協会の関係の部分にもなりますが、当然本人の負担利率によって返済額が変わってくるわけですから、その返済額に対して、保証協会としては返済能力があるかどうかということを審査していくわけですので。","id":"exchange-010"},{"speaker":"堺委員","kind":"確認","question":"もう１点、(2)の区内の業歴要件の廃止の3)の改正理由のところなんですが、企業の区内での事業展開を支援すると。前段では区外での業歴が１年以上ということなんですが、これはあるのかないのかも含めて、これは確認です。精算の肩がわりを区でするなんていうことはないですよね。利用者としては、大田区で借りたものもあるし、品川区で新たに借りたものもある、そういう解釈になるのですか。","respondent":"金子産業振興課長","answer":"最後のほうで委員がおっしゃったとおりでして、私どもに融資の申し込みがあった場合には、例えば隣の区で融資を受けたものについて続いていれば、それを前提にして返済能力があるかどうかを審査してお貸しするかどうかということになりますので、それを一本化するということは。","id":"exchange-011"}]},{"id":"topic-02","title":"第１３号議案 品川区立工場アパート条例の一部を改正する条例","agenda":"第１３号議案 品川区立工場アパート条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"もう１つ、家賃のところなんですけれども、条例上はこの金額だけど、現実的には改めて改正後の人の金額にということで、４割減ぐらいの金額に設定されているんですけれども、なぜそういう措置がされていたのか、条例上の額を、そこそのものを改正しておかなかったという、その辺がよくわからないので、教えていただきたいと思います。","respondent":"金子産業振興課長","answer":"工場に関しましても、既存の方については、こちらで出ていただくということではなくて、既存の方は従来どおりの契約権限の中で、円満に使用されている限りはそのまま継続していただこうと考えています。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"経過はわかりました。ですから、追い出しはしないという、そこは当然だと思うんですけれども、その辺のところで、なかなか私としては判断というか、それがちょっと引っかかるというか、有効活用という点ではそれは大事なことだということは思うんですけれども、そういう状況の中で４月１日からですよね。","respondent":"金子産業振興課長","answer":"そういう意味で、誠意を持ってご説明して対応していきたいと考えています。繰り返しでくどいようですけれども、私どもは強権的に出ていただくということは考えてございません。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"それとあわせて、満了までということがあったんですけれども、最大が２０年ということなんですが、大体入居されて創業されている方々は、創業というか、工場を経営されている方々は、満了までどのくらいの期間があるのかどうかということを伺いたいんですが、なかなか一般の工場の家賃等と比較する機会があまりないのでわからないんですけれども、品川区内で今。","respondent":"金子産業振興課長","answer":"私どもとしては今の条例の考え方でいきたいと思っているところです。そういう時期が近づいてきましたら、その辺については、入っている方々のご意向も伺いながら、きちっと対応していきたいと考えています。","id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"そういう意味では、実態にも合わせた仕組みになるのかなと思うので、そのこと自体はそんなに私も問題にしないとは思わないわけですけれども、そういう考え方になりますと、なんといっても、今いる方々は少しきちんと最後まで面倒を見てあげないと、満了まで面倒見ることも可なんですよという発想で、追い出すことはないんですよというのではなしに、可なんですよというのではちょっと違うような気がするので。","respondent":"金子産業振興課長","answer":"今回その仕切りをとりまして、ほかの住居と同じ広さにして全体を事務室にしようということで、料金が半分から倍に変わってくるという意味合いの表で、ちょっとご説明しなかったので申しわけないんですけれども、そのようにご理解いただければと思います。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"もう１つお伺いしたいと思うんですが、いわゆる住居ということで、これは住居と工場です、それでお使いくださいということで一応の契約になっているというわけですが、事務所のような形でお使いになっていたということなんでしょうか。","respondent":"金子産業振興課長","answer":"４戸の方については、住居として使用しながら事務室としても使用しているという現況でありましたので、そういう意味ではこの要件からは逸脱してはいなかったのかなと思いますが、先ほど申し上げましたとおり、事務所化することについては。","id":"exchange-016"},{"speaker":"土井委員","kind":"質問","question":"となると、今度は完全に事務所になるわけですよね。事務所として貸すときのお値段と住居で貸すときのお値段というのは、世間相場的にも違うんじゃないかなという感じがしないでもないので、そのことと、どういうお考えなのかを聞かせてください。そこら辺は容認をしつつもお伺いしますので、よろしくお願いいたします。","respondent":"金子産業振興課長","answer":"そういう意味では、先ほど申し上げましたとおり、家賃そのものが今、品川区内でも上昇傾向にありますので、この部分については、住宅か事務室とかいう前に、そもそも安い設定でしておりますので、そのようにご理解いただけたらと思います。","id":"exchange-017"},{"speaker":"本田委員","kind":"質問・要望","question":"もう１つは、課長はさっき弾力的に対応するですけれども、創設当時からおられる方々で、２０年にまだ間がありますけれども、出ていかなくちゃならないというときに、適切なところがあればいいけれども、なかなかそういうことも困難ということも出るようなこともないとは言えないわけで、そういう点では使用期間のあり方、更新については、弾力的に将来考えていくということは。","respondent":"金子産業振興課長","answer":"それから創設当時の方々、先ほど申し上げましたとおり、平成２４年には２０年になるわけですけれども、今の考え方としましては、条例どおりきちっとというというふうになりますけれども、これについてはその時点でご相談をしながら、しかるべき対応をしていきたいと考えています。","id":"exchange-018"},{"speaker":"本田委員","kind":"質問・要望","question":"そういうことなどを考えますと、隣の大田区ではわりと大規模な工場アパートを新たに整備されましたけれども、大田区の場合、品川区とはちょっと規模が違うんですけれども、先ほどもお尋ねして工業が減ってきているという状況も、品川区のまちの状況から見て、いろいろ適切な判断はしなくちゃならないけれども、工場アパートの持っている役割というのは私は大きいと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"堺委員","kind":"質問・要望","question":"これについては、平成８年の第４回定例会の一般質問のときに、工場使用料や住宅使用料の料金設定についてお伺いした経緯があるんですが、そのときにもそのときどきの状況に応じた形での料金設定をぜひお願いしたいという形で、利用者側に立った形での要望をした経緯があるんですが、そういうことから、使用料の現行と改正後で、今は改正後の料金設定になっているということですが。","respondent":"金子産業振興課長","answer":"１点目の創設創業時から入居されている方についての弾力的な運用というのは、先ほどご説明申し上げましたとおり、委員ご指摘の趣旨で対応してまいりたいと考えています。","id":"exchange-020"},{"speaker":"堺委員","kind":"質問","question":"適切なということなんですけれども、そのモデル工場ができた段階での傾斜家賃というのは３年単位で料金設定を見直していきますよという考え方を今も区は持っていますね。ですから、今回、施行は工場部分については平成１９年４月設定です。あるいは毎年見直していくんだと。その辺はどういうふうに我々は理解すればいいんでしょうか。","respondent":"金子産業振興課長","answer":"そういう意味では、いろいろな要素も全部含めて、２年あるいは３年なり、そういったタイミングで料金設定はどこが適切なのかというのは、その都度私どもとしては検討していく必要があるという意味でお答えしたつもりですので、よろしくお願いいたします。","id":"exchange-021"},{"speaker":"堺委員","kind":"質問・要望","question":"ちょっと要望しておきます。ですから、今回新たに形になるにしても、この使用料等については２年ごとに見直しますよと。何かその辺は明確にある程度文章化しておいたほうがいいのかなと。その辺については何も触れないでおいたほうがいいのか、その辺はどうなんでしょうか。入居される側に立って考えると、例えば２年ごとに見直しますよと、はっきり打ち出してもらっておいたほうがいいような気がするんです。","respondent":"山田区民生活事業部長","answer":"ですから、こちらのいわゆる使用料についての設定も、やはりそういう方々の使い勝手の様子も見ながら、年限を切ってということではなくて、ある意味ではフレキシブルに対応できるような形で、なるべく育てていくという視点で考えておりますので。","id":"exchange-022"}]},{"id":"topic-03","title":"４番目、第１６号議案 品川区国民健康保険条例の一部を改正する条例","agenda":"４番目、第１６号議案 品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"土井委員","kind":"質問","question":"これがまずもって大事なんですね。これがどう決まるかということでは、国や都の支出金がある。その辺の決まり方についてちょっとお伺いしたいのと、保険料率等で均等割等が減額をされるという措置はそれなりにすばらしいことなんですけれども、その減額分を補てんするための資金は、だれがどのように負担をした形になっているのか、それが区の繰入金なのかどうかということを含めて教えてください。","respondent":"原国保年金課長","answer":"保険料の決め方の関係からまず説明していきたいと思うんですが、まず保険料で算定するものということで、まず国のほうで基本的なものを定めてあります。","id":"exchange-023"},{"speaker":"土井委員","kind":"確認","question":"総額としての支出部分の算出シートでいけば、２６５億円という数字は品川区が実態としてかかるお金ですよと、支出するお金ですよと。その分が今のお話では４分の３。さらにその下の部分のそのほかに要する費用のうちの、先ほどあった高額医療費とか、出産育児、葬祭費、そういうものは区で負担をするということを原則として繰入金を入れるんですよということでよろしいんですか。ちょっと確認させてください。","respondent":"原国保年金課長","answer":"今の説明が悪くて大変申しわけございません。医療費等につきましては、国のほうで３４％、それから東京都のほうで６％ということで、４０％が医療費に係る分ということで、負担金および補助金でくるようになります。","id":"exchange-024"},{"speaker":"土井委員","kind":"意見","question":"今の話をもう１回繰り返して恐縮なんですが、国や都からは４０％が来ることになっていますよ。プラスして減額分の４分の３は国や都から来るんですよ。４分の１は区が負担するんですよということでよろしいですね。","respondent":"原国保年金課長","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"１０ページのところの国保加入世帯の数が８万３,４９２と出ているんですが、平成１８年と比較して増えていると思うんですけれども、そして減額措置、７割減額等々があるんですけれども、減額世帯も国保加入は高齢者が中心で、どんどん増え続けているという実態の中で、７割減額、５割減額がそれぞれどういう推移になっているのか伺いたいのと、そして、その下に減額賦課非該当世帯ということで、この数は。","respondent":"原国保年金課長","answer":"こちらにつきましては、収納状況のほうでご説明しますと、平成１６年の収納率が８４.６８％、これは前年ですけれども、そちらのほうが平成１７年度が８４.９４％ということで、平成１６年に比べて平成１７年が０.２６％収納率が上がっているです。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"それぞれ数字を教えていただいてありがとうあります。そして、この１０ページのところの７割減額も微増というおっしゃり方をしましたけれども、増えている。そこはかなり経済状況の厳しい低所得者の方々のところの実態をどう見るかということが大事だと思うので、改めて確認をしたいということで、具体的な数字も申し上げて確認をさせていただきたいと思います。その点の見解もあえて伺いたいと思います。","respondent":"原国保年金課長","answer":"そういったところを、平成１８年度ですと、特別区の課長会のほうでも国に要望して、ぜひ激変緩和をとってほしいということで、これは特別区だけではなくて、いろいろなところからそういう要望の中で実施されたと思いますけれども、平成１９年度のこちらの軽減措置につきましては。","id":"exchange-027"},{"speaker":"南委員","kind":"確認","question":"住民税が１万６,５００円、国保料が４万８,２４４円、介護保険料が４万６,８００円ということで、先ほどご紹介したように１１万１,５００円で、この３つの税金を払う、そのトータルで見たときに２.８倍になっているんですが、国民健康保険料だけで比較をすると５倍になっているんですけれども、これは具体的にこういう状況で考えていいのかどうかをちょっと確認したいんです。","respondent":"原国保年金課長","answer":"激変緩和によってどのくらいの影響が保険料に対して起きているかですけれども、例えば３００万円の課税所得の方であれば、５万円を住民税額で出たものから差し引いて計算するわけですから、５万円の１.２４倍、こちらの分が年間の保険料として減額される数字ということで。","id":"exchange-028"},{"speaker":"南委員","kind":"質問","question":"とりあえず私の質問は終わりにしたいと思いますけれども、改めて今回の国保の料金の改定というのは、税制改悪の大きな影響で、とりわけ低所得者の方々の暮らしを直撃するんじゃないかと私は思うんです。５００万円の世帯の方は、逆に保険料が増えているということになっていますので、いわゆる中間所得と言っていいんでしょうかね。５００万円の方々、平均的な所得なんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"本田委員","kind":"質問・要望","question":"そういう点ではこの滞納対策問題、収納率の問題、当然２３区全体としての検討などいろいろやられたと思いますけれども、十分その辺のところをいろいろな緩和措置はとったけれども、対応を切にやっていただきたいということを、この説明を聞いて改めて思いますので、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-04","title":"５番目の第２６号議案 品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","agenda":"５番目の第２６号議案 品川区廃棄物の処理および再利用に関する条例の一部を改正する条例","exchanges":[{"speaker":"土井委員","kind":"意見","question":"いろいろなサービス業のほうは、翌日配達とかありますから、そういうふうにはならないにしても、その辺はどうなっているのかなということと、今まで集めてくるのに相当手間暇がかかるわけで、そういうのが過重な状況にあって、過重と言うべきかどうかわからないけれども、日数等がかかるのもそういう関係もあったのかなという気もしないでもないので、その辺も含めてお聞かせください。","respondent":"島袋品川区清掃事務所長","answer":"現在では１８日間、大体そのくらいかかってしまっている。我々としましては、なるべく臨時車等を含めまして、現在４台でやっているところを、週に１回か２回は車を２台増やして対応している。もう１８かそれ以上に。","id":"exchange-031"},{"speaker":"土井委員","kind":"意見","question":"そんなにたくさんあるというのは実感としてあれだったんですけれども、それが影響が出るほどになるかどうかというのは大変難しいんですけれども、そうすると、日曜日に持ち込むとして、受付は日曜日の前の日でいいのかどうなのかというのも含めて、それらの設立等がうまくいくかなということと、ごみの処理券をどこかで買うわけですけれども。","respondent":"島袋品川区清掃事務所長","answer":"資料の２ページ目に持込の流れが書いてありますけれども、現在の粗大ごみと同じように、粗大ごみ受付センターに今度の日曜日に持ち込みたいと。","id":"exchange-032"},{"speaker":"土井委員","kind":"質問","question":"そうすると、いずれにしても集めに来ていただく場合であれ、持ち込む場合であり、粗大ごみ受付センターのほうに受付するんですよと。今までですと、清掃事務所の方が持っていくわけですからそのままでいいわけですけれども、一般の人が持ち込んでくるわけで、資源化センターの中に入ってくるわけですね。入ってきてどこでもぐるぐる行かれちゃっては困るし、その辺はどういうふうにやるんですか。","respondent":"島袋品川区清掃事務所長","answer":"それを貼りまして、資源化センターの入り口から車で入ってきてもらいまして、そこでおろして受付をして、帰りは清掃工場の出口をちょっと使わせてもらいます。そういう流れをつくっております。清掃工場側にはこの話をしていまして、そういう流れが滞らないように考えております。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"今の土井委員がおっしゃった出入り口のところが私もよくわからないので、この間、区民委員会で行ったあそこの正門というのかしら、そこから入って、そしてすぐ左に曲がっていろいろ見た、あの辺を資源化センターと言っていいんですよね。それで、帰りはまたちょっとこう行って、今度は左のほうを通ってこちらの湾岸道路に出るということでいいんですかね。ちょっとそこがわからないんですが。","respondent":"島袋品川区清掃事務所長","answer":"今、南委員おっしゃったとおりです。資源化センターの入り口がありますね。そこでおろしまして、そこから戻るんじゃなくて、そこから先のほうの清掃工場のほうを通って出てもらう。一方通行の流れでしたいんですね。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"一方通行の流れはもちろんそのほうがいいと思うし、外に出たところの道路の状況を見てもそういうふうにしないといけないと思うんですけど、なれないと迷い込んじゃうかなという気もしなくもないので、もちろん表示とかそういう案内はしてくださると思うんですけれども、よろしくお願いしたいなと思っています。そういう都合ももちろん採用していただけるということでいいんですか。","respondent":"島袋品川区清掃事務所長","answer":"そのとおりです。","id":"exchange-035"},{"speaker":"土井委員","kind":"質問","question":"今、お伺いしますと、１万数千件あって、臨時の車を出さなきゃ間に合わないぐらいに大変お忙しいようなんだけれども、これをやっても日曜日の１,０００件から見たら、大して大きな影響はないかなという感じがしてまいりますので、人と車とか勤務時間とかいろいろな状況があるにつけても、それはよく相談していただいて、２３区全部でやっているときとあまり変わらないやという話になっても困っちゃうので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"林（和）副委員長","kind":"質問","question":"これは新しく始まるわけですけれども、このＰＲの方法はどういうふうにするわけですか。","respondent":"島袋品川区清掃事務所長","answer":"広報とかホームページなんかを使って、通常のＰＲをやろうと考えています。","id":"exchange-037"}]},{"id":"topic-05","title":"条例が終わりまして、次に請願審査","agenda":"条例が終わりまして、次に請願審査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"免税点というのと基礎控除というのの違いというのはどういうふうに、この表現を見てみると、免税点を基礎控除に改めていただきたいという、単純にそういうことなんですけれども、あまりよくこの辺はわからないので、教えてください。","respondent":"太田税務課長","answer":"基礎控除については、１５０万円を引きますので、課税標準額が２００万円であれば、そこから基礎控除として１５０万円を引きますので、課税標準額としては５０万円になるということで、繰り返すようですが。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"あるいはもうちょっと中小企業、さっきの概念で言うと、もう少しそれよりは個人事業者でもないし、いろいろな方々が入っておられるんだろうと思うんですけれども、なかなか景気が回復しているとはいっても、厳しい実態がまだまだいっぱいあると聞いておりますので、そういう方々にとってこういう要望をされるということは、ご商売上、経営も厳しいものがあるということもあるのかなと思うんですが。","respondent":"太田税務課長","answer":"ランクというよりは、加入されている方々のお話かと思いますけれども、税務団体の場合、大きく分けて３つの団体があります。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"いわゆる中小企業というふうに位置づけていいのかどうかというのをちょっと知りたかったので伺ったんですけれども、わかりました。私は趣旨からいって非常によく理解できるところもありますので、今日結論を出すということになれば、それはそれで進めていただいていいと思うし、私としてはこの厳しい経済状況の中で、できるだけ要望に沿うような形で取り扱っていきたいなとは思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"林（和）副委員長","kind":"質問","question":"先ほどもお話がありましたけれども、都議会のほうで２月２８日にまた審議をされるということですよね。ですから、今、南委員も言われていましたけれども、私たちも前向きではありますけれども、今日のところは様子を見るということでもって、継続にされたらいかがなのかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"土井委員","kind":"質問","question":"継続ということになると、我々の任期が終わっちゃいますよね。廃案になるわけですね。控除にしても。これはもともと１５０万円というのはまけてあげたんですよという意味なのか、それともそこから上の人は取るんですよという意味なのか、両方兼ねている中身を持っているものですから、非常に判断が難しいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"堺委員","kind":"確認","question":"さっきご説明いただいたのを確認ですが、４区が継続で１１区が採択だとおっしゃったんですね。そこをもう１回。","respondent":"太田税務課長","answer":"この２８日に審議予定ですので、都においても第３回定例会、第４回定例会で出たものについて、一方が継続、一方が未審議という状況ですので、おそらく継続となる見込みというニュアンス的なもので聞いております。各区においては、１１区が意見書を国へ提出したです。","id":"exchange-043"},{"speaker":"堺委員","kind":"意見","question":"どうしたらいいのかなと。都議会が２８日にやるので、それを見てからでもいいかなと。だから、どうしようかなということなんですよ。できれば２８日の都議会の結論を見た上で、今言ったような形でいいのかなという気がするんですけれども、あるいは今日、品川区として結論を出すということになれば、採択という意味合いの感じかなという気がしないでもないんですけれども、申しわけないんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"堺委員","kind":"質問","question":"ただ都議会はまだそのまま継続しても審議する予定があるわけです。品川はここで一たん改選ということがあるんですよね。要するに変わっちゃって、この委員会がなくなるわけですから、このまま審議による廃案という、それもどうかなという気がして、それで悩んでおります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"本田委員","kind":"意見","question":"廃案にするのはしのびないし、今日趣旨採択なのか、紹介議員には自民党の皆さんがなっているんだけれども、ここにいないし、もし、副委員長の意見が統一見解ということであれば、流すということでいいのかどうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"本田委員","kind":"質問","question":"趣旨採択を諮ったらどうかと思うんですが、それでいいかどうかですね。紹介議員になっている会派の皆さんはいかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"土井委員","kind":"確認","question":"こういうものを議論をしてもらいたいという問題提起としての趣旨はよくわかるわけですが、数字が細かく入ってくると、これまたその数字が云々の問題になりますから、なかなか難しい部分があるということでしょうし、かなり大きな制度改正の中身を含んでいるので、ここはあっさりとそのままというのは、やっぱり我々も無責任でおられないという問題があるものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"本田委員","kind":"質問","question":"明日も委員会があるわけですね。明日まで継続させていただいて、これについて特に自民党の皆さんの統一見解を言っていただいて決めたらどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/593414?Template=document&Id=2482#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":49603,"voices":134}},{"id":"h19-20070226-7","meetingId":"h19-cm02","date":"2007年2月26日","dateIso":"2007-02-26","committee":"厚生委員会","time":"午前１０時０３分～午後１時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この衛生試験所で現在はどんな体制になっているのかということと、あと、発注側が民間に委託してきたということなんですけれども、実際、今されている業務の中身について教えていただきたいと思います。それと、先ほど、保健所としてやらなければならない検査については残していくということですが、これはどういうことなのかということについて教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"検査技師ですけれども、主査の２人はそのままでございまして、学校給食の調理職員の年間検体が１万１,０００件ほど、月に２回、細菌とＯ－１５７と２つの検査を全職員分、栄養職員も含めてですけれどもやっておりまして。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ありがとうございました。それで、そのために、職員の体制が、先ほど、主査が２名で、検査の方が４名で、合わせて６名ということなのか、主査も入れて４名ということになるのか、そのことだけ確認をさせてください。","respondent":"谷田部健康課長","answer":"現在、検査技師５名配置してございまして、主査が２人、一般職員が３人、４月１日以降、主査を２人、検査技師が２人、検査関係は４名体制で進めていきたいというふうに思ってあります。","id":"exchange-002"},{"speaker":"三村委員","kind":"質問","question":"今のご説明の中で感染症という話がありましたけれども、今、鳥インフルエンザやなんか日本国内でもいろいろ発症例があると思うんですけれども、品川区内でもそういった発生した場合というのは、検査もこちらの担当になってくるんですか。","respondent":"倉橋品川区保健所保健サービス課長","answer":"新型インフルエンザにつきましては、指定感染症ですので、基本的には都の衛生試験所、すなわち健康安全研究センターのほうで検査することになっております。","id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この中でちょっとはっきりしなかったのが、行政検査等の機能に変更がないというのは、同じ場所で今後も継続していくということの意味なんですか。","respondent":"谷田部健康課長","answer":"その建物は、細菌を遮断するための設備等になっていますので、これをちょっとほかに移すというのはなかなか難しいものですから、現在の建物はそのまま活用いたしまして、近隣の保健センターのほうの管理下に置くということで迅速な体制をとっていきたいです。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。今までどおりきちっとした体制をとっていただきたいというのと、ちょっと気になったのは、これ、あの建物は最初から衛生試験所という建物ではなかったでしたか。これ、もとがなくなってしまうとあの建物はどうなるのか、部署が違うのかなと思いながらちょっと気になったので。","respondent":"谷田部健康課長","answer":"看板も品川第一地域センタービルというふうに看板を立てさせていただいて、その中に衛生試験所というものがありますというアナウンスと、それから、チラシ等なんかでも、品川第一地域センタービルというふうにしたほうが、初めての方にもわかりやすいので。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"わかりやすいのは、確かに品川第一地域センターと言ったほうがわかりやすいけれども、たしか今年の予算の中で、あの建物の改修費の中に衛生試験所という名前で出ていなかったかなと思ったので、それを今ちょっと思い出しました。","respondent":"谷田部健康課長","answer":"現在、衛生試験所があの建物のビル全体の維持管理を担当していますので、それは衛生費の中でそれぞれ組んです。ですから、今年、外壁改修があったり、それからさまざまな工事を定期的に入れていますので、現在も衛生費の中で、これからも衛生費でやっていく予定です。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"教えていただきたいのですが、今後、民間委託ということでいろいろ経緯があるんですが、今後、行政検査というのはどういう方向性になるのかなということで、要は、ほとんど民間でやるような形の流れになっていって、行政機関の中では民間に渡していくという全体的な方向性があるのかどうかをお聞きしたい。","respondent":"青山品川区保健所長","answer":"したがって、確かに一部食中毒で行政処分をやるときには、健康安全研究センターに持ち込んで、そこの試験結果によってでなければ処分はできないとなっておりますが、これは都と区の協定で、しかしながら、それをいち早く検査をしていくとか、自粛を促していくとか。","id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今回ここがまた保健所に戻っていくということなので、この辺の衛生試験所が設立されたときの位置づけというか、目的というか、どういうところに重きが置かれてここに設置されたのかというのが１点で、その辺が保健所の中にまた戻ってくるというあたりで、支障がないのかどうかというのが１つと、あと、新旧対照表の１ページのところの第３条のところに。","respondent":"谷田部健康課長、青山品川区保健所長","answer":"ただ、そうは言っても、なかなか衛生教育というのは難しい関係がありますので、試験だけではなくて、今後も子どもたちには衛生教育というのは引き続きやっていく必要がありますので、これは保健所。今回、組織が地域保健法の改正に伴い、保健所、保健センターとなりました段階で、処務規程上、保健所が全体を統括する形になっておりますので、そういう点では保健所の管轄のもとに試験所は入るということで、広義に言えば。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"ただ、今、教育のほうでは、特別支援教育というのが始まって、ここは所管がちょっと違うかもしれないんですが、もうちょっとその特別支援学校という意味合いが広がる形になってくると、対象者が広がるのではないかというような期待を持ってしまうんですが、そういうことではないということなのでしょうか、その考え方というか、適用範囲というのを教えてください。","respondent":"諸岡児童課長","answer":"対象範囲等の変更はございませんで、今までの対象範囲と全く同じです。ただ、この盲・ろう学校、養護学校、この名称が学校教育法の改正に伴って変更になったということのみで本条例の改正を行うです。内容については変更ございません。","id":"exchange-009"},{"speaker":"三村委員","kind":"質問","question":"家庭あんしんセンターのほうで今まで実施されていた障害者生活支援センターのほうなんですけれども、相談機能ということでやられていたということなんですけれども、今までの場所よりは利便性の高いところに移るので、それ自体はいいのではないかという話を聞いたんですけれども、その相談、特に心身に障害のある方に相談に来てもらうような体制になっているというふうに認識しているんですけれども。","respondent":"西島障害者福祉課長","answer":"生活支援センターもこのたびこういう形で移りますと、当然、相談機能は強化されるので、出張相談ということも、どうしても時間的な制約とかいろいろあるのは当然出てまいりますが、それについては当然強化をしていくということにしたいというふうに考えております。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今の関連なんですけれども、障害者生活支援センターがあんしんセンターから身障者会館に移りますけれども、今までのあんしんセンターでされていた生活支援センターの体制と業務の内容が、身障者会館に移って、今度はケアマネジメントの体制になっていくということなんですけれども、それがどういうふうに体制と中身が変わっていくのかについてお聞かせください。","respondent":"西島障害者福祉課長","answer":"現在の生活支援センターの体制ですが、常勤１人、非常勤１人という体制です。それで、今度新しいところに移りますと、今考えているのは、平成１９年度につきましては、常勤２人、非常勤２人もしくは３人というような体制を今検討しています。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ケアマネジメント体制というちょっとイメージがいま１つはっきりしないので教えていただきたいのですけれども、介護保険のほうでは、ケアマネジャーがついて、それぞれの計画を立てるという体制になっていまして、もともとこの障害者の方のときに、こういうケアマネジメント体制がないので、介護と同じようなケアマネジメント体制をつくってほしいというのはずっと要求としても上がっていましたし。","respondent":"西島障害者福祉課長","answer":"役所のケースワーカーとの関係ですけれども、ケアマネジメントを始めると言いましても、今度新しく始めるので、役所側もそうですし、それから生活支援センター側の職員もそうですが、当然ここの部分の連携というのは大変重要になってまいります。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、今までは多分、サービスを受けるときに、区のケースワーカーの方に自分の相談をする方はこのケースワーカーというふうな形で相談をしながらサービスを組んできているというのが今の事業だと思うんですけれども、それがこの身障者会館のほうに徐々に移っていって、身障者会館のほうのケアマネジメントをするその体制の中で、計画とかなんかも、相談なんかも全部そちらのほうに移っていって。","respondent":"西島障害者福祉課長","answer":"すぐはならないと思いますが、将来的な形としては、高齢のほうと同じように、区側のほうはいわゆる包括支援センター的なイメージで、あちらは具体的な支援センター現場、こういう形でなっていくのだろうというふうに考えているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう形というのは、本当に障害者の方からも求められていたものですので、今お聞きしてイメージが何となくついてきたというところなんですけれども、ぜひ充実をさせていくということでよろしくお願いしたいと思います。そこら辺のところをちょっと確認をさせてください。","respondent":"西島障害者福祉課長","answer":"国の動向いかんにかかわらず、国の本体の法律が変わってしまえば変えざるを得ませんけれども、附則とか政省令が動いても、そう簡単に変えなくて済むようにというふうなことを考えて、今回、実施したということと、委員が指摘した部分については。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの条例改正の内容のところで、２番目のところに「更なる軽減策の実施に伴い」ということで書かれているんですけれど、今回、国のほうのこの利用料の軽減措置が新たにとられることになりましたよね。そういうところで、この「更なる軽減策の実施に伴い」という中身について、国と品川区の軽減策の概要について教えていただきたいと思うんですけど。","respondent":"西島障害者福祉課長","answer":"先ほど国は低所得３までというふうにお話をいたしました。この部分につきましては、品川区はさらにそれを拡大して、所得制限なしで、通所に関しては全員対象として４分の１軽減の実施をするということを来年度実施を予定しています。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、低所得１、２の方はその利用料と、それから食費の実費負担というのは５,０６０円ということで、国のこの試算で言えば、８,８１０円のところが品川区では５,８１０円ということでいいのかということを１つ確認をさせていただきたいのと、それからあとは、一般の区民税が１０万円未満と、１０万円以上ということで国のほうの今度の軽減策は分かれていますけれども、品川区はこれを分けないで。","respondent":"西島障害者福祉課長","answer":"一般のいわゆる１０万円未満につきましては、１万４,３６０円が国の示した例ですが、これから３,０００円引きますので、品川区は１万１,３６０円、それから、いわゆるそれ以外、所得割１０万円以上の方、国の基準でいいますと２万９,２００円が。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"確認","question":"２点だけちょっと確認させてください。その辺だけ１点確認したいのと、もう１点が、今ずっとお話があった使用料の件ですけど、使用料は今現状よりも逆に減っていくんだということは十分わかっているんですが、例えば、この条例が変わったことによって、書類上、利用者の方の間に何か書類関係かなんかが発生するのかどうか。","respondent":"諸岡児童課長、西島障害者福祉課長","answer":"今般、そのスペースとして、あまり広いスペースではないわけですが、相談室とか相談コーナーとかというところで、子育て支援機能、特に相談機能の充実を図っていきたいと考えております。２点目の契約に関するお尋ねですが、障害福祉サービスを受けるときは申請を区のほうに出していただきます。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"家庭支援センターのほうは、今言ったように充実を図っていただきたいのと、もう１点使用料の件は、要するに現状ではまず変わらないんだよということは、何か書類を出せというと、上がるんじゃないかという心配を持たれるといけないと思ったので、その辺が誤解のないような形でやっていただきたいなと思ったので、もう一回。","respondent":"西島障害者福祉課長","answer":"ケースワーカー等につきましては個別に、当然窓口あるいは訪問先で問い合わせした際にはわかるようなものをつくってご説明していきたいと考えています。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そしてテロ対策を契機に両法律を統合するという方針を撤回して、結核対策のさらなる充実強化を求めるものである」という声明が出されていましたけれども、これはこういう状況の中からどういうふうに改善がされて、今回の統合になったかというあたりをちょっとひとつ教えていただきたいと思います。","respondent":"青山品川区保健所長","answer":"ただ、全国保健所長会等で要請された事柄につきましては今回の法律の中に盛り込まれて、そして統合された感染症法が制定されましたので、ほぼ私どもが要求してきた事柄についてはこの法の中に盛り込まれたということを前提に考えております。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その盛り込まれた中身の大まかな概要を教えていただけないでしょうか。","respondent":"青山品川区保健所長","answer":"しかし、人権という観点から考えるとそれはまずいということで、一たん厚生労働省はそれを極めて厳密に運用しろと言ってまいりまして、それは現実にそぐわない。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここで、意見聴取の方法を簡素化ということで、「以下の要件を満たしたときは、意見聴取の方法を簡素化する」ということで書かれていますけど、その中身が今の弁護士とドクターで電話でやり取りして確認できればという中身でいいのか、この意見聴取の方法の簡素化の具体的なところをお聞きしたいと思っていたので、そこのところを１つ確認をさせていただきたいのと、それから。","respondent":"倉橋品川区保健所保健サービス課長","answer":"もう１点の開催の期日といいますか、間隔ですけれども、これも同様に、今のところ月に２回の定例開催、それに加えまして、条件に合わない場合は緊急に開催する可能性もありますので、プラスアルファで緊急開催という可能性もあるということで準備しております。","id":"exchange-021"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"例えば、「数的には件数は減っているけれども、死亡率で見ると日本は米国の５倍も多く、約３０年のおくれがある」といったことも事実であるというような何かショッキングなことも書かれているのですけれども、この辺の実態が品川区の場合ではどういう状況になっているのかひとつ聞かせていただきたいのと、その実態の中で、より対応できる状況になっているのかどうかというところをお聞かせいただきたい。","respondent":"倉橋品川区保健所保健サービス課長","answer":"３年程度で動向を見るのはなかなか難しいところですが、長い動向を見ますと、減少傾向といいますか、だんだんと少なくはなってきているところです。","id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問","question":"その下の第６条のときに、「ただし、緊急その他やむを得ない場合であって区長が別に定めるときは、この限りではない」と書いてあるので、その辺が具体的にどうなのかなと。例えば、結核のところにおいては弁護士が、法律的な人が入るというところが重要だと思うので、必ずそこが確保されるのかどうかその辺をお聞きします。","respondent":"倉橋品川区保健所保健サービス課長","answer":"それに対して、第６条ですが、緊急その他やむを得ない場合については１枚目の２番の(2)1)、2)、3)、4)で示しました簡素化の要件を厳密に守ることによりまして、先ほど申しました菌検査が陽性で、かつ排菌状態であって感染する可能性が非常に危惧される状態である。","id":"exchange-023"},{"speaker":"三上委員","kind":"意見","question":"そういった点に対する医師会の皆さんの、当然疑ってみるという、要するに年齢ではなくて、ある程度そういった年齢の方については「どうなんだろうか。じゃあ、ちょっとレントゲンでも撮ってみましょうか」とかということがあってもいいんじゃないかと思うんですけど、そういった要請というものを医師会とどのように連携をとられているのかということについてお願いしたいんですけど。","respondent":"青山品川区保健所長","answer":"後者を先にご説明しますが、やはり、結核において一番の問題は、本人が医師のところに行かないという以上に、医師が見落とすというところが極めて高いです。というのは、今の若いドクターにとって、まず熱が出て、せき・たんが出てというような場合に何を考えるかというと、肺炎。","id":"exchange-024"},{"speaker":"三上委員","kind":"質問","question":"伺ってよくわかりました。品川はよくやっているということはわかりましたので、多少安心はいたしましたが、結局ゼロにはならないということですので、やはりそういった意味での意識啓発は強化されるようにお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"三村委員","kind":"質問","question":"２の（３）で受給者証の交付を受けている者というふうに変わっているんですけれども、旧条例のほうの第４条の（１）の規定が外れたのかなという気もするんですけれども、この規定に該当していて、そういう受給者証を持っていなかったという人は実際に存在するんですか。皆さん、受給者証を所持していらっしゃって特に問題ないのか、その点について。","respondent":"西島障害者福祉課長","answer":"第４条の関係ですけれども、従前は西大井つばさの家は、法内のいわゆる障害者自立支援法の給付を受けている。したがいまして受給者証というのはお持ちです。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"条例改正の内容のところに法内化に伴いということなんですけれども、今まで法内ではなかったものが法内になったということで、どこがどう変わって法内になったのかということについてもご説明をお願いできたらと思います。","respondent":"西島障害者福祉課長","answer":"ただ、通常、グループホーム１戸の建物としては４人から１０人というふうに制限が拡大をされたことに伴いまして、この北品川つばさの家につきましても、いわゆる区の単独の事業から自立支援法の枠組みのほうに移行した、こういうことです。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、区としての北品川つばさの家そのものは全く変わっていないのが、自立支援法になったために法内化にできるようになったということなんですか。自立支援法はもっと前に実施されているにもかかわらず、それであればなぜ今になったのかということもあわせて教えてください。","respondent":"西島障害者福祉課長","answer":"この６人ですが、運営のことを考えると、今の基準で言うと、６人が一番有利かなと。世話人体制とか、そういうことを考えると、６人が一番有利なのかなということで、２人部屋を改修いたしまして、みんな個室ということで６人の２ユニットということにしたものです。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ありがとうございました。それともう１つ、この（４）の利用者負担額についての規定は、今まで出てきたものと同じということの規定になると思うんですけれども、このグループホームでのさらなる軽減策というのが、実際どういう状況になるのかということについてお聞かせいただきたいと思います。","respondent":"西島障害者福祉課長","answer":"これにつきましても、午前中の議論で説明したとおりの適用を受けますので、居宅の部分については４分の１軽減、こういうことになります。ですから、この部分については、午前中と同様だというふうにご理解をいただければというふうに思っております。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"知的障害者の援護施設のほうは、これは今まで出てきた条例と同じ文言整理ということでいいんですけれども、もう１つ、児童学園のほうなんですけれども、これは去年の９月のときにこの条例が出されたときの課長の説明で、半年間利用料を据え置くという形にてしていたのが、今回、改めて自立支援法の規定の中で行っていくということになると思うんですけれども。","respondent":"西島障害者福祉課長","answer":"あわせてその際に、たしか三村委員の質問だったと思いますが、４月以降はどうなるんですかというご質問をいただいたと思いますが、そのときに国のほうも新しい軽減策を検討しているようなので。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回新たにこういう形で国も、それから区もさらに上乗せをした形での軽減策をとられた場合、今までの負担と今回の軽減策がとられたときの負担で、どう変わっていくのかというのをちょっとお聞きしたいんですけれども、かなり今までも幅があったということで、負担の幅がかなり、４,５００円ぐらいから３万３,７００円くらいまで幅があるということなんですけれども。","respondent":"西島障害者福祉課長","answer":"あまりこれ、プライバシーにかかわるので詳しくはお話しできないんですが、比較的所得層の高い方が通園しているというようなこともありますので、そういう意味では、そんな結果が出ているだろうと、これも推定ですので、実際、所得というのは年々動きますので。","id":"exchange-031"},{"speaker":"木下委員","kind":"質問","question":"ちょっと二、三お伺いしたいんですが、発達障害児の問題というのは、ＬＤですとか、多動児ですとか、小さいうちからそういう形で教育するというのはものすごく意義あることで、一貫性あるそういう教育というか、育児をしていくというのは、私、大賛成なんですけれども、ちょっとお聞きしたいのは、この発達障害児の療育事業、これ、都道府県ですとか、あと、政令指定都市ではあるらしいんですけれども。","respondent":"西島障害者福祉課長","answer":"今の発達障害者支援法の枠組みでは、都道府県の仕事の範疇でございまして、障害者自立支援法の枠組みにも入っておりませんので、そういう意味では品川区が初めてになるのではなかろうかというように考えているところです。","id":"exchange-032"},{"speaker":"木下委員","kind":"質問","question":"大人になった際にいろいろ問題を起こす子たちが多いということで、私なんかも宇治少年院でのそういう矯正、問題を起こすお子さんの矯正のことなんか、いろいろ調べたりなんかして、小さいうちから対処したほうがいいというふうにつくづく思っておりますので、ぜひ模範となるようにお願いいたしまして、質問をさせていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"三村委員","kind":"意見","question":"今の木下委員と逆の立場になるのかなという感じがするんです。逆にあまり小さいときから、ＬＤだとか、ＡＤＨＤで障害者というレッテルを張って、普通の子どもたちと違うところに押し込めてしまうような流れに持っていかないでほしいなというのが少し。","respondent":"西島障害者福祉課長","answer":"したがいまして、そこを分けるとか何とかということではなくて、例えば保育園に行っている人が１日ここに通ってくるというケースも、将来的には、すぐそれができるかどうかは別にして考えられますし、そういう意味では。","id":"exchange-034"},{"speaker":"西本委員","kind":"確認","question":"それはどのように今回、指定管理者、福栄会ですから信頼はしておりますけれども、その辺の確認等々はどのようになっているのでしょうか。","respondent":"西島障害者福祉課長","answer":"家庭あんしんセンターの中でもさまざまな事業がやられてありますが、その中の今は発達障害児については一部の事業ということになりますので、そこにいらっしゃる方がすぐこっちへ移るということではなくて、その辺は本人の希望とか、その辺も踏まえながら。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"これからかなり発展していくだろうというところで非常に興味があるところだし、発展していただきたいと思うんですが、巡回相談をやっていますね、それとの関連性はどういうふうになっているのかなと思いますが。","respondent":"西島障害者福祉課長","answer":"そういう意味では、最初は学齢前だけれども、そこが広がって、当然、特別支援教育とのつながりというんですか、ご本人の了解を得ながらデータというんですか、プログラム等の引き継ぎ等も行っていく必要があるでしょうし、そういう意味では、今回。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この軽度発達障害児の療育というところに関しては、本当にお父さん、お母さん方から充実させてほしいという希望がたくさん出ているので、この期待にこたえるような中身にぜひしていただきたいというふうに思っているところですけれども、先ほど、三村委員の答弁のところで、保育園に通いながらもここに通ってくるというのは、将来的にはそういうふうな方向ということなんですけれども、ここら辺のところは。","respondent":"西島障害者福祉課長","answer":"ただ、この辺は７月の施行というのは、採用しまして、これから私どもの担当のほうと直接いろいろ細かいことを、それは家庭あんしんセンターの現在の状況との連携をとりながら詰めてまいりますので、その辺の状況を見ながら、体制については徐々に整理をしていきたい。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今お話にあったような１時間で８,０００円ということで、私もこういうお話は聞いていて、すごい本当に専門的な療育を受けると、かなり改善されて、あと、学び方なんかにしても、その子に合わせた学び方というのをしてもらう中ですごく理解ができるようになるというふうな話はお聞きしてきたんですけれども、そういう点で言うと。","respondent":"西島障害者福祉課長","answer":"済みません、今回の議案につきましては、ちょっと私の説明がいけなかったかもしれませんが、今回の議案は、現在ある品川児童学園の指定管理を福栄会にお願いをするという議案でございまして、それになぜ変えるかというところの質問で軽度発達障害の取り組みが出ている。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"もう１つお聞きしたいのは、今回、指定管理者の変更ということで、品福が指定管理者になったときには、多分、期間が５年間ということではなかったかと思うんですけれども。５年間ということではなかったんですか。契約の指定期間が５年間というのがすごく多かったので、ちょっと私も実際確認はしていないんですけれども、そこら辺のところの期間がどうだったのかをちょっと教えていただけないでしょうか。","respondent":"西島障害者福祉課長","answer":"内容は指定管理者の変更ですが、議案上は指定管理者の選定についてという議案になりますので、そこはちょっと言葉のことで申しわけないんですが。それで、５年間というのは品川総合福祉センターに指定管理をお願いしたときも５年間ということでお願いをしています。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今まで出ている中でちょっと何点か確認させていただきたいんです。そうすると、今通っているお子さんたちが新しい方とこれからの事業の中でかかわり合うことになってくる、その辺がまずどういうふうにうまくいくのかなとちょっと気になっているんですけれども、当然うまくやるということでお話も進めていると思うんですけれども、ちょっと確認だけさせていただければ。","respondent":"西島障害者福祉課長","answer":"これを変更するに当たりまして、やはり現在通われている知的障害児の保護者、お子さんに対する動揺があっては一番いけませんので、この辺についても両法人で詰めていただいて、あまり法人の人事にかかわることで断定的なことは言えませんが、現在の人員のままで行くような方向で。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"さっき言った選定がこれからどうかというのは、ちょっと場所が違うと思うので済みません。ただ、あくまでもこれからも運営をうまくやっていただきたいということで、その辺を今後別のケースのときにも十分意識していただきたいなという思いがあります。それから、ちょっとはっきりしないのは、プチレーブでしたか、あれは品川総合福祉センターが今やっているのは、これも一緒にかわるということなんですか。","respondent":"西島障害者福祉課長","answer":"ただ、清掃部門につきましては、品川児童学園の２階で朝の朝礼とか給食等をやっておりましたので、児童学園がこういういわゆる障害児の、もともとは全体が児童学園という施設だったんですが、たまたま空きスペースがあるのでそういうことで進めてまいりましたが。","id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後に要望しておきますけれども、この今の児童学園、地域の中でもいろいろな協力体制をとっていただいているんですよね。ですから、今までの協力体制をこれからも維持できるように、新しい事業者の福栄会さんのほうともうまく調整していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"飯沼副委員長","kind":"質問","question":"本間議員の質問の中で、教育のところだったんですが、就学前教育のところで、幼保一体化の今後の進み方のところで、学校の改築時に伴って一体化を進めるというようなご答弁があったんです。そこのところをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"飯沼副委員長","kind":"意見","question":"幼保一体化のところ、幼稚園にかかわる部分で、幼稚園のこのありようが幼保一体化の中で進んでいくという、微妙かなと思うんですけれども、幼保一体化のところはここが所管なので、いかがかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/443219?Template=document&Id=3168#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":52750,"voices":145}},{"id":"h19-20070226-8","meetingId":"h19-cm02","date":"2007年2月26日","dateIso":"2007-02-26","committee":"建設委員会","time":"午前１０時０４分～午後４時５３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","topics":[{"id":"topic-01","title":"します。 ということで、第２７号議案、品川区道路占用料等徴収条例の一部を改正する条例、第２８号議案","agenda":"します。 ということで、第２７号議案、品川区道路占用料等徴収条例の一部を改正する条例、第２８号議案","exchanges":[{"speaker":"井上委員","kind":"質問","question":"固定資産税の評価額の変更ということで、過去１０年ぐらいでいいと思うんですけれども、傾向というか、今回は２割弱の値上がりということですが、どのように推移しているものなのかということを教えてください。","respondent":"松代管理工事課長","answer":"改定額のほうは、平成元年、平成４年、平成８年という形でやってきてありますけれども、その都度激変緩和を念頭に置きまして、対前回の改正額の２割アップというものを限度としまして、ずっと改正をしてきたところです。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"前回、平成４年と平成８年と改正をして、今回ということなのかどうかということと、ピークが平成元年であれば、価格が下がってきているということですから、そこのところ、今まで２割ぐらいで来ているということで、今は緩和策ではなく、どのような計算式になっているのか、それとも、まだ今後上がるのかという推測を教えてください。","respondent":"松代管理工事課長","answer":"ですから、評価額が下がるのと改正額が上がるのと、こういった感じで、将来的にはぶつかって、それが一致するところがあるんでしょうけども、今回の平成１９年度の改正のときに、その時点で言いますと、まだまだ評価額のほうが高い状況にあります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"２７号議案のほうからお伺いしたいんですけれども、初めに、固定資産税の評価額ですけれども、２３区の中では、それぞれ区で額が違うと思うんですけども、今回のこれは２３区としての値上げの考え方、ちょっとご説明していただきたかったのと、それと、資料説明の中で、自転車の車止めとおっしゃったんですが、それがちょっとどういうものかよくわからなかったので。","respondent":"松代管理工事課長、松嶋交通安全担当課長","answer":"それ以外のところは低くなっております。これに当たりましては、占用料の改定の基本的な考え方としまして、平成１８年の８月の助役会で２３区一体的な改正をするという基本方針を確認しております。車止め装置等についてご説明いたします。これは自転車等の駐車機器ということで、例えば車輪止め、ラックみたいなもの、それから柵、ワイヤー、照明用具、案内板、自動精算機等々を含めて自転車等駐車器具ということになっております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"２３区では一体的なものというお話の中で、国の計算方式に基づいて額が決まるというお話ですけれども、上がるものはおそらく企業的、企業の負担のものが上がっていく、下がるものは、例えば５ページ目のところですね、商品置き場その他これに類するものというのが１万７,７００円から１万７,０００円に下がる、その後、看板、それと商店街の装飾灯というんですかね、アーチ型の。","respondent":"松代管理工事課長、松嶋交通安全担当課長","answer":"今、委員お話のとおり、５ページのほうに右が現行額、左が改正額でございまして、看板、アーチ等々の部分が若干下がっております。自転車等駐車器具の関係につきまして、ラック等につきましては、限られたものという考えではございませんで、その構造につきましては、固定式であったりとか、安全性、耐久性を具備したもの、そういったものです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"自転車のほうはよくわかったんですけど、区道上にとめられるものというのは、要は品川区の設置している駐輪場のことだけを指すんですかね。区民に対する負担というのは、どういうものがあるのか、ちょっと具体的な例示をご説明いただけますか。","respondent":"松代管理工事課長、松嶋交通安全担当課長、岩田まちづくり事業部次長","answer":"公共溝渠の関係ですけれども、これは国のほうから私ども地方自治体のほうに移管されておりまして、それを受けて、今調査を品川区はしておりまして。これはだれが設置するものかというご質問でございましょうか、それともラック自体のことのご質問でございましょうか。駐輪場の件ですが、昨年道路法の施行令が改正になりまして、今までは道路上に自転車駐車場は設置できないということになっておりました。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"一般的に、公共溝渠のほうですけども、先ほどのご説明の中で、区民または企業に対する負担の変化があり、企業に対する話は電柱というお話がありましたけど、区民に対する影響というのは、どういうものが公共溝渠の上にあるのかなという、その変化をもうちょっとご説明いただきたいのと、自転車のほうは、現状は区が設置するものだけなんですかね。それとも、民間が設置しているものもあるんですかね。","respondent":"松代管理工事課長、松嶋交通安全担当課長","answer":"そういったものが区民、個人とのかかわりだというふうに思ってあります。ただ、今度個人が設置するものはいいのかという話ですけれども、一応設置基準の中に設置主体につきましては、「地方公共団体、公共交通事業者、地元商店会、その他、これらに準ずる者であって、当該器具を適切に管理し。","id":"exchange-006"},{"speaker":"阿部委員","kind":"確認","question":"公共の場所、多分先ほどご説明にもあったように、道路の上に駐輪場をつくるというのは、多分イメージとしては駅の近くですとか、そういったところになるのか、条件が整った場所ということになるのかなと思うんですけれども、そうなりますと、逆に設置を促進する意味から、例えば第３条ですか、占用料の減免という項目もありますが、公共の例えば駅前ですとか、スーパーの前だとか。","respondent":"松代管理工事課長","answer":"１番目のどこの部分の表現かということで、７ページの新旧対照表をご覧ください。新のほうの中段にあります令第７条第８号に掲げる器具と、ここのところです。","id":"exchange-007"},{"speaker":"阿部委員","kind":"質問","question":"つまり、公道上に民間企業が駐輪場を経営するということになるのであれば、むしろ何か相当取っちゃってもいいんじゃないかというぐらいの感覚があるんですけれども、その辺を考えると、やはり、占用料は幾らぐらいなのかなというのがさらに関心がわいてくるんですが、いかがでしょうか。","respondent":"松代管理工事課長","answer":"申しわけございません。今例示で大井町駅周辺のＡの価格ですけれども、今こちらにちょっと細かいところの部分での数値がございませんので、後ほど調べてお答えします。","id":"exchange-008"},{"speaker":"井上委員","kind":"意見","question":"今のと関連するところで、区の場合、今までのいろいろな委員会での審議でも駐輪場を道路に計画ができるんではないかというような検討も視野に入れてというようなニュアンスがあったんですが、区がそういった道路上に駐輪場を設置するという場合には、占用料は当然無料になるのかどうなのかということと、あと、公共溝渠なんですが、大井七丁目とか六丁目とか、あの辺の道路、地域であるんですけれども。","respondent":"松代管理工事課長","answer":"どういった基準かといいますと、今言いましたように、水路としての機能、またあとは、そこの周辺にお住まいの方々への通路的な機能がない場合、それぞれケースが違ってまいりますので、１軒１軒私どもが調査をしまして、なおかつ周辺の方々等の意見等も聞きながら。","id":"exchange-009"},{"speaker":"井上委員","kind":"意見","question":"そういう中で区が設定するとしたら、それは無料かどうかということを決めていらっしゃるのかどうかということと、あと一つ、払い下げにおいては、有料というか、払い下げするのに有料とされているのかどうかということについて。","respondent":"岩田まちづくり事業部次長、松代管理工事課長","answer":"現在、まだ無料の駐輪場というのが存在しているわけですけれども、これはその当該駅に区がきちっとした駐輪場が設置されていない、いわゆる暫定期間の間、緊急避難的に道路等に無料でとめていただいている、こういうことですので。公共溝渠の払い下げに関することですが、実際払い下げするときには有料で払い下げをしております。払い下げ金額等については、払い下げ基準というものを設けておりまして、その基準に照らして払い下げをしています。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問","question":"占用料、１平米当たり３万４００円と、民間の業者側、駐輪場経営する、自前で土地を確保するよりは、かなり安い価格になるんじゃないかなと思うんですけれども、その辺、業者が公道を使って、言葉は悪いんですけど、あまりぼろもうけにならないようにするのが区民感情に適しているかなと思うので、その辺はぜひうまくやって、どんな方法があるのか、ちょっとわからないので。","respondent":"松嶋交通安全担当課長","answer":"今回の占用を認めた背景、目的といいますのが、民間に対して利益を追求させるというものではなくて、道路上に放置されている、そういった、公道上ですね、放置自転車、全国的な問題であって、それに対応するための占用の改正です。","id":"exchange-011"},{"speaker":"阿部委員","kind":"意見","question":"それは民間に任せて、つくられるようになったときに、きちんとチェックするということでお願いをしたいと思います。多分こういった場でも審議することができるのかなと思いますので、その際もお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"細かいことなんですけれども、道路占用料のところは、先ほど２３区一体でというふうに、助役会でそういうふうに言っていましたけども、そうすると、２３区一体でやると、品川区というのは上がるんでしょうか、下がるんでしょうか。","respondent":"松代管理工事課長","answer":"今回の固定資産税評価額、１級地、２級地ということでやっておりますけれども、１級地のほうはかなり上がっております。２級地のほうは、私ども品川区も含めてですけれども、若干下がっております。品川区あたりでは、比較しますと、９６％ぐらいだろうと考えています。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。自転車駐輪場の話になっていますけど、例えば、自動車、四輪、普通車だとか、そういうものというのは、この関係で言うと、そういうのも含まれているんでしょうか。","respondent":"松嶋交通安全担当課長、岩田まちづくり事業部次長","answer":"それで、占用の関係で言いますと、例えば自動車を止めるための駐車器具とか、そういったものは普通ございませんで、大体白線の中に止めるという状況にありますので、自動車の分は入っていないです。いわゆる路内駐車場といわれるもので、道路上に駐車できるのが、例えば大井町で言えばどんたく通りというんですか、あそこに白くペイントしていますけれども、あれは東京都公安委員会が設置をしているものでございまして。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"その話だと、そこで１時間当たり１００円とか１５０円とか料金を取って駐車させているんですけど、あの料金というのは、公安委員会のほうの収入なんですか。じゃあ、それは区道だとか、あるいは都道、国道、いろいろあるんですけど、そこのところで、例えば区道でやる場合は、区のほうは全く関係ないということなんですか。","respondent":"松代管理工事課長","answer":"今次長からありましたように、区道の占用に当たりますので、警視庁のほうから申請が出まして、私どものほうで許可をする。そこに路内駐車場として設置をし、維持管理をする。占用料等については、公共ということで減免をして無料と、そのような形です。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"確認","question":"質問は、駐車場代というのはどっちに入るのかということと、例えば公安委員会の申請で区のほうがオーケーを出すということになると、区のほうにはどういうふうに入っているのかなと、そこのところをもう一遍確認しておきたいのと、あとはアーチのところでは、今回たまたま値下げになったんですけども、私この資料を見たときに、商店街の商店振興で値下げをしたのかなというふうに思ったんですけど。","respondent":"松代管理工事課長","answer":"これは一定の占用料をきちんと決めた上で、商店街、零細、もしくはそういった個店等の商業振興ということから、減免率をそれぞれに設けておりまして、看板等についても減免等を設けてあります。そういった中で対応している、このような状況です。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"意見","question":"先ほどの駐車場のほうというのは、やっぱり何か腑に落ちないなというふうに思いますけど、公安委員会のほうでやって、そちらで駐車場代が入っていくわけですよね。通常、今の駐輪場の話からいけば、当然そこでの使用料というか、公安委員会と品川区との間で当然あっていいんじゃないかというふうに思うんですけども。","respondent":"岩田まちづくり事業部次長","answer":"したがって、それが各区の個数に応じて公平に分担されているかというのがいわゆる問題になっているところでございまして、これは特別区の土木主幹部長会と警視庁との間で懸案事項になっているところです。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっといろいろ懸案事項ということで、これから調整等もやられるのかなというふうに思いますので、ぜひこういう意見もあるということで、伝えていただきたいと思います。もう一つ、公共溝渠のところなんですけども、先ほどの払い下げのところで、基準についてやっているんですけど、考え方だけちょっとわかりやすく教えていただければと思うんですが。","respondent":"松代管理工事課長","answer":"払い下げをするかしないかといいますのは、繰り返しになりますが、水路の跡をどのように今使われているのか、その使われ方の機能というのが水路から通路等に変わって、周辺にお住まいの方々が通路としてまだまだ使って、今後も必要だというようなものであれば。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"意見","question":"わかりました。仮にそこの本来、例えばそこのおたくに払い下げが適当だという場合には、例えばそこのおたくが、とってもそんなお金はないよというふうになると、いつまでもそこの公共溝渠ということで、土地、例えば両側は払い下げているんだけども、その真ん中だけ残るという、そういうのもときどきあるんですけど、そういうときはどういうふうになっていくのかなと思うんですけど。","respondent":"松代管理工事課長","answer":"ですから、そういったところは、それぞれケース・バイ・ケースだと思うんですけど、私どもも、今使われる方のあり方も含めて、当該の方とお話をする中で、申請等を受け付けていければと、このように考えているところです。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"固定資産税の２割ずつ上がってきたから安いのが出るわけがないと考えると、１級、２級ということで安くなると言っていましたけど、こういう話、１級地、２級地というのは前からあったんじゃないかと思うんですけど、何でこれが安くなるのか、わかりやすいように教えてください。","respondent":"岩田まちづくり事業部次長","answer":"１級地、２級地というのは、先ほど課長が言いましたように、いわゆる都心６区ですね。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"幾つかなんですけども、道路占用料と公園条例ですけども、やっぱりこの中で、電柱なんかがありますよね。そうすると、私は今までは区道だから安いのかな、公園は区民共通のものだから、そこに電柱を置くので高いのかなというふうに理解していたんですけど、これは今言った１級地、２級地のという形の中で公園の中と道路で差があるということですか。","respondent":"松代管理工事課長","answer":"今委員おっしゃったとおりでございまして、そのような形で下がっております。それと、若干道路の場合と公園の場合では、電柱の取り扱いがちょっと違いますのは、前回の平成１６年の改定時には、既に今回と同じように道路も公園も同一の考え方で占用料を出しております。","id":"exchange-021"},{"speaker":"松澤委員","kind":"意見","question":"まとめで。上空に持っている通路というふうにありますけれど、それは区道を挟んでの建物の通路かなと思うんですけど、そうすると、２種類あると思うんですね。例えば、昭和大学ではやっぱり病院の通路がまたがっていますよね。あるいはきゅりあんを見ると、あれは商業ビルですよね。やはり買物客が行くようになっている。","respondent":"松代管理工事課長","answer":"１条、２条、３条というような感じであるんですが、その占用される部分の種類の違いを第一種、第二種、第三種というような形で区分けをしています。","id":"exchange-022"},{"speaker":"藤田委員","kind":"質問・要望","question":"これについて、地上の変圧器になるのか、地下の変圧器になるのかわかりませんけれども、これによって随分ちょっと負担額がかなり違うと思うんですが、区として事業を進めているわけですけれども、これに対して、商店街としてどういう負担が生じてくるのかというのを教えていただきたい。","respondent":"松代管理工事課長","answer":"地下の部分でそれをコンパクトにまとめるような方針をとっていただくような感じで今進めているところです。そういった意味では、共通する街路事業型の大きな道路で見ているような変圧器は表に出てこないというような形をとっております。","id":"exchange-023"}]},{"id":"topic-02","title":"第１５号議案、品川区手数料条例の一部を改正する条例","agenda":"第１５号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"２番目の保健衛生のほうで聞いていきたいんですけれども、改正理由は８年以上改正がないということで、都と歩調を合わせてという理由なんですけれども、８分の１ページにあります移動飲食店なんですけれども、このように４,７００円から５,６００円ということなんですけれども、手数料の条例としては、どのように条例があって、ただ、品川区内に警察署は四つありますけども。","respondent":"谷田部健康課長","answer":"過去３年の経過です。自動車ですとか、自転車とかがありますけど、自動車では移動飲食店の営業所の数ですが、平成１６年３月末で３６件、平成１７年３月末で４０件、平成１８年３月末ですから、１７年度末が３９件、大体この辺の数字で推移しております。","id":"exchange-024"},{"speaker":"本多委員","kind":"質問","question":"傾向としては、やっぱり減っている傾向なんですか。ちょっと細かく、大体の傾向だけ教えてください。","respondent":"高橋品川区保健センター衛生課長","answer":"いわゆる屋台ということで、ラーメン屋とかうどん屋が屋台を引いているところの移動ということで、これは平成１６年から１８年にかけては、１６年末で２８件、１８年末で１７件ということで、だんだん少なくなってきている傾向があります。","id":"exchange-025"},{"speaker":"本多委員","kind":"質問・要望","question":"自動車での営業もかなりよく最近見かけるんですけども、自動車ですから、品川だけじゃないと思うので、その辺の状況というか、適正にお願いしたい。ここではお願いしたいということ。何かこれを見ていると、責任だけは建築主事にあるような感じなんですけども、途中の作業の区としての責任と民間確認業者との役割分担が、その辺のところを教えていただきたい。","respondent":"片田建築課長","answer":"ただ、行政責任というものが区にあるわけですけれども、委員がおっしゃられたのは、一昨年の最高裁の判例の中で、民間機関の確認をおろしたものについて、最終の責任といいますか。","id":"exchange-026"},{"speaker":"本多委員","kind":"確認","question":"それで、大臣認定プログラムを使った場合とそれ以外の場合で手数料が異なるということなんですけども、この確認申請料ですとか、その手数料の管理についてはどうなっていくのか。","respondent":"片田建築課長","answer":"したがいまして、その認定プログラムを使用すれば、評価番号とかというものを含めて一連の構造計算の流れに乗りますから、入力するときのインプットと出された出力、これを見れば確認できるというものでございましたけれども、そういうものをあわせて今再検討していますので。","id":"exchange-027"},{"speaker":"松澤委員","kind":"質問","question":"本当に基本的なことなんですけど、構造計算の大臣認定プログラムによるものとよらないものとここにありますけど、そもそも構造計算を大臣認定プログラムでやるという、そこのところがどうなっているのか。大臣認定プログラムというのは、どういうものがあるのか教えてください。","respondent":"片田建築課長","answer":"認定であれば、当然一連の流れで計算されるべきものですから、そういう後での操作ができないようにという大臣認定のプログラムを今、検証していることです。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、構造計算している我々が例えばテストを受けた場合、１００点満点でも９５点まではいいですよと５点の許容範囲があったんですけど、これは構造計算においては、１人で計算していくから、１００点じゃなくちゃいけない。１点でも外しちゃいけないよというふうになっているのか、許容範囲は、その辺はどうですか。","respondent":"片田建築課長","answer":"もう一つ、これもやはり構造計算なり、コンピュータが、１００点の、１００点というよりも１を基準にした場合、１に近づける、計算が一番難しいというような考え方ですけれども、実は余力が一番大事でございまして、１００以上あるいは１以上の評価を持っていただきたいと。","id":"exchange-029"},{"speaker":"松澤委員","kind":"確認","question":"私、今１００点と言いましたけど、最低ラインで、行うということですね。建築主事がノーと言ったものでも再検査をして、そこで判定をする中で、またイエスと言った場合にまたそこで総合的に判断して、イエスかノーかを決めて、イエスの場合はオーケーにして、ノーのものは不適合通知をしますよというふうになっているという理解でよろしいんでしょうか。","respondent":"片田建築課長","answer":"それをさらにこの目で見て問題がないものを、そういう機関のほうに回して、機関のほうで別な目で見て、あるいは再計算して検討すると、そういう一つのダブルチェックあるいはトリプルチェックになるかもしれませんけれども。","id":"exchange-030"},{"speaker":"松澤委員","kind":"確認","question":"この確認というものが建築設計屋は与えられた仕事で悪いことをしないんだという前提が前にあったと思うのね。そのすべてが品川区の建築主事の、何かあった場合には責任になるということ。その責任のとり方というのはどうなの。","respondent":"片田建築課長","answer":"ところが、やはり、建築主事の制度の中に、国のほうの考え方として、どうしても入れ込むといったような考え方で、あえて難しいシステムを、これまでのシステムの中に入れ込んできたと。","id":"exchange-031"},{"speaker":"松澤委員","kind":"意見","question":"本当にこれは相当問題があると思うんですね。これが２３区一斉に出されている。実際、ほかの区でどのような形で審査されているのかね。ちょっと延ばそうなんていう場合じゃないと思うんですね。それは手数料の問題だから、おそらく品川でちょっと待って、次の定例会にしようなんていったら、おそらく品川区が手数料を払うことになる。それはどうなの。","respondent":"片田建築課長","answer":"現在の法律の中でも、都道府県知事が民間機関を指定しなさいということで、各都道府県がそういう第三者機関をチェックするような形になるかなと。２３区についても、すべてその機関と契約を結ぶといったようなことになります。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の話の流れで、建築確認の事務のことですけれども、そもそもこれはやっぱり原因に対して対策を講じるべきだと思っていて、やっぱり確認申請そのものを民間に解放してしまった、そこに一番の原因があるのではないかなと思っているんですね。結局、それはそのままにして、じゃあダブルチェックだという話になっているから、私に言わせると二度手間であって、さらにその最終的な責任を裁判の中で行政が持つ。","respondent":"片田建築課長","answer":"やはり個人の財産ということも含めた中での考え方だと考えていますから、やはり、今後国のほう、あるいは横浜の裁判がどう動くかということも含めて、自治体としての責任の問題も当然考えなきゃいけませんから、やはり、これは当然必要な対応をしていきたいということで、２３区。","id":"exchange-033"},{"speaker":"中塚委員","kind":"意見","question":"新たにピアチェックというところで、手数料などを追加するわけですけれども、そもそもピアチェック機関というのも、品川区自身が手をかすのではなく、ここで見るとピアチェック、契約というふうに書いてありますよね。このピアチェックというのは、どういう組織なのか。この流れが本当にあってはならない耐震不正の事件の対策として機能しているのかという、それが疑問なので、そこをご説明いただけますか。","respondent":"片田建築課長","answer":"それも１人ではなくて、複数の目で見て検証を行うですので、なかなかそういう方を確保することは各自治体とも難しいという状況ではありますが、そういう中でいろいろ検討することによって、そういうミスをできるだけなくしていこうといったことでは。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"この１５号議案は、ほかに保健衛生の関係もあるので、そちらのほうの質問に移りたいと思うんですけれども、保健衛生のことは、主に３点今回変えることになりますけども、まずそれぞれ手数料の収入の影響額というんですかね、現行からまた変わったとき、幾らが幾らになるのか、１、２、３点、それぞれご説明していただきたいのと、あと前後するんですけども、それぞれ事務がちょっとどういう事務なのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"それぞれわかりました。次の手数料の影響額なんですけれども、三つの主に業務に分かれるみたいですけど、今回の改正による影響総額というのは、もし試算があればご説明いただけますでしょうか。同時に、前回の改正から８年間経過しているというご説明でしたけれども、８年間の経過があった理由、どういった経過があったのか、そこもあわせてご説明いただけますか。","respondent":"谷田部健康課長","answer":"平成１８年４月１日、昨年の４月１日から食品衛生法と食鳥関係の手数料を引き上げしてございまして、私どもも引き上げの検討はその当時しましたが、まだまだ景気回復の足どりがはっきりしていないという段階から、もうしばらく様子を見ようということと。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"三つあわせて３２０万円ということなんでしょうか。その中で、政策的にどういう判断がされたのか、２３区でほかの区が上げたという話がありましたけれども、景気の回復、まだ苦しいなというのが僕の思いなんですけど、政策的な判断の変更といいますか、結論といいますか、それをもう少し教えていただけますか。","respondent":"谷田部健康課長","answer":"そういうところと、あと手数料ですけれども、一定の負担を求めるのは、私どもも十分承知しておるわけでございまして、東京都が、かつて２３区を含めて一体的に行っていた時代から、食品衛生については、都区一体となって行っていこうという判断がございまして、私どもも、昨年。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"新年会に行ったときに、ある商店街の会長が、「今年も４つお店がなくなったんだよ。それも１カ所だけではないです。みんな、商店街は言っています。そういう実態を見きわめれば、商店主に言わせれば、今なぜ火に油を注ぐような、全部で３２０万円ですけれども、商店街の産業振興の視点から、政策的に正しい判断だとは思えないんです。もう一度、ご説明をお願いします。","respondent":"谷田部健康課長","answer":"新規につきましては、１万６,０００円が１万８,３００円ということで、２,３００円の引き上げをするという内容になっています。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問はこれで終わりにしようかと思うんですけれども、保健衛生の水準を確保したいという点から、商店の負担を上げるという、保健衛生をしっかり守る責任は行政にあると思うんですよね。個店のそれぞれの営業実態、状況を、数はわかりませんけれども、状況をしっかり見ていただいて、値上げをするという方向ではない方向が、今求められているんじゃないかなと考えています。これは僕の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問・要望","question":"今のに少し関連するんですけれども、最終的に、この値上げの目的は何ですかというところなんです。今、お話をちょっとお聞きした限り、目的がよくわからないけれども、それをまずは１点、先に確認をさせていただきたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど言っていた商店街活性というところも含めてですけれども、一方ではイベントとかいろいろなところでお金をかけて、それが本当に実態に合っているかどうかというところが問われているというふうに、私は感じているんですけれども、そういう部分で、増収が３２０万円という予算があるんであれば、そこのところを勘案すれば、本当にこの値上げが妥当かどうかというのは疑問なんですけれども。","respondent":"谷田部健康課長","answer":"１件当たり幾らコストがかかるのかというようなことを申し上げますと、１分１秒で細かくは計算することは非常に難しいので、手数料を設定した当時から、平成１０年の改定を踏まえて、それなら今回の状況を見て、当時とは状況が変わっているというところでのお願いです。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"去年と今年でそんなにすごく変わっているようには思えないので、去年、少し様子を見ましょうといって、今回、２区を除きということですから、そういう政策判断をした区もあるというところですので、これは本当に予算的にも３２０万円ということでは、どうなんでしょうかと、すごく疑問なんです。","respondent":"谷田部健康課長","answer":"基本的には、許可を得なければ、こういう商売をやることができないということで、そういう意味で、食品衛生をいかに各営業者一人ひとりが確保していくか、それが本当に合致するかどうかの確認を、保健所が公衆衛生という観点からやるわけですので、許可を取ることを経て。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっとずれているかなと。今、食品はこんなに問われていて、安心安全の食を求める区民の要望というのはあるので、この体制に対してすごく、そちらとして行政がやっていただきたいということは、もちろんわかるんです、やっていただかないと困るということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"阿部委員","kind":"質問・要望","question":"１点だけ。ですから、今後はそのような形で納得できるような理由を最初から示していただきたいと思うんですが、いかがお考えでしょうか。お答えをいただきたいというか、お考えだけお伺いしたいと思います。","respondent":"谷田部健康課長","answer":"そういうふうに、手数料を事細かに、こういう場合については幾らというのはなかなか難しいという状況の中で、今回、平均して１.２倍の改定をお願いするということです。","id":"exchange-044"},{"speaker":"阿部委員","kind":"質問・要望","question":"要は、これからでいいですから、この資料の中において、改正理由として示すときに、年数がどうであるとか、他区がどうであるといった状況を示すのではなくて、ざっくりでいいんですけれども、この数年間のうちに、コストが上がったから手数料も上げるというような理屈であれば、こちらの委員会としても通しやすいですし、逆に、何年経ったから上げるんだというふうな言われ方をしてしまうと。","respondent":"谷田部健康課長","answer":"大変失礼いたしました。先ほど申し上げました部分ですけれども、いわゆるコストの推移のある程度ひな型的なものがお示しできれば、次回、改定をお願いするときには、そういったものも資料としてつけします。","id":"exchange-045"},{"speaker":"宮崎委員","kind":"提案","question":"今の食品衛生のことなんですけれども、そういう資料を出せれば、今議会中になんていうお話なんだけれども、それはちょっと、今、条例を提案している側としたら無責任な説明ですよ。これだけ上がるのが１.２倍になるんだと。じゃあ、一体１.２倍の裏づけは何なんですか。はっきり言ってください。","respondent":"谷田部健康課長","answer":"それで、今回、東京都も、私どもも一定のシミュレーションはしました。中には２倍になっているものもあります。２倍の手数料でお求めするのもご負担が大変ですので、東京都が１.２倍の範囲で押さえましたので、私どもも、東京都と同額で、今回、ご提案申し上げたです。","id":"exchange-046"},{"speaker":"宮崎委員","kind":"質問","question":"ここのところが出てこなければ、これから出せるかどうか検討しますなんて言ったら、条例審査にならないんじゃないですか。先ほど、２区は足並みがそろっていないようなんですけれども、行政の中身で連続性というか、一体的、二人三脚というふうに言われるのかわからないんですけれども、それをやる必要はあると思うんですけれども、料金まで合わせる必要というのは一体何なんですか。どうなんでしょうか。","respondent":"谷田部健康課長","answer":"食品衛生施行条例、これは東京都条例で、先ほどもご説明申し上げました。東京都内、食品衛生法の措置の基準というのが統一にされてあります。ですから、審査する項目、基準がすべて一緒です。そういう中で、同じ許可を受ける場合には、その基準に沿ってやっていく。","id":"exchange-047"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうであれば、コストがどうのこうのなんて言っちゃいけないんですよね。食品衛生のことはおいて、建築確認のことなんですけれども、二つ確認したいんですが、一つはピアチェック機関というのは一体どういう機関なのか。イーホームズの影響で、箱の数としても７０箱とかきて非常に大変だったという話なんですけれども、うちの体制がどうなのかなということを、ちょっと説明いただければと思うんですけれども。","respondent":"片田建築課長","answer":"そんな中で、区の体制についても、現行の体制、特に担当者としては、２人体制で行っていますけれども、そういう意味で、大型物件は少なくなってきているところもありますが、十分に研究しながら事業を行っていますので、今のピアチェックということも仮に出てきたとしても。","id":"exchange-048"},{"speaker":"宮崎委員","kind":"確認","question":"建築確認のほうは、なかなか、正直言って、現場のところは国の関係で、そこで振り回されているなと、私はそういうふうに思っております。そもそも、やっぱり建築確認は今までどおり、規制緩和の前、そういうふうに行政のところでしっかりやるというのが本来のやり方だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"藤田委員","kind":"確認","question":"１点だけです。先ほど、建築課長が、国の責任を明確にするという、再整備をすべきところがあるんではないかということは、よく理解できます。大体わかったんですが、ピアチェック機関を設けるために、手数料を改正するということなんですが、ここだけちょっと教えてください。要するに確認申請から認定するまでの期間というのは、今まで決まっていますよね。それだけ教えてください。","respondent":"片田建築課長","answer":"ただ、今回の法改正の中で、従来、委員のお話にありますように、受け付けてから２１日間ということがございましたけれども、法改正の中では、延ばされて、３５日間と、時間がかかるものについては、プラス３５日、７０日まで建築確認が、法的には。","id":"exchange-050"},{"speaker":"藤田委員","kind":"意見","question":"そうしますと、品川区でも、４５件あるわけですが、これが東京都の中で数多くあると思うんです。東京都の認可をする部分もある。今、３５日延びましたと言っても、その中で収めてくれるのかどうかというのが心配になってくると思うんです。そこら辺の、感触だけで結構です。","respondent":"片田建築課長","answer":"それぞれのピアチェック機関についても、やはりノウハウの違い、あるいは専門分野として若干違いがあるかもしれませんので、そこのところを見て、２３区全体が円滑に回るような仕組みを調整しているという状況です。","id":"exchange-051"},{"speaker":"藤田委員","kind":"質問・要望","question":"そこがちょっと、やはり、どこと契約するかというのは、区としては問題になると思うんです。ですから、全体の中で、２７機関ありますが、その辺の見極めをぜひ慎重にやっていただきたい。これは要望して終わります。","respondent":"福田まちづくり事業部長","answer":"先ほどから、手数料の問題のご質問がかなり出まして、私どもの事業部ともう一つの事業部に共通するお話ですので、特定のご質問に対するお答えではないんですが、全般的にお答えしたいと思います。","id":"exchange-052"},{"speaker":"井上委員","kind":"意見","question":"だから、私たちはここにいるのであって、それが出せません、ご理解くださいというのは、やっぱりその努力があったかどうか、こういうことでここまでは出しましたということが示されなければ、審議に当たるところではないと思うし、部長がそういう発言をするということは、私はおかしいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"意見","question":"私も、まちづくり事業部長がそう言ったので、ちょっと言いたくなっちゃったんですけれども、先ほども言ったんですけれども、それはおかしいんですよ。１.２倍を出すなら、コストがこれだけかかっていると、やっぱりその裏づけが一定程度出てこないとだめ。今定例会中にその資料を出すというお話であれば、それはもう今のこの場に出てなきゃおかしい話なんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"中塚委員","kind":"質問","question":"まちづくり事業部長の今のお話ですけれども、おそらく、地方自治法の第２２４条だか、７条だかの手数料にもかかわるところのことをおっしゃると思うんですけれども、あそこはいわゆるできる規定なんですよね。あくまで、あの条項はできる規定ですから、区の政策でいかようにもすることができる。そこに手数料をかけるか、かけないか、上げるかどうかの判断は区の判断なんですよ。この条文は違いますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問","question":"先ほどの保健衛生関係にかかわる議論の中で、コスト云々の話の中で、補足的な点として、手数料の話を、まちづくり事業部長が説明をしたわけですよね。でも、あの規定というのはできる規定であって、政策的に、しても、しなくても、上げても、下げても、これは区の判断なんですよ。ですから、別に法解釈を聞いているんじゃなくて、さっきの説明の中身は不十分だったんじゃないですかという質問です。","respondent":"福田まちづくり事業部長","answer":"これは、法の解釈の問題です。私が先ほど申し上げたのは、手数料を取るか、取らないかではなくて、手数料の金額は、というふうに申し上げました。これは第１４３条の３です。","id":"exchange-056"},{"speaker":"宮崎委員","kind":"質問","question":"出せると言ったんです。やっぱりそれが手数料を改定する根拠になるわけですから、やっぱりそれを出さないでそのまま通そうなんていうのはちょっと、私はそれを通したら、やっぱりこの委員会自体なんだと言われても仕方ないと思います。ですから、扱いについても、その資料を出すのであれば、出してもらうというふうにしたほうがいいんじゃないかなという意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"藤田委員","kind":"意見","question":"先ほど、ご答弁がありましたように、それぞれがみんな違うわけですよ。この資料を出せと言われても、おそらくあしたには間に合わないんじゃないかと、私は思いますよ。ですので、次の機会に、そうしたものを資料として考えていきたいということですので、それはそれでいいんじゃないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"それで、個々のケースの根拠ではなく、大体平成１９年度の予算で３２０万円ということが出てくるわけですから、そういうふうなことで言えば、８年間で、この食品のこの事業に対してどれだけのコストがかかっていたかということは、多分出していただける、決算書ごとに、そういうことはまとめられていると思いますので、その資料を出していただいて、あしたあるわけですから、扱いとしては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"井上委員","kind":"質問","question":"こういう予算だとか、こういうお金を決める算定に当たって、どういう根拠で算出しているかということは、そちらの課のほうでされていることですから、これを出すに当たった根拠を示してほしいということなので、この中でどういう算定をしているのかがわからない私たちに向かって、こういう資料ですかっていう問いかけは、ちょっと無理があると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問","question":"先ほど、今定例会中に出せるといった資料って一体何なんですか。そこなんですよ。場合によったら、もう１回テープを起こしてみてみる必要があると思うんですけれども。だから、その１.２倍の根拠を示してほしい。それが、先ほど、今定例会中に準備できるという数字とイコールなのか、どうなのかというのは、今はちょっと私のメモがはっきりしないので、よくわからないんですけれども。","respondent":"谷田部健康課長","answer":"今定例会中に、例えば、今回の議案審査に係わる資料の提供は難しいというふうに、私は、先ほど申し上げたつもりです。今、ご議論になっているのは、例えば、標準的なものを二、三、私の答弁の中で、今回、２倍にコストが上がったものもありますと。","id":"exchange-061"},{"speaker":"阿部委員","kind":"質問","question":"確かに、網羅的である必要はないと思いますし、どれか一つについてお示しいただけるということと、それから都のほうのシミュレーションに関するものというのも別にあると考えてよろしいでしょうか。都のシミュレーションのトータルなものと、区の中の取り出して何業種か、主に数が多いようなものが出てくれば、それでもう十分なのかなと、私は感じるんですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"松澤委員","kind":"確認","question":"実は、私どもは、前半部分はちょっと建設委員会になじまない部分であって、建設委員会の部分ということで、建築確認に対することなんですけれども、私たちはこれを審査するに当たって、附帯決議をつけたらどうかということが出ているんです。私どもとしては、この条例を通すに当たっては、建築確認の部分については、附帯決議をつけたいと思うんです。あした、できるんですか。","respondent":"伊藤委員長","answer":"それは最大限生かす形で委員会を運営しながら、効率的な委員会運営を考えていきますと、できれば、この議案については、あした、結論を得た上で、附帯決議までできればと考えています。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"確認","question":"今、言っているのは、建築確認のほうでしょ。うちのほうは、今の意見で、大体こんな感じかなと。今、問題になっているのは食品のほうで、これではちょっと審査がまだ不十分じゃないかということだから、あわせて、あしたやれるんじゃないですか、建築についても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-03","title":"第３０号議案、品川区地区計画の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第３０号議案、品川区地区計画の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"細かいことで、１７分の１２のところで、大崎駅東口第３地区地区整備計画のところで、旧の場合は、平成１４年度に告示された、この再開発地区整備計画をと、こういうふうに変わっているという、特定のエリアだと思うんですけれども、ここのところを、ちょっと説明していただきたいと思います。","respondent":"片田建築課長、青木都市開発課長","answer":"今、２点ほどご質問いただきましたけれども、いずれも該当するところがありますので、説明しますと、平成１４年に都市計画法が改正されまして、以前は再開発等々のことが分れていたところが。１２ページの大崎駅東口第３地区地区整備計画の変更について、ご説明を補足いたします。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回、三つの変更ということかと思うんですけれども、中原街道と、小山台一丁目と、大崎駅東口の、それぞれの整備計画の主な目的と、今回、とられた理由を、繰り返しになるかもしれませんけれども、簡潔にご説明いただきたい。","respondent":"片田建築課長","answer":"大崎駅東口第３地区につきましては、新たに土地利用の変更等々がございましたので、それに合わせた形で整備計画が進められてきたわけですから、それの内容を含めて改正をするという内容です。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"２点目の中原街道は、主に背後にある住宅への回り込みを防ぐ防音の対策というお話ですけれども、２点目は、防災面からということで、それぞれ必要な対策かなとは感じているんですけれども、補助金や、また当事者の本人負担の問題、そこはどういう関係があるのか、ちょっと教えていただきたい。この辺について、教えていただけますか。","respondent":"伊勢住環境整備担当課長、青木都市開発課長","answer":"この２つは、それぞれ東京都のほうで実施している事業ですけれども、一つは、騒音の大きさから、夜間６０dB以上、あるいは昼間ですと７０dB、どちらかの状況が見られる。大崎駅東口第３地区の件について、お答え申し上げます。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"中原街道と小山台で、そういう対応が必要だとは思いますけれども、特に小山台のほうの住民の方々の合意の問題なんですけれども、それぞれ建主の負担も含めて、この間、住民合意はどのように進められてきたのか、教えていただきたい。今、どういう建築物が予定されているのか。今度の制限でどういう中身になるのか、ご説明願います。","respondent":"伊勢住環境整備担当課長、青木都市開発課長","answer":"小山台一丁目のほうですが、特に規制が直接かかります、先ほどの図面のＣのところですけれども、こちらにつきましては、去年の３月、あるいは６月。ちなみに、都市計画決定をするに当たって、事業予定者からご提案をいただいているものは業務ビルです。品川区としては、助成金については、何とか働きかけをしたいですけれども、現在のところ、東京都の助成制度がなくなるということで、難しい状況です。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"中原街道、小山台一丁目、この事業そのものは、それぞれ目的は理解できるんですけれども、住民との間の合意や、また、今後の説明や、それについては十分に丁寧に進めていく必要があるのかなと思います。大崎駅東口ですけれども、業務棟というお話がありましたけれども、規模はどれぐらいなんでしょうか。現時点で、どういう業務棟が考えられるのか。業務棟の内容について、ご説明いただけますか。","respondent":"青木都市開発課長","answer":"今、申し上げましたように、用途については風営法にかかるもの、あるいは、工場等の立地が制限されているですので、業務ビルであれば建築可能であろうと考えております。具体的なものについては、この条例の審議の中では特に把握してございませんので、ご報告できません。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"６００％というのは、要は高さで言うと何ｍの建物なんでしょうか。","respondent":"片田建築課長","answer":"建物の面積等にも関係してくるものですけれども、高さの最低限度ということで、９９ｍということでは考えているわけですけれども、通常、容積率、あるいは建ぺい率の範囲でするということですので、敷地面積がどれほどあるかということを、私も把握してございませんが。","id":"exchange-070"},{"speaker":"中塚委員","kind":"意見","question":"最後に。建築物の高さ最低限度９９ｍとここにありますけれども、この事業は、本当に今必要なのかどうか。やっぱり再検討すべきじゃないかと考えています。","respondent":"青木都市開発課長","answer":"一番最後の資料４、今の議論の９９ｍというところの、資料は、建築物の高さの最低限度となっておりますけれども、これは大変申しわけございません、実際に可決されました審議会での議論の中の地区計画は、「建築物の高さの最高限度を９９ｍ」。","id":"exchange-071"},{"speaker":"宮崎委員","kind":"意見","question":"悩んでいます。東口第３地区のところはちょっとあれなんですが、今回の条例の小山台と中原街道に面した部分については賛成なので、全体としては、もうこれは賛成です。一般的には、大崎駅の再開発はちょっと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"}]},{"id":"topic-04","title":"平成１８年請願第１１号「（仮称）中延６丁目新築工事」建設に関する請願","agenda":"平成１８年請願第１１号「（仮称）中延６丁目新築工事」建設に関する請願","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"住民との話し合いをやっている間に工事が始まったと。区のほうとしては、住民との話し合いというのは、基本的なことだと思うんですけれども、こういうふうに出てきたというのは、区のほうは一体業者のほうにどういうふうに指導、対応をしたのか。","respondent":"齋藤住宅課長","answer":"そういう点でいくと、丁寧にお話し合いに応じるように、業者のほうに話していますし、工事を半年間止めたというのは、事業者のほうでも配慮してくれたんだと理解しております。","id":"exchange-073"},{"speaker":"宮崎委員","kind":"質問","question":"配慮というふうに言えるのかというのは、やっぱり住民のほうは、あれでは納得しないと思うんですけれどもね。やってみたら、ああいう被害が出た、こういう被害が出たとかいっぱいあるわけですから、そういうことはしっかり話し合いをして、例えば、出たらどうするかということを検討していかないと、建築条件とか、状況のあり方も、住民から信頼されなくなってしまうんじゃないかなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"中塚委員","kind":"意見","question":"風害の問題で、シミュレーションした結果、問題ないと、事業者は言うみたいですけれども、この案件だけじゃなくて、建物ができてビル風が強くなったというのは、すべてのビルで多くの人の実感なんですよね。当然、風害に関しても、日照についてもそうですけれども、こういう声が挙がるというのは、やはり建物を建てる建築主の責任が問われてしかるべきではないかと思います。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"井上委員","kind":"意見","question":"紛争予防条例が、区の立場として、住民側の利益につながっているかどうかということを、どのように判断されているのか。この条例が、住民側にとってどうかという評価は、どうされているかということについて。","respondent":"齋藤住宅課長","answer":"ただ、住民の方と事業者で一定の補償の話になっている場合については、我々は関与しません。その使い分けについては、我々は十分に話を聞いておりますので、各案件ごとに適切に対応していると考えております。","id":"exchange-076"},{"speaker":"井上委員","kind":"質問・要望","question":"法令に沿っている限りはどうにもならないというようなところで、だったら、この紛争予防条例は何なのかということになるんだと思うんです。教えていただきたいんですけれども、話し合われている間に、工事が進まないという仕組みは、どういうものをつくればできるのかということがあれば、参考に教えていただきたいんです。","respondent":"齋藤住宅課長","answer":"それは何かと言えば、近隣の方に一定の補償をしないと工事が進めないということになってしまう。要は、法令で認められて建てられるものにつきましては、これを止めるなんていうことは、行政として、条例を設置することはなかなかできない。","id":"exchange-077"},{"speaker":"井上委員","kind":"確認","question":"工事を止めるというよりも、話し合いを持つという前提に、建築確認を申請するという状況の中で、区の要綱だとか、いろいろな基礎になるものにのっとって、業者が法令にのっとって計画を出せるという事前協議は行われているけれども、そのことについての区民への情報提供が一切なく、計画がされてしまって、変更ができない状況で。","respondent":"岩田まちづくり事業部次長","answer":"住民の皆さんが、ある日突然、自分の家の前に大きな建物が建つ計画を知ることによって、今後の生活に対する不満や不安というのが起きるのは当然でありまして、これは、昭和５０年代、いわゆるマンションの林立工事が行われたときに、そういうことが各地区で問題になって。","id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"それからもう一つ、話し合いをすることが必要だということはよくわかるんですけれども、それだけで、住民の側からすれば、努力はしてもらったけれども、結局は何も変わらなかったというようなところで、行政はそれで努力をしたという立場になっているんですけれども、それがどういう結果かというと、何も変わらなかったということになりつつあるということも含めて。","respondent":"齋藤住宅課長","answer":"話し合いということなんですけれども、担当課長として申し上げれば、１２階を６階に下げる、あるいは隣にマンションが建ったから家を建替えなさいと、こういったところからスタートする話し合いと、そういう建築紛争と。","id":"exchange-079"},{"speaker":"松澤委員","kind":"意見","question":"ここは弁護士が入っているから、いろいろとやられているでしょうけれども、そのような話し合いはやっている中で、立ち上がった中で、私たちは、これをどうしようかと大変苦慮しているんです。私たちの仲間も請願署名議員になっていますので、いろいろ苦労しているところがあって、そんな意味で、私もこの現場に関しては業者も相当努力しているなと思ったんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"宮崎委員","kind":"質問","question":"風害というものは、第３者機関なんかで、大体こういう影響が出るとか、そういうふうな調査が必要じゃないかと思うんです。今回、大分企業のほうにも努力したというのはあると思うんですけれども、でも風害というのは、やってみたら、つくってみたらこんなになっちゃうというのが多いものですから、もっと考えていかなきゃいけないと思うんですよ。何か問題意識というのはありますか。","respondent":"齋藤住宅課長、岩田まちづくり事業部次長","answer":"風害のない平穏な生活を受ける権利などというのは、今のところありません。風害に対する補償や基準というのはあります。委員おっしゃるように、中延六丁目は、事業者側の住民への説明資料というのは、ほかでは比較できないぐらい丁寧な資料を用意しております。","id":"exchange-081"},{"speaker":"宮崎委員","kind":"意見","question":"技術的にも、いろいろそれはそれで安価でできるというのはあると思うんですけれども、私はやっぱり、一定基準を、ある意味では第３者機関で認定すると、それに基づいて、つくる側も、住民の側も合意していく。それがすぐにできるとは思いませんけれども、しかるべきところで、検討してもらったほうがいいかなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"宮崎委員","kind":"意見","question":"実際上、もう今期で議会も終わってしまうので、今の推移の状況もありますけれども、やっぱり採択することが必要だと思います。話し合いをやっている間に始めるなんていうことは、やっぱり議会としては、これはだめだということをきちんとしたほうがいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"井上委員","kind":"意見","question":"紹介議員の方たちもこれだけいて、ご賛同いただいているということですし、本当に法令に沿って言えば、なかなか難しいという状況はありますけれども、今期で議会が終わってしまうというところで、廃案というのも、それはちょっとという思いがいたします。こういう問題というのは、議会としてどう考えるかということだと思いますので、私は、採択をするということにしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/668670?Template=document&Id=3874#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":70828,"voices":218}},{"id":"h19-20070226-9","meetingId":"h19-cm02","date":"2007年2月26日","dateIso":"2007-02-26","committee":"文教委員会","time":"午前１０時０３分～午後０時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","topics":[{"id":"topic-01","title":"第３１号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例","agenda":"第３１号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"人事委員会の勧告の中で、職責の違いによる期末手当と勤勉手当を、ちょっとどういう表現だったかわからないんですけど、反映する必要があるみたいなニュアンスがあったんですが、それはどういう事情なんでしょうか。これでいうと、どちらかというと、この条例案では職責についている人を、上に厚く、下に薄くするように読み取れるんですけれども、実際にはどういうことなんでしょうか。","respondent":"市川庶務課長","answer":"その結果、この幼稚園教育職員の給与につきましては、現行の園長を１０％から１２％に上げるということ、これが上に厚くということになる、結果としてはそうなるのかもしれないんですが、ただ、下に薄くということは、少なくともこの改正の趣旨からは。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"本給のほうで、そもそも職責によって差がありますよね。その上に、今度、期末手当と勤勉手当にまた差を上乗せする。これはしようがないといえばしようがないんですけど、二重になるんじゃないのかなという気がするんです。実際に、平均的なものでいいですから、例えば園長と教頭の期末手当と勤勉手当、具体的にはどれぐらいの、１０％から１２％に上げて差に変化があるのか、わかったら教えてほしいんですが。","respondent":"市川庶務課長","answer":"教諭のうち、１０％の適用を受けている者が２人、５％の適用を受けている者が８人。全部で１８人になるわけです。幼稚園教諭全体で、今２５人おりますので、残りの７人は一般教諭ということになります。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"内容に入る前に、幼稚園は教頭と呼んでいるんですか。学校は副校長と呼んでいるんだけど、そこの違いをまず教えていただけますか。","respondent":"河野指導課長","answer":"都のほうは、公立学校に対して、平成１７年４月から、教頭の名称を副校長と変えて、一部、校長がそれまで持っていた権限等を副校長に移したという経緯がありますが、その段階で、既に幼稚園教諭のほうは都の教育委員会の管轄を離れておりましたので、２３区の教育委員会では。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました。今までは。ここのところね。それを、来年度になるわけだけど、上げるという、給与と言っていいかどうかわからないが、加算の部分だから。だけど、そういう流れになっていくというふうに受け取っておいていいわけですか。ここのところ一般の企業の大学初任給が、上がるというような報道もされているんだけど、流れはそういうふうに受けとめていいかどうかを聞かせてください。","respondent":"市川庶務課長","answer":"これは行政職の、先ほど申し上げた見直しの中でも同じです。したがって、一般的な給与のアップということで提案をするよりは、むしろ、総合的な人事給与制度の見直しの一環ということで提案をさせていただいているということで、ご理解いただければと思います。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"さっき、一般職の説明もされて、上限率が変わらないので条例改正は必要ないという内容、今回、中身は変わっているんですか。こういうふうに参考のところに出てきているように、年齢とかで変わりますけど、変わってますね、段階的に上がる、下がる。一般職もこれに準じるということはないけど、これと同じような形になるんですか。","respondent":"市川庶務課長","answer":"先ほども申し上げましたけれども、この実施につきましては、本年の４月１日からということで、来年度からですけれども、そういう見直しをいたします。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"意見","question":"一般職のほうはここで議論する場所ではないというふうに思いますので、中身まで入るのはあれですけど、職務、職責を的確に反映するということを単純に受けとめると、下がるという人は、単に職責、仕事の内容が軽いということは言葉がいけないな、下げても仕方がない内容なのかというふうに受けとめられるんだけど、１つのランク、それから２級の方で。","respondent":"市川庶務課長","answer":"今回、結果として率が下がりますのは、一般教諭のうち、経験年数が３０年以上になる、いわゆるベテラン教諭の処遇が、結果として率を下げることになります。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"最後に短く。もう１つ、上がる人は、園長はあれなんだけれども、教頭職は年齢によって差がなくなるんですよというふうに受けとめるんですが、上がっていって、平成２１年度は同じ１０％になるというふうになっているんだけれども、教頭は年齢に関係なく、仕事をきちんとこなせると見なして、こういう数字に合わせる、そういうふうに理解しておくものなんですか。","respondent":"市川庶務課長","answer":"そのとおりです。","id":"exchange-007"},{"speaker":"築舘委員","kind":"質問","question":"あまりいい質問ではないとは思うんですけど、経験年数が大卒３０年、または短大卒３２年以上ということで、教頭とか教諭が全部説明されているんですね、２級とかいう部分で。これは、大卒、短大卒でないと資格がないということなんでしょうかね。それと、園長はどういうふうに……。","respondent":"市川庶務課長","answer":"園長については、３級と書いてありますけれども、園長になればすべて３級職の取り扱いということで、幼稚園の場合には１級職から３級職までございまして、基本的に適用になっているのは２級職と３級職だけなんですが、園長はすべて３級職の取り扱いということですので。","id":"exchange-008"},{"speaker":"築舘委員","kind":"質問","question":"そうしますと、途中で、例えば大学とか短大を出ていない人で、資格試験みたいなものをとって、幼稚園の先生になりたいというのがあり得るかもしれないんですけど、そういうときは全く認められないということでしょうか。","respondent":"市川庶務課長","answer":"現行、幼稚園教諭の免許の取得ができるのは、短大または大学でそれなりの教育課程を終えた人ということですので、要するに、採用している教諭については、すべて２級職の、大卒または短大卒の教職員だけだということでご理解いただければと思います。","id":"exchange-009"}]},{"id":"topic-02","title":"平成１９年陳情第１号 「就学援助認定者、学校別一覧表は区教委は把握していないという。他区では作る、嘘はだめだ修学旅行等では","agenda":"平成１９年陳情第１号 「就学援助認定者、学校別一覧表は区教委は把握していないという。他区では作る、嘘はだめだ修学旅行等では","exchanges":[{"speaker":"本間委員","kind":"質問・要望","question":"前文のところで、修学旅行等では、１校当たり３００万の補助金が支出されているので、調査を求める陳情というふうに記載されて、裏面のほうでは、４番目で、修学旅行だけで１校当たり約４００万円の税金、中学校があるという点について、もっと具体的な部分でわかることがございましたら、お願いします。","respondent":"古里学務課長","answer":"ただ、総額で申し上げれば、平成１７年度は修学旅行費にかかわる就学援助、これにつきましては、平成１７年度で品川区全体で２,３００万円を３９０名に対し支給をしております。修学旅行に関する就学援助は、１人当たり７万円余ということで支給をしています。","id":"exchange-010"},{"speaker":"本間委員","kind":"質問","question":"この陳情者の金額が、３００万円というのと４００万円というのと、それと同じような形で出ていたものですから、そして、補助金が支出されているという、それでこういう言い方になっている部分なので、例えば、前段を小学校で見たらいいのか、後の４００万円が違うというふうに見ましたが、今のお話で数字が出てきましたので、後でそろばんはじけば、これ、小学校、中学校同じということですね。","respondent":"古里学務課長","answer":"修学旅行は中学校にしかございませんので、中学校に対する支給です。","id":"exchange-011"},{"speaker":"本間委員","kind":"質問","question":"そうしますと、４番目に書いてある部分の、前後してあれなんですが、修学旅行だけで１校当たり４００万円の税金、中学校があるというのは、品川区ということじゃないということですか。","respondent":"古里学務課長","answer":"陳情者とのやりとりの中では、他区の例としておっしゃってあります。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"予算書、決算書見れば出てくるんだろうけど、今、修学旅行の分が２,３００万円で、３９０名ということだった。総額で、全部いろんなものに援助がされているんだけど、１つだけいただく人と、何種類かという人もいらっしゃるんだろうけれども、額でいえば、総額で幾らで、人数でいうと、それらを１つもらっている人、２つもらっている人、ひっくるめて何名というのは、それは出ているんですか。品川区全体で。","respondent":"古里学務課長","answer":"認定者は、いろいろと認定の割合はありますけれども、認定者総数で申し上げますと４,５３８名です。それから、これとは別に就学奨励費、これは養護学校等に通学する児童・生徒たちに出す就学奨励費というものですが、これが連名で７１名です。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"この方は、調査を求める陳情というので、ここでいろいろ聞いていくことも調査なんだろうと思うんだけれども、１校でどのぐらいというか、１人幾ら出ているというのがお知りになりたいのか、全体的にわかりにくいんだけれども、改めてどこを調査するのかという感じも受け取らないんだけど、今のような、品川区全体でどのくらいの方が就学援助を受けていらっしゃるのかというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"陳情者の方が書いていることなので、私も勉強不足なのでわからないんですが、他区では学校別の就学援助の額を出しているというのが、この陳情者の方は言っているんですが、品川区ではつくる必要もないし、つくっていないというはなんですけども、品川区がつくっていない理由をもう少し丁寧に教えていただきたいのと、あと、過去にさかのぼっても。","respondent":"古里学務課長","answer":"私のほうでも、そうしたものがあればご提示したいということで、そのとき答弁をさせていただきましたが、後ほど、当日、終わった後、区議会事務局を含め、協議をさせていただき、学校別に出すことによってプライバシーに直結するおそれがあるということから。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"各校ごとにはつくったことがないということなのか。学校ごとに出すとプライバシーにかかわってくるんじゃないかということなんですが、そこはもう少し丁寧に教えていただけないでしょうか。","respondent":"古里学務課長","answer":"当然、１学年１００名を超す学校もありますけれども、そうした中でこの情報をお出しするということについては、１学年というところまで含めてしまうと個人に直結する可能性がある、プライバシーに触れる情報だということを私どもは認識してございまして。","id":"exchange-016"},{"speaker":"沢田委員","kind":"質問・要望","question":"どうも陳情の趣旨がよくわからないんですけれども、教育委員会のほうに問い合わせというか、話し合いに来たときに、本人は何のために学校別に就学援助の一覧表を求めたか、何をしたいかということはおっしゃっていたんでしょうか。それから、先ほどつくっていないからというと、情報公開の開示請求があって、それに対して不存在という格好で処理というか、出したのかどうか、そこいらを説明してください。","respondent":"古里学務課長","answer":"その時点で、もうこの件についてはお出しが難しいということを申し上げたんですが、情報公開請求は権利がありますので、その請求について、それは昨年末ですが、今年、この情報公開請求の結果について結論をとりにいらっしゃった折り、そういうお話を申し上げましたけれども。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと聞き取れなかったので申しわけないんですが、情報公開請求は出されたんですか。ちょっとそこをもう一度。","respondent":"古里学務課長","answer":"昨年末、情報公開請求を提出されております。それに対して、私どもは当人がいらっしゃったときに、文書が不存在であるということでお話を申し上げましたけれども、その点、ご理解をいただけなかったです。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"この文面を読みますと、税金をこんなに投入してけしからんということが読み取れるんですけど、それにしても、税金を投入しているんだから、学校別に明らかにすべきなんじゃないかというふうに読み取れるんですけど、他区の状況は調査なさっているんでしょうか。他区では学校別にやっているのがどれぐらいあるとか、ないとか、そういうのがあったらお答えいただけますか。","respondent":"古里学務課長","answer":"私ども、他区については調査をいたしておりません。私どもは、ほかの区と違いまして、学校事務システムというシステムにより、口座振替等のシステムを確立しております関係で、学校を経由してこの事務を進めなければならないという条件がございません。","id":"exchange-019"},{"speaker":"沢田委員","kind":"意見","question":"全体の趣旨はわかりますよ。言っている趣旨はあるんだけど、今のところは、必要ありませんのでと、こういう陳情が出てきているときに必要ありませんというのは、木で鼻をくくったみたいな感じだなと。調べたけどこうでしたというのはいいんだけど、調べもしないし、その気もないというのはいただけないなと思いますけど、それは感想だけで、とりあえず終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"今の沢田委員のところでちょっとわからなかったんですか、一たん、昨年末に情報公開の要求の提出があって、それで、一たんその方は帰って、後日改めて来たときに、そういう書類というか、データはありませんという説明をしたということなんですか。その請求があったときにデータがありませんというのは言わなかったんですか。","respondent":"古里学務課長","answer":"その間、私どもはご連絡申し上げるということで電話番号もお聞きしたんですが、その時点では電話番号もお教えいただけなかったために、私どもは結果を持ちながら、陳情者がいらっしゃるのをお待ちしていたということで、２月１３日当日付になってあります。","id":"exchange-021"},{"speaker":"沢田委員","kind":"質問・要望","question":"非常に困る、区側の言うことも、確かにそういうシステムになっているので、学校別に出すことがどうなのかというのもちょっとわかりますし、ただ、できれば我々も他区の状況がどうなのか、他区ではどういう考えでやっているのかを調べてみたいなと思うので、できれば継続にしていただきたいということで、陳情が出ているわけだから、調べてからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"意見","question":"どうして１校幾らを知らなきゃいけないのか、よくわからないところもあるし、あまり触れられたくないような部分も多いと思いますので、願意に沿いがたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"沢田委員","kind":"意見","question":"私はできれば、せっかく陳情が出てきたので、ほかを調べた上でと思ったんですけれども、あえて今の段階で採択か、不採択といえば、学校ごとにやることの問題点も心配されますので、今日採決するということに関しては、これを採択というふうにはいかないということだけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"武内委員","kind":"質問・要望","question":"学校別につくる、なぜそれを求めるかという趣旨がよくわからないのと、今ほかの委員からも出ましたけれども、個別につくったことによって、うがった見方をすると、それが学校選択の１つの情報として、いいほうに働かないというような気がするということと、そういう心配があるということで不採択と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"本間委員","kind":"確認","question":"お話を確認しまして、この陳情者の方の意思を酌み取ろうと努力をしているんですけれども、やはり品川区としては、お話ありましたようにプライバシーに直結するおそれがあるということで、非公開としている中でのやりとりですので、残念ながらこの方の趣旨に対して答えが出せない状態だということですので、不採択で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"専決処分の報告（報告第３号）","agenda":"専決処分の報告（報告第３号）","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"それには責任があるというか、何対何という話ではなくて。お客様が乗っているという意味で、自分だけではないんですから。そういうことで、もう少し教育委員会は、注意の度合いというのかな、それを考えてほしいと思うんですが、いかがですか。","respondent":"古里学務課長","answer":"処分が甘いというふうに思われる向きもありますが、私どもについては、職員がお客様を思ってやっているということ、これから、寒冷地であるということから、通常の道路以外のところは余計に事故が起こりやすいということも含めて、委員のおっしゃったことも含めて。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"確認","question":"もう１つ確認させてください。車は学務課所有の車なんだけど、運転していた方は区の職員ですか。それとも、日光林間側の職員ですか。それだけ聞かせてください。","respondent":"古里学務課長","answer":"運転手は、私どもの区の職員です。","id":"exchange-028"},{"speaker":"武内委員","kind":"質問・要望","question":"参考に教えていただきたいんですけれども、こうして相手方の住所と名前を出すということには何か意味があるんですか。","respondent":"古里学務課長","answer":"これはあくまでも双方の示談でございまして、相手の損害に対して私どもの支払いを行うということで、当然、支払いの相手方を明示せざるを得ないです。要は先ほどの債務を相手方に対して履行するという形になりますので、こういう形にするです。","id":"exchange-029"},{"speaker":"武内委員","kind":"質問","question":"支払い先を明確にということなんでしょうけれども、そうすると事故の場合、双方の名前を出すということは必要ないということでしょうか。見解をお願いします。","respondent":"古里学務課長","answer":"片方の当事者は品川区ですので、あえて品川区をわざわざここには明示をしてございません。ただ、相手方と、当事者は品川区ですので、そういうことでご理解いただいています。","id":"exchange-030"}]},{"id":"topic-04","title":"御殿山小学校・幼稚園に関連する再開発事業","agenda":"御殿山小学校・幼稚園に関連する再開発事業","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"私も２月１０日の説明会には、再開発の説明会に参加したんですが、そこでかなりの高い建物が何棟も建つということがわかったんですけれども、今回は小学校の近くということもありまして、どういう建物をどこにつくるかというのはこれからの検討課題だと思うんですけれども、建物が建った場合の日照の影響が、小学校にとってどれぐらい日陰になるのかという。","respondent":"市川庶務課長","answer":"私どもがこの事業について説明を受ける中で、特に小学校または幼稚園の場合、午前中の日照の確保ということで極力配慮をしていただきたいということを申し入れてきてあります。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"午前中、そういった要望となっているということだと思うんですけれども、具体的にまだこの時点ではどういう日影といいますか、具体的にどういう影響があるかというのはつかんでいらっしゃらないということでしょうか。","respondent":"市川庶務課長","answer":"具体的な日影の時間の説明については受けてございません。これは一定の設計が始まらないとできない話だと思います。","id":"exchange-032"},{"speaker":"沢田委員","kind":"質問","question":"御殿山小学校の学校の運営に大きくかかわる開発ですけれども、ＰＴＡや学校関係者にはこの施設計画について説明はされているんでしょうか。","respondent":"市川庶務課長","answer":"ただ、当然のことながら２月９日、１０日の計画説明会、これが１つの時期の目安となっていますので、いわゆる学校のＰＴＡという組織に対して、学校あるいは教育委員会から説明したということは現状ございません。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"今度の計画でいうと、かなり影響を受けると。今、説明の中で午前中の日照を確保してくれという、校庭だけでいいますと、真南ですから午前中校庭は確保される。開発という都市計画に基づく計画なのに、学校の子どもたちの太陽を奪うというのは、私は真剣になるべきだし、渋谷区なんかでもものすごい運動になって広がっているわけですから、その点はどういうふうに考えているのか。","respondent":"市川庶務課長","answer":"事業者に対してそういったことの説明を求めてしかるべきじゃないかと、これはもうおっしゃるとおりで、私どもはそういうつもりでこれまでも業者の説明を聞き、それに対して教育委員会としての申し入れをしてきたつもりです。","id":"exchange-034"},{"speaker":"沢田委員","kind":"質問・要望","question":"もちろん学校の教職員も含めて、都市計画決定され、その後、事業計画になるともうとまらないわけですから、長くなったからこれでやめますけれども、私はぜひＰＴＡの関係者に日影阻害時間、工事にまつわるいろいろなこともある程度輪郭が出ているでしょうから、そういうことを含めて説明をするということを大急ぎでやっていただきたいと思いますけれども、そこはいかがでしょうか。それだけ聞いて終わります。","respondent":"市川庶務課長","answer":"これが今の校舎にどういう影響を与えるか、これは出せると思います。ただ、これから改築を手がけるときにその場合に現行と比べて日影の影響の差異というものがあるのか、この辺は当然のことながら一定の時期になりましたら説明する必要があると考えています。","id":"exchange-035"},{"speaker":"沢田委員","kind":"質問・要望","question":"おそらくＰＴＡなどに説明したら、いろいろな声が出てきちゃうと思うんです。それは厳密な詳細設計まで至っていないですから、概算にしかならない。これ以上やると時間が長くなるのでやめますけれども、ぜひ、そこは私は区教育委員会として子どもたちに与える影響を、現時点でつかめる範囲をつかんだ上で早急にＰＴＡ、保護者会のほうに説明をしてもらうように要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"意見","question":"図面というか、絵を説明してほしいんだけれども、絵の形でいうと右上にグレーに染められていないコの字型になっている白いところが御殿山小学校、幼稚園の敷地、左下のほうにまた白い部分があるんだけれども、まず御殿山小学校の敷地はどの部分というのを説明してくれますか。","respondent":"市川庶務課長","answer":"要するに御殿山小学校の校庭があって、その先、図でいうと下のところに幼稚園が配置されているです。今回の資料の中で網をかけてある部分がいわゆる北品川五丁目第１地区の再開発事業の区域です。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"学校とは関係ないということで理解しておいていいわけですね。敷地が段になっているというか、極端に高いところと低いところがあって、この説明だと全敷地位置で書いてあるよね。あの高低差は変更しないと考えているんですか。","respondent":"市川庶務課長","answer":"その中でご指摘のあったグラウンドレベルの差が、これは現状では西側のほうに校舎を配置して、東側のほうは体育館、校庭ということになってありますけれども、この辺、校舎のレイアウトをどうすることで、先ほどご指摘にありましたけれども、教育の施設環境というところで。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"これから組合と品川区あるいは教育委員会というのがどういう形で話し合いを進めていくのか。さらに言うと、一番下に幼稚園の部分は無償譲渡されると書いてあるんだけれども、そうすると今ある幼稚園の部分は学校の敷地に組み込んで、御殿山小学校の部分として考え、幼稚園の部分は全く別に組合からもらえるんだというふうに考えておいていいわけですか。","respondent":"市川庶務課長","answer":"これが１つの課題かと考えています。２点目の幼稚園の問題につきましては、少なくとも幼稚園の園舎が現在地から移転をする。ですけれども現在使っている幼稚園の園舎と園庭の部分は基本的に御殿山小学校の用地として使っていく、こういう方針です。","id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問","question":"幼稚園の園庭の確保は、単純に考えると、こっち側に園庭を残すと園舎と離ればなれになっちゃうと、そういうことはないということだけれども、机上の話とすればそういうようなことで、園庭はこれからどういうふうに園舎とつけてつくっていくかということ。それは聞いておきます。幼稚園舎も昭和４６年。それはもう今現在のところでは、教育委員会は了承済みというふうに私たちは理解していいわけですか。","respondent":"市川庶務課長","answer":"やはり、建物の老朽化対応ということ、これがやはり１つの大きな判断要素になって、御殿山小学校の全面改築、こういった結論を出したものです。","id":"exchange-040"},{"speaker":"林（宏）委員","kind":"質問","question":"この後、区単独の事業ではないので難しいところはあるにしても、来年度の平成１９年度に都市計画が決定されると、組合と話し合いながらだけど、即基本計画というところに入っていくというふうに考えてもいい。ということは平成１９年度中に基本計画に入っていくというふうに考えていていいわけですか。","respondent":"市川庶務課長","answer":"校舎の改築につきましては、この市街地再開発事業そのものが、今日お示しした資料ですけれども、平成２１年度着工予定で２４年度の竣工という、一応スケジュール案が今のところ出されてあります。","id":"exchange-041"},{"speaker":"林（宏）委員","kind":"意見","question":"１つだけごめんなさい。そうすると平成２１年度から２４年度、４年間、再開発事業があるわけで、その中で竣工まで終わらせるというふうに考えておいていいわけですね。平成２４年度以降になるということはないと。","respondent":"市川庶務課長","answer":"少なくとも私ども計画部隊としては、そういう目途で現在計画を進めてあります。","id":"exchange-042"}]},{"id":"topic-05","title":"荏原西地区小中一貫校","agenda":"荏原西地区小中一貫校","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"私は先日の荏原第二中学校で行われました説明会に参加させていただいたんですが、今学務課長が言ったようなことも含めての説明はあったんですけれども、それでも今の学校選択制、今の荏原第二中学校を選択するに当たって３年間同じ学業条件で卒業するというのを前提のもとで選択をしてきたわけですから、納得がいかない、理解できませんというような答えがたくさん出ていたのを私が目の当たりにしたのですが。","respondent":"古里学務課長","answer":"ただ、私どもは荏原第二中学校の西地区一貫校がスタートした時点での教育環境、それから将来の西地区の中学校の教育環境ということを考えた中で、現時点で荏原第二中学校が西地区一貫校に合流をしていくことが荏原西地区。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"教育委員会の方からご理解をいただきたいということで再三発言があるんですけれども、２２日の説明会の中でも理解していただきたいという話をされたところ、理解できませんと、はっきり言う父兄の方もいらっしゃいまして、中の質問で私は納得していないので、こういった計画を凍結、変更する可能性はあるんでしょうかというような質問があったんですけれども。","respondent":"古里学務課長","answer":"今の時点で最初の説明と中段の説明が全く違うという矛盾した説明を行政としていたすわけにはまいりませんので、同様の内容で説明をさせていただき、その中でご理解をいただくように私どもは計画の内容を詳細に説明をし、ご理解をいただくように努力をしていく。","id":"exchange-044"},{"speaker":"沢田委員","kind":"意見","question":"いろいろ子どもが減少してきて、学校をどうするかというのは、必然的にどこかで考えなくてはならない問題ですけれども、私は手続きの問題でちょっと聞きたいんですけれども、この方針を荏原第二中学校を含めて母体校とするという方針をいつから検討を始めて、今どの時点に立っているのか、区として決めたのか、区教育委員会として承認をしたのか、そこらは日を追ってどういう段階でこういう方針となったのか。","respondent":"古里学務課長","answer":"これは学校選択が始まる９月の段階で、私どもがそういう情報を出せるかどうかということも含めて検討してきたところですが、最終的な判断については私どもとしては予算編成段階で区教育委員会としての考え方をまとめ、それから区教育委員会としての方針を決定し、予算編成をし。","id":"exchange-045"},{"speaker":"沢田委員","kind":"質問・要望","question":"何月何日、どういう時間で。日を追って説明をしていただきたいと思うんです。だって、これが適正規模だと。１学年４学級と５学級が中学校は好ましいなんて、まだこれから検討するのに、なぜここに盛り込んじゃったのかというのがわからないので、いつの段階でそれを決定したのか日を追って、それから機関はどこの機関で決めたのかというのを説明してくださいと聞いているんです。","respondent":"古里学務課長","answer":"教育委員会の決定としては、２月１３日の教育委員会において、このことを報告をし、決定をさせていただいてあります。","id":"exchange-046"},{"speaker":"沢田委員","kind":"意見","question":"そうすると２月１３日が決定ですよね。だけど、今年のプレス発表は、たしか、２月５日か６日ですけれども、母体校は平塚小学校となっているのは、いきなり説明会、たしか２月６日だったかな。手順がおかしいんじゃないかと思うんです。だって、まず教育委員会の決定があって、それから住民に説明をする。決定は絶対じゃないからね。一体どこで決めたのか。実際のところはどうなっているの。","respondent":"古里学務課長","answer":"事務局の独走ですけれども、私どもは先ほど申し上げたとおり、建設説明会、前回の中での説明、それから地域における今までのご意見、それから荏原第二中学校と平塚中学校の現在の就学の状態、これらを見ながら夏から始めた建設準備会でのさまざまなご意見。","id":"exchange-047"},{"speaker":"沢田委員","kind":"質問・要望","question":"私はそう思います。なぜこんなに拙速にやらなきゃならないのかという問題なんですけれども、これは予算委員会にこのままゆだねるとして、どうしても私が聞きたいのは、これまで学校選択やプラン２１は、学校選びの特色を出して、競争でやるというふうに言ってきたんだけれども、それを目指すものではないんだということを一貫して言ってきましたよね。八潮なんか特に。その点を答弁いただきたいんです。","respondent":"古里学務課長","answer":"したがいまして、私どもは西地区一貫校が一貫校として大きく羽ばたくそのスタート時期、それからさまざまな準備、これを進めていく上では平成２０年４月に新中学校を発足させることは皆さんご異論がない。","id":"exchange-048"},{"speaker":"沢田委員","kind":"質問","question":"これで終わります。最後の１点だけなんですけれども、明確に反対だという声が聞かれれば考えるというニュアンスに聞こえるんですが、それでよろしいでしょうか。長い歴史のあるこの学校をこんな格好で拙速に統合するのは困るという声が多数聞こえるんですけれども、その時点では、安藤委員もさっき言ったんですけれども、もう一度見直しの可能性があるということでよろしいでしょうか。","respondent":"長田教育次長","answer":"もう既にそのときからも声が出ていまして、子どもの数が減っている中でごく至近距離に２校あるというようなことで、これで本当にいいんだろうかというようなことが出されていまして、本来そこから検討が始まりまして、建築、それから一貫校の説明もその時期から始めて。","id":"exchange-049"},{"speaker":"沢田委員","kind":"質問・要望","question":"私の質問に答えていただいていないんですけれども、私の言いたいのは八潮のときに学校選択や小中一貫校、プラン２１は学校統廃合を目指したものではない、だけど、地元から要望があれば、それは別ですと。これは最終的にはそうですよね。だけど、賛成する声は私どもは聞いていない。全部が全部とは言えないかもしれない。当然、私は今までの答弁に対してあると思うんですけれども、いかがでしょうか。","respondent":"長田教育次長","answer":"計画の見直しの問題ですけれども、今まで私どものほうでいろいろな説明会、あるいは地域の方々からのお話し合いですとか、意見を聞く限りでは、そういった反対の声は今までございませんから、当面は今の計画どおりに進めていきたいと考えています。","id":"exchange-050"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は、学校の統廃合が絶対にないとは、するなとは言うつもりはありませんけど、学校の統廃合をやるときには十分な時間と慎重な検討、それから、大方の合意というのを前提にすべきだと思います。次長のほうが、大方の反対の声が表明されれば、そのときは考え直す、考えることもあり得るということで了解しますけれども、ぜひその声を大事にしていただきたいということを求めて、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問","question":"それを無視したような時期にこういうことをやったというのは本当に反省してもらわなきゃいけないと思うんだけど、教育委員会は本当にそういうことを知っているんですか。そういう意味で、時期が非常に悪かったというのは大きな反省点だと思うんだけれども、これからこういう時期にこういう発表をするというのはないんですか。考えなくていいですか。","respondent":"古里学務課長","answer":"ご案内のとおり、来年度以降、さまざまな検討を正式にやっていく過程の中では、絶対そのようなことがないようにしてまいりたいと考えています。","id":"exchange-052"},{"speaker":"林（宏）委員","kind":"意見","question":"長所・短所というのかな、一長一短があるんだろう。荏原第二中学校の場合は京陽小学校だよね、小中一貫教育は。その辺について地域の人たちに、形がこういうふうになるのとは別に、いわゆる、品川の進めている教育という点から、どういうふうに地域の意見、あるいは地域へのお願い、そういうことを始めているのかどうか、その辺を聞かせてください。","respondent":"吉村小中一貫教育担当課長","answer":"もちろん、荏原第一中学校、戸越台中学校についてもこのまま継続していくという形で、今、京陽小学校とは来年度の教育課程について詰めているところです。","id":"exchange-053"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっと待ってください。整理するね。小中一体型の学校と、別々、中学校の場合は別として、小学校の場合は複数の中学校と連携教育をするから、一体型の中学校に当たる部分とも連携はとるんですよという説明として受けていいんですか。","respondent":"吉村小中一貫教育担当課長","answer":"はい、そのとおりです。","id":"exchange-054"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、なぜ一体型の学校が必要なの。もう１つ言うと、一体型の学校でほかの小学校と連携する余裕があるんですか。その辺、説明してください。","respondent":"吉村小中一貫教育担当課長","answer":"１点目の、なぜ一体型が必要なのかということなんですけれども、一体型については、今の６校構想ということで６つつくる予定ですけれども、完全に１つの学校として校長が１名になり、組織も１つの組織として運営する新しい学校形態を考えるものです。","id":"exchange-055"},{"speaker":"林（宏）委員","kind":"意見","question":"そんなの初めて聞いた。そういう説明はきちんとすべきだよ。小中一体型一貫校の教師に余裕が出てきたなんていう話は初めて聞いたよ。一体になるということよりも、ソフト的に、その辺について、きちんと小学校側にも、あるいは今言われた一体型のどこが対応するんだと、受け側というのかな、相手側の中学校にもきちんとしていかなきゃいけないというのはやってほしいんだけど、それを。","respondent":"吉村小中一貫教育担当課長","answer":"それから２点目の、委員のおっしゃる京陽小学校の課題、これは、実はこの話が出たときに、当該の京陽小学校の校長からも私のほうに連絡がありまして、来年度以降の教育課程についてどうしていくかと、これは非常に大きな問題だということで。","id":"exchange-056"},{"speaker":"林（宏）委員","kind":"確認","question":"そういうことまでも教育委員会は配慮しながら、それこそ教育委員会と学校現場と連携をしてということを欠かさないようにしてほしいなというので、それは強くお願いしておきます。聞きたいのは、荏原第二中学校から離れるんだけど、この表の八潮の、せっかくいただいた表なので確認しておきますけど、八潮地区の欄で、開校予定があった後に施設竣工が来るんだけど、これは間違いじゃないの。","respondent":"市川庶務課長","answer":"平成２０年度に、現在の八潮小学校と八潮中学校の校舎の一体化工事を、ほぼ１年かけて行います。その予算を平成１９年度予算の中で、基本設計、実施設計として計上させていただいている、こういうことです。","id":"exchange-057"},{"speaker":"林（宏）委員","kind":"質問","question":"そうなんですか。わかりました。間違いじゃないわけね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169946?Template=document&Id=4598#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":35739,"voices":143}},{"id":"h19-20070226-5","meetingId":"h19-cm02","date":"2007年2月26日","dateIso":"2007-02-26","committee":"総務委員会","time":"午前１０時０３分～午前１１時３５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"の１、議案審査","agenda":"の１、議案審査","exchanges":[{"speaker":"山村委員","kind":"質問","question":"今までの収入役が廃止されて、これからは副区長が２人ということもあるかと思いますけれども、この収入役と助役だった場合と、副区長２人の場合だと、給与とかそういう面ではどういうふうに変わったのかということと、私の勉強不足で申しわけないんですが、イメージとしては、私は今まで、助役ですとか収入役は当然役所の内部の方がなるというイメージで思っているんですけれども、副区長という感じになると。","respondent":"桑村総務課長","answer":"一番最初の、いわゆる収入役をなくして副区長を置くというのは、私の説明がちょっと悪かったかもしれませんけれども、考え方としてちょっと違っておりまして、一つは、収入役が廃止になる理由ですけれども、これまで現金出納あるいは財産管理というのは。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"先ほど説明の中で、助役がこれまでやってきた仕事に比べて、先ほどの説明だと政策、企画ですとか、区長の権限に属する事務の一部について委任を受けるというふうにありましたけれども、これまで助役がやってきた仕事の中で、一つには政策、企画とかということにも、区長と相談をすることなりというのは、当然してきた仕事なんだろうと思うんですけれども。","respondent":"桑村総務課長","answer":"とりあえず、品川の場合においては、やろうとすると告示をして対外的に発表しなきゃいけませんので、今のところと言っても４月１日ですが、やることにはしておりませんので、今後、検討していく課題なのだと思います。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"区長の補佐という助役の役割から、区長と同じように前面に出て行くんだというようなことで、今、最後の方で、４月１日からの改正ということで、区長自身の考えが中心になって流れていくんだということだったんですけれども、ただ、こうしてとにかく助役を廃止して副区長をつくり上げるという条例の変更が行われているわけですから、自治体の考え方として、副区長を置くことによって。","respondent":"桑村総務課長","answer":"それが今度の副区長の役割だ。とは言っても、今、ドラスティックに何を４月１日から変えるかというのは、各団体が非常に検討しているところなんだと思います。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"関連してお聞きしたいんですが、今回、助役を副区長に改めるという条例改正なんですが、こういうふうに地方自治法を改正すると、区の条例もこういうふうに改めて改正するんですが、こういうことって品川区独自でやっている中の職務のことまで地方自治法に左右されちゃうものなんだと思うんですが、何かおかしいなと思うんですけれども、こういうことは結構あるんですか。。わかる範囲で結構です。","respondent":"桑村総務課長","answer":"その意味では、条例自体が果たして有効なのかどうかという疑問もあるでしょうし、その意味では、各団体で自治法の範囲で、全体が国の審議をされて決まった中で、考え方、ものを出されたわけですので、これを押してやるのは。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区もすばらしい自治体だと思うので、その中で自由に裁量を持って、名前も何も助役としなくてもいいんでしょうけど、そういう決め方、こちらのことはこちらで自治を任せていただきたいなという感想もあります。そういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"山村委員","kind":"質問・要望","question":"最初に、定数を超える員数というのは、これは改定するときにこのように変わっていくという理解でいいですか。それが二つ目。それと、最終的に保育士が増で、全体の減が６２ということなんですけれども、これは人数なので、人件費ベースで変わったら、それも教えていただきたいと思います。","respondent":"榎本人事課長","answer":"１点目の定数外の部分ですけれども、これにつきましては、１年以内に解消される予定職ということで、今回の場合には学校の職員３０人ほどがこれに当たっているということです。","id":"exchange-006"},{"speaker":"山村委員","kind":"質問","question":"自動車運転のところで、あとどのぐらい委託化されていないかというか、直営化されているのですか。","respondent":"榎本人事課長","answer":"６名が、今回の退職で４名になってあります。今回２名減です。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"行政評価の中で定数見直しがずっと進んできておりますけれども、民間委託を考える際に、定義みたいなものがあればちょっと教えていただきたいんです。それと、この間の「さけび」に載っていた、これは土木に関係する職員のところでの人員が少なくなっているというような記事が出ていましたけれども、減にするときに、現場の声をどういうふうに反映をされているのか、ちょっとお聞かせ願えますか。","respondent":"榎本人事課長","answer":"最初の委託の部分の定義ですけれども、これはあくまでも人数減が先にあるのではなくて、委託に移行した分を減にという考えですので、区民サービスは減らない限りで事務を効率的にしていこうという考え方がベースにあります。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"どちらかというと区民生活と直結している部分での現業職というんでしょうか、そういう部分での委託が相当量増えているんですけれども、その辺での考え方というのは当然あるんだと思うんですけれども、その辺を教えていただけますか。","respondent":"榎本人事課長","answer":"ただ、その中で気をつけなければいけないのは、民間企業が独占しないような形での委託を考えないと、足元をすくわれるというか、サービスの向上に結びつかないという形がありますので。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"よく区の方で言われる、民間委託することで、直営でやっているよりもサービスがよくなるという話が出てきますけれども、委託先というのは民間企業で商売ですから、契約の内容以上の仕事をするということはあり得ないでしょうし、今、委託をした先のパートなり、契約社員なりがどんどん切りかわっていくということがよく新聞なんかにも出ていますけれども、その辺で考えると、実際に民間に委託したときに。","respondent":"堀越行財政改革担当課長","answer":"民間委託のサービスの検証部分は、今までは仕様書等できめ細かく規定しまして、定期的に報告を受けています。現場の視察等も行っておりますし、そういった中で適正に執行されている、そうした形で運営をしているです。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"今のお話だとよくわからない。検証する際に具体的に項目としてあって、直営よりサービスがよくなっていますよという判断の仕方をするんでしょうけれども、今回の学校給食のところで言えば、どういう具体的なチェック、検証をされているのか。具体的なところを教えてもらいたい。","respondent":"堀越行財政改革担当課長","answer":"サービスが向上している部分もありますし、サービスが充実されて、よりコストが上がっている形というのもありますし、サービスの向上とコストの部分の両立を目標として、民間委託の導入ができるものから進めているという形です。","id":"exchange-011"},{"speaker":"須貝委員","kind":"意見","question":"そこで、今、ほんとうに中枢の部分だと思うんですが、こういうところは、業務委託というよりは何とか品川区の職員がきちっとおさめるような、人員削減ということもあるんでしょうが、逆に安全上の問題も含めて、また何かトラブルがあったときにすぐ対応できるような、情報管理はさまざまにしていると思うんですが、逆に心配する面があるんです。その辺に対してご見解を聞かせてください。","respondent":"小野情報システム課長","answer":"そこではいろいろな機械の保守だとか、あるいはオペレーション、それからシステムの制度改正や何かがあったときの変更だとか、こういうものについては今までも庁舎の中で委託の部分も入れながらやっていたわけですけれども、よりセキュリティの高い建物。","id":"exchange-012"},{"speaker":"菊地委員","kind":"意見","question":"ただ、今お話があった、仕様書の中でこういう業務の委託をしているんだというんですけれども、実際にそれが確実に区民サービスの向上に結びついているのかどうかということがきちんと検証されて、示されるということが必要だと思います。先に課長が言われたコストの問題の部分、どうしてもコストの部分で追求をしているというふうに思います。こういった疑義から、この定数条例については反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"山村委員","kind":"質問・要望","question":"分類とかそういうところは質問してもしようがないので、現在、この手当を払うようなケースというのは年間どのぐらいあるのか。ほとんどないんだとは思うんですけど、それを教えていただきたい。この３類以下の「手当なし」というのは、手当が定められていないというような言われ方をしたと思うんですけど、手当を出さないということの理解でよろしいんですか。","respondent":"榎本人事課長","answer":"実績ですけれども、この感染症の第２類の方の実績が、１７年度の実績ですけれども、年間で２１７件。それから結核の方につきましては１７年度実績は１８件あったです。","id":"exchange-014"},{"speaker":"山村委員","kind":"質問・要望","question":"結核が１８件ということで、２類が年間２１７件ということですけれども、結構自分が持っているですが、この２類の１７年度というのは現行のところを見ればいいと思うんですけれども、大体どれが多いのかというのを教えていただきたいと思います。とりあえず、２類の中でどれが多いんでしょうか。","respondent":"榎本人事課長","answer":"１６年につきましては、細菌性赤痢が６件ということで、そういう患者に接触したので日額が払われたものです。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"教えてもらいたいんですけれども、前区長が２３区の会長をやられていたときに、この問題で法律が改正をされるという前段で、要望書を上げておられましたよね。結核自体がなくなったわけじゃなくて、集団感染の心配があるんだということで、上げられていましたけれども、これはどういうふうに取り扱われたというか、反映されたものなんでしょうか。","respondent":"榎本人事課長","answer":"その要望書の方は、ちょっと存じておりませんけれども、実際上、その法律の中では、結核については２類に該当するということで、かなり重症の部分に移っていますので、決して結核を軽く見ているとかそういうことではないように思います。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"そうすると、職員の体制のところなんですけれども、今までの体制とどういうふうに切りかわるんですか。１類とか２類とかというんですけど、これは専門に１類を扱う職員、２類を扱う職員という体制ではないんだと思うんですけど、その辺の職員の体制だけ教えていただきたい。","respondent":"榎本人事課長","answer":"体制については今後も変わりなく、逆に結核接触が今まで１７０円だったのが、今度は２類ということになりましたので、３２０円ということで、引き上げで充実といえば充実という形になっているものです。","id":"exchange-017"},{"speaker":"原（浩）委員","kind":"質問","question":"平面図が添付されているんですけれども、できれば現場関係図の立面を教えていただければ。今でなくて結構です。なければ後で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"山村委員","kind":"質問","question":"これは聞かずにいられないんですけれども、想定外の障害物を教えてください。","respondent":"宍戸施設担当課長","answer":"木造の校舎の時代の基礎が残っておりまして、木造の校舎を解体するときに基礎まで撤去していたということで当初見込んでいたんですけれども、残っていました。","id":"exchange-019"},{"speaker":"山村委員","kind":"質問","question":"そうすると、それは建築会社側がやり忘れたという感じですか。そういう意味ではミスが起こったと考えられますか。","respondent":"宍戸施設担当課長","answer":"当初、どういうふうな契約になっていてどうかというところまで追いかけ切れないんですけれども、そういう意味では、当初、旧木造校舎の基礎まで撤去しなさいよという契約内容になっていませんので、少なくとも、今回の工事会社の契約というふうなことではございません。","id":"exchange-020"},{"speaker":"山村委員","kind":"意見","question":"それともう一つ。これで工期が１カ月ほどおくれるんですけれども、学校の運営というのはそういう意味ではどういうふうになりますか。","respondent":"宍戸施設担当課長","answer":"４月の開設ですから、校庭が１カ月間使えなくなるという意味では、学校生活に支障が出るんですけれども、運動会、その他、大きい行事には何とか間に合うということで、極力学校側の運営で体育館を活用していただくなど工夫していただいて。","id":"exchange-021"},{"speaker":"原（浩）委員","kind":"確認","question":"関連なんですけれども、今の中で、ここでの契約は飛島建設ですよね。確認なんですけれども、通常、そういったときには施設埋設物の特約条項で、向こうは担保しないよという項目が入っておろうかと思いますので、入っていてこういう結果になっているのであればいいと思うんですけれども、その辺、おわかりになったら教えてください。","respondent":"宍戸施設担当課長","answer":"そもそも、基礎の撤去があるであろう、その中での杭があったとか何とかという細かい部分での変更ではなくて、そもそも、旧木造校舎の時代の基礎そのものがあるということを想定していなかったものですから、その項目自体、契約の中に全く入っていなかった。","id":"exchange-022"},{"speaker":"原（浩）委員","kind":"確認","question":"再確認なんですけど、そうすると、旧建物の敷地に関しては契約等に入っていなかったんですね。整理して伺いますが。","respondent":"宍戸施設担当課長","answer":"今、委員のおっしゃったとおりです。","id":"exchange-023"},{"speaker":"山村委員","kind":"質問","question":"特別区競馬組合の監査委員が３人から２人ということで改正になった。競馬組合としても２人のままで、これは３人にもできるというようなお話だったんですけど、そういうことはせずに、一応２人のままでやることに決まったということでよろしいですか。","respondent":"桑村総務課長","answer":"その理由は、先ほどちょっと申し上げたとおり、平成１５年から企業会計を入れているということがありまして、その意味では、会計事務については会計事務所を入れてきちっとやっているというのが基本にあるようです。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"１点だけ教えてもらいたい。さっきの副区長の話もあるんですけれども、一連の改正の流れの中に、区の場合はさっき言ったように体制強化ということなんでしょうけれども、こういうところの、競馬組合とか厚生事務組合での改正の流れの目的というか、そこだけ教えていただけますか。","respondent":"桑村総務課長","answer":"今回の場合は、人事・厚生事務組合については、法律どおり収入役と、吏員その他の職員を法律どおり変える、競馬組合については、吏員その他の職員は法律どおり変える、監査委員の数については３人というのは置けなくなったものですので、２人の原則に戻して。","id":"exchange-025"},{"speaker":"菊地委員","kind":"提案","question":"本会議でも提案をさせていただきましたけれども、時間をいただいて、議員提出第１号議案の説明をします。改正の主な点は３点あります。それから２点目は、意思形成過程の情報、(5)にあるように「公表しない」というふうにされていますけれども、これを削除したいと考えています。ですから、公開にかかわる事務というのは、一般的な日常事務の範囲内というふうに考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"山村委員","kind":"質問","question":"写しの資料とかそういうのはまた別にいただくということですか。この２ページ目の左の２の、「当該写しの作成および送付に要する費用を負担しなければならない」というような、これはコピー代とかということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"菊地委員","kind":"意見","question":"そうですね。今回は、手数料について無料にしていきたい。コピー代ですとか、テープですとか、そういったものがありますけれども、これは実際に紙代がかかったりテープ代がかかったりしていきますので、この分についてはそのままという形になっています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"ちょっと意見を言わせてください。情報公開に対して、そのたびに費用を無料にするというところはいいのかなという観点はあるんですが、今現在、個人情報保護法等ありまして、個々の案件に対して、じゃあ全部オープンにしていいかどうかというのは、今後も議論が続くところだと思うんですね。そういうふうに考えますと、今回は賛成をいたしかねます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]},{"id":"topic-02","title":"平成１９年請願第２号 ＪＲ不採用問題の早期解決に関する意見書の提出を求める請願","agenda":"平成１９年請願第２号 ＪＲ不採用問題の早期解決に関する意見書の提出を求める請願","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"当時、実は私の兄貴も国鉄の職員でして、当時のことを何となく覚えているんですけれども、中曽根首相の時代だったんですけれども、国会の答弁や何かの中で、中曽根首相自身が「１人も路頭に迷わせない」とか、ちょっと有名になった言葉があるんですけれども、そんなことを言っていました。私どももぜひ意見書を上げていくということを進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"山村委員","kind":"意見","question":"都議会の方でも１２５人中１２４人が提出者になっています。私はなかなか、子どものころの話になってしまって、この辺のことはリアルタイムでよくわかっていないんですが、賛成で、意見書を提出ということでいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"山路委員","kind":"意見","question":"都議会の方で公明党も賛成しておりますので、意見書を提出して、賛成でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"賛成ですが、最高裁はＪＲに不当労働行為の責任はなしと決めたわけですから、意見書の中でどういう内容になるかというと、人道的配慮という言葉しかないと思うこともあるので、正副委員長にぜひ一任をさせていただきたいと思っているんですが、人道上というところの文言はぜひ入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"石田委員長","kind":"質問","question":"後でも申し添えますが、採択となれば正副委員長として必ず案文をつくるわけですから、あす提出するようになりますので、そこでまたご意見をいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問","question":"私も、国会および政府に対して、ＪＲ不採用問題の早期解決に向けて、関係者に働きかけるように努力を要請するということですから、このことについては人道上問題なので、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/396657?Template=document&Id=1746#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":27625,"voices":149}}]);
